#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void hinge_loss_kernel(const half* predictions, const half* targets, half* output, int64_t total_elements) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // Compute 1 - predictions[i] * targets[i]
        half prod = __hmul(predictions[idx], targets[idx]);
        half clamp_val = __hsub(half(1.0f), prod);

        // Clamp to minimum 0
        half result = __hmax(clamp_val, half(0.0f));

        // Store result
        output[idx] = result;
    }
}

__global__ void reduce_mean_kernel(const half* input, half* output, int64_t n) {
    extern __shared__ half sdata[];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Load data into shared memory
    sdata[tid] = (idx < n) ? input[idx] : __float2half(0.0f);
    __syncthreads();

    // Perform reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = __hadd(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    // Write result for this block to global memory
    if (tid == 0) {
        atomicAdd(output, sdata[0]);
    }
}

// Main function to compute hinge loss
extern "C" void compute_hinge_loss(const half* predictions, const half* targets, half* output, int64_t batch_size, int64_t elements_per_sample) {
    int64_t total_elements = batch_size * elements_per_sample;

    // Step 1: Compute hinge loss for each element
    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    // Allocate temporary storage for intermediate results
    half* temp_output;
    cudaMalloc(&temp_output, total_elements * sizeof(half));

    // Launch kernel to compute hinge loss
    hinge_loss_kernel<<<grid_size, block_size>>>(
        predictions, targets, temp_output, total_elements
    );

    // Step 2: Reduce to mean
    // For simplicity, we'll use a single block for reduction since we're dealing with large arrays
    half* final_result;
    cudaMalloc(&final_result, sizeof(half));
    cudaMemset(final_result, 0, sizeof(half));

    // Use a single block for reduction since we're dealing with large arrays
    int num_blocks = 1;
    int shared_mem_size = block_size * sizeof(half);

    reduce_mean_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        temp_output, final_result, total_elements
    );

    // Copy result back to host or return appropriately
    half result_value;
    cudaMemcpy(&result_value, final_result, sizeof(half), cudaMemcpyDeviceToHost);

    // Divide by total_elements to get mean
    half mean_result = __hdiv(result_value, __float2half(static_cast<float>(total_elements)));

    // Copy final result back to output
    cudaMemcpy(output, &mean_result, sizeof(half), cudaMemcpyHostToDevice);

    // Cleanup
    cudaFree(temp_output);
    cudaFree(final_result);
}
