                             const __half* __restrict__ targ,
                             float* __restrict__ out_sum,
                             int64_t total) {
    float thread_sum = 0.0f;

    // stride over the input vectors
    for (int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
         idx < total;
         idx += (int64_t)blockDim.x * gridDim.x) {
