    // block‑level reduction in shared memory (max 1024 threads)
    __shared__ float shmem[1024];
    shmem[threadIdx.x] = thread_sum;
    __syncthreads();

    // reduction tree
    for (unsigned int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shmem[threadIdx.x] += shmem[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // atomic add the block result to global accumulator
    if (threadIdx.x == 0) {
        atomicAdd(out_sum, shmem[0]);
