import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------------- #
# CUDA kernel (WMMA based FP16 GEMM: C = A @ B.T)
# --------------------------------------------------------------------------- #
_cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

// WMMA tile dimensions
constexpr int WMMA_M = 16;
constexpr int WMMA_N = 16;
constexpr int WMMA_K = 16;

// Thread block tile size (must be multiple of WMMA tile)
constexpr int TILE_M = 64;   // 4 WMMA_M tiles (rows)
constexpr int TILE_N = 64;   // 4 WMMA_N tiles (cols)

// Kernel: each block computes a TILE_M x TILE_N output tile
__global__ void gemm_wmma_fp16_kernel(const __half* __restrict__ A,
                                      const __half* __restrict__ B,
                                      __half* __restrict__ C,
                                      int M, int N, int K) {
    // block origin (row, col) in output matrix C
    const int block_row = blockIdx.y * TILE_M;
    const int block_col = blockIdx.x * TILE_N;

    // each warp computes one WMMA_M x WMMA_N tile
    const int warp_id = threadIdx.x / 32;          // 0..3 (128 threads per block)
    const int lane_id = threadIdx.x % 32;          // not used directly

    const int warp_row = warp_id / 2; // 0..1
    const int warp_col = warp_id % 2; // 0..1

    // top‑left corner of the WMMA tile this warp will compute
    const int a_row = block_row + warp_row * WMMA_M; // row in A / C
    const int b_col = block_col + warp_col * WMMA_N; // column in B (after transpose)

    // Declare WMMA fragments
    wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K,
                   __half, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K,
                   __half, wmma::col_major> b_frag;
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K,
                   __half, void> acc_frag;

    // Initialise accumulator to zero
    wmma::fill_fragment(acc_frag, __float2half(0.0f));

    // Loop over K dimension in WMMA_K sized steps
    for (int k_tile = 0; k_tile < K; k_tile += WMMA_K) {
        // Pointers to the current sub‑matrices
        const __half* a_ptr = A + (a_row * K) + k_tile;                     // A is row‑major
        // B is stored row‑major as (N, K). We need B^T (K, N) column‑major.
        // For column‑major layout the leading dimension is K.
        const __half* b_ptr = B + (b_col * K) + k_tile;                     // reinterpret as col‑major

        // Load tiles into WMMA fragments
        wmma::load_matrix_sync(a_frag, a_ptr, K);
        wmma::load_matrix_sync(b_frag, b_ptr, K);

        // Perform the matrix multiply‑accumulate
        wmma::mma_sync(acc_frag, a_frag, b_frag, acc_frag);
    }

    // Store the result tile to C (row‑major)
    __half* c_ptr = C + (a_row * N) + b_col;
    wmma::store_matrix_sync(c_ptr, acc_frag, N, wmma::mem_row_major);
}

// Launcher wrapper
void launch_gemm_fp16(const at::Half* A,
                      const at::Half* B,
                      at::Half* C,
                      int64_t M, int64_t N, int64_t K) {
    dim3 block(128);   // 4 warps per block
    dim3 grid((N + TILE_N - 1) / TILE_N,
              (M + TILE_M - 1) / TILE_M);

    gemm_wmma_fp16_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A),
