    int col = blockIdx.x * blockDim.x + threadIdx.x;   // [0, N)

    if (row >= M || col >= N) return;

    float acc = 0.0f;   // fp32 accumulation for accuracy
    for (int k = 0; k < K; ++k) {
        __half a = A[row * K + k];
        __half b = B[col * K + k];            // B stored as N x K
        acc += __half2float(a) * __half2float(b);
