# ---------------------------------------------------------------------------
_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

constexpr int WMMA_M = 16;
constexpr int WMMA_N = 16;
constexpr int WMMA_K = 16;

constexpr int WARPS_PER_BLOCK = 4;
constexpr int THREADS_PER_BLOCK = WARPS_PER_BLOCK * 32;

__global__ void matmul_wmma_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int M, int N, int K) {
    const int warp_id = threadIdx.x / 32;               // [0, WARPS_PER_BLOCK)
    const int m_tile  = blockIdx.y * WARPS_PER_BLOCK + warp_id; // row tile index
    const int n_tile  = blockIdx.x;                     // col tile index

    if (m_tile * WMMA_M >= M || n_tile * WMMA_N >= N) return;

    // WMMA fragments
    wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, wmma::col_major> b_frag;
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag;

    wmma::fill_fragment(acc_frag, 0.0f);

    // Loop over K dimension tiles
    for (int k_tile = 0; k_tile < K; k_tile += WMMA_K) {
        const __half* a_ptr = A + (m_tile * WMMA_M) * K + k_tile;   // A is (M, K) row‑major
        const __half* b_ptr = B + (n_tile * WMMA_N) * K + k_tile;   // B is (N, K) row‑major; we treat it as transposed

        wmma::load_matrix_sync(a_frag, a_ptr, K);
        wmma::load_matrix_sync(b_frag, b_ptr, K);   // col‑major load matches Bᵀ layout

        wmma::mma_sync(acc_frag, a_frag, b_frag, acc_frag);
    }

    // Convert accumulator (float) to half and store to C
    float tmp[WMMA_M * WMMA_N];
    wmma::store_matrix_sync(tmp, acc_frag, WMMA_N, wmma::mem_row_major);

    __half* c_ptr = C + (m_tile * WMMA_M) * N + n_tile * WMMA_N;
    #pragma unroll
    for (int i = 0; i < WMMA_M; ++i) {
        #pragma unroll
        for (int j = 0; j < WMMA_N; ++j) {
            int idx = i * WMMA_N + j;
            c_ptr[i * N + j] = __float2half_rn(tmp[idx]);
        }
    }
}

