    const int K = A.size(1);
    const int N = B.size(0);   // B shape is (N, K)

    dim3 blockDim(THREADS_PER_BLOCK);
    dim3 gridDim( (N + WMMA_N - 1) / WMMA_N,
                  (M + (WMMA_M * WARPS_PER_BLOCK) - 1) / (WMMA_M * WARPS_PER_BLOCK) );

    matmul_wmma_kernel<<<gridDim, blockDim>>>(
        reinterpret_cast<const __half*>(A.data_ptr()),
        reinterpret_cast<const __half*>(B.data_ptr()),
        reinterpret_cast<__half*>(C.data_ptr()),
