cpp_source = r'''
#include <torch/extension.h>

// Declaration of the CUDA launcher (definition lives in the .cu file)
void matmul_fp16_launcher(at::Tensor A, at::Tensor B, at::Tensor C);

// Expose the launcher to Python
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16_launcher", &matmul_fp16_launcher,
          "FP16 matrix multiplication A @ B.T");
