# --------------------------------------------------------------------
# CUDA implementation (compiled with nvcc)
# --------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef TILE_SIZE
#define TILE_SIZE 16
#endif

// --------------------------------------------------------------------
// Kernel: C = A (M×K) * Bᵀ (K×N)   where B is stored as (N×K)
// --------------------------------------------------------------------
__global__ void matmul_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int M, int K, int N) {
    int tx = threadIdx.x;                       // column inside tile
    int ty = threadIdx.y;                       // row inside tile
    int row = blockIdx.y * TILE_SIZE + ty;      // global row index in C
    int col = blockIdx.x * TILE_SIZE + tx;      // global col index in C

    __shared__ half As[TILE_SIZE][TILE_SIZE];
    __shared__ half Bs[TILE_SIZE][TILE_SIZE];

    float acc = 0.0f;                           // FP32 accumulator
    int numTiles = (K + TILE_SIZE - 1) / TILE_SIZE;

    for (int t = 0; t < numTiles; ++t) {
        // Load tile of A (row‑major)
        int aRow = row;
        int aCol = t * TILE_SIZE + tx;
        As[ty][tx] = (aRow < M && aCol < K) ?
                     A[aRow * K + aCol] : __float2half(0.0f);

        // Load tile of B (stored as N×K). We need Bᵀ, so element (col,row)
        // corresponds to B[row, col] in the original layout.
        int bRow = col;                         // original row index in B (N dim)
        int bCol = t * TILE_SIZE + ty;          // original column index in B (K dim)
        Bs[ty][tx] = (bRow < N && bCol < K) ?
                     B[bRow * K + bCol] : __float2half(0.0f);

        __syncthreads();

        #pragma unroll
        for (int i = 0; i < TILE_SIZE; ++i) {
            acc += __half2float(As[ty][i]) * __half2float(Bs[i][tx]);
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// --------------------------------------------------------------------
// Launcher (exposed to Python)
// --------------------------------------------------------------------
void matmul_fp16_launcher(at::Tensor A, at::Tensor B, at::Tensor C) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda() && C.is_cuda(),
                "All tensors must be CUDA");
    TORCH_CHECK(A.dtype() == at::kHalf && B.dtype() == at::kHalf && C.dtype() == at::kHalf,
                "All tensors must be half (fp16)");

    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(0);   // B shape is (N, K)

    const dim3 block(TILE_SIZE, TILE_SIZE);
    const dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE,
                    (M + TILE_SIZE - 1) / TILE_SIZE);

    const half* a_ptr = reinterpret_cast<const half*>(A.data_ptr<at::Half>());
    const half* b_ptr = reinterpret_cast<const half*>(B.data_ptr<at::Half>());
    half* c_ptr = reinterpret_cast<half*>(C.data_ptr<at::Half>());

    matmul_fp16_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        a_ptr, b_ptr, c_ptr, M, K, N);
    AT_CUDA_CHECK(cudaGetLastError());
}
'''

