#include <cuda_fp16.h>
#include <ATen/ATen.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_INPUT
#define CHECK_INPUT(x) \
  CHECK_CUDA(x);       \
  CHECK_CONTIGUOUS(x);
#endif

// -----------------------------------------------------------------------------
// Kernel: vectorised half2 ReLU with reduced launch overhead
// -----------------------------------------------------------------------------
template <int TPB>
__global__ void relu_fp16_kernel(const __half* __restrict__ in,
                                 __half* __restrict__ out,
                                 size_t half2_len,
                                 bool has_tail) {
    const size_t tid = threadIdx.x;
    const size_t idx = blockIdx.x * TPB + tid;
    const size_t stride = gridDim.x * TPB;
    const __half2 zero2 = __float2half2_rn(0.0f);

    // reinterpret as half2 pointers (process two fp16 per iteration)
    const __half2* __restrict__ in2  = reinterpret_cast<const __half2*>(in);
    __half2*       __restrict__ out2 = reinterpret_cast<__half2*>(out);

    // main vectorised loop
    for (size_t i = idx; i < half2_len; i += stride) {
        // __ldg may help with read‑only cache on A100
        const __half2 v = __ldg(in2 + i);
        out2[i] = __hmax2(v, zero2);
    }

    // tail element (odd total number of fp16)
    if (has_tail) {
        // Only one thread (tid==0) needs to handle the final element
        const size_t tail_idx = half2_len * 2; // index of the lone fp16
        if (tid == 0) {
            __half x = in[tail_idx];
            // x > 0 ? x : 0
            out[tail_idx] = __hgt(x, __float2half(0.0f)) ? x : __float2half(0.0f);
        }
    }
}

// -----------------------------------------------------------------------------
// Host wrapper
// -----------------------------------------------------------------------------
void relu_fp16_forward(torch::Tensor input, torch::Tensor output) {
    CHECK_INPUT(input);
    CHECK_INPUT(output);
    TORCH_CHECK(input.dtype() == torch::kHalf,
                "input must be FP16 (torch.float16)");
    TORCH_CHECK(output.dtype() == torch::kHalf,
                "output must be FP16 (torch.float16)");
    TORCH_CHECK(input.numel() == output.numel(),
