//------------------------------------------------------------------------------
// ReLU kernel for fp16 using half2 vectorization and a grid‑stride loop.
//------------------------------------------------------------------------------
template <int TPB>
__global__ void relu_fp16_kernel(const __half* __restrict__ in,
                                 __half* __restrict__ out,
                                 size_t total_half2) {
    const size_t idx = blockIdx.x * TPB + threadIdx.x;
    const size_t stride = gridDim.x * TPB;

    const __half2* __restrict__ in2  = reinterpret_cast<const __half2*>(in);
    __half2*       __restrict__ out2 = reinterpret_cast<__half2*>(out);
    const __half2 zero2 = __float2half2_rn(0.0f);

    // Vectorized part (process two elements per iteration)
    for (size_t i = idx; i < total_half2; i += stride) {
        // Load through texture cache (read‑only) for higher bandwidth
        const __half2 v = __ldg(in2 + i);
        // Mask: 0xFFFF where v > 0, else 0
        const __half2 mask = __hgt2(v, zero2);
        // Keep positive lanes, zero the rest
        out2[i] = __hmul2(mask, v);
    }

    // Handle the possible trailing element (odd total length)
    if ((total_half2 * 2ULL) < (size_t)gridDim.x * TPB) {
        // Only one thread (thread 0 of block 0) needs to do the tail work
        if (idx == 0) {
            const size_t total = total_half2 * 2ULL;
            if (total % 2ULL) {
                const size_t last = total - 1ULL;
                const __half x = in[last];
                out[last] = __hgt(x, __float2half(0.0f)) ? x : __float2half(0.0f);
            }
        }
    }
}

