import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# C++ declarations
# ----------------------------------------------------------------------
cpp_src = r'''
#include <torch/extension.h>

// Launcher declaration
void matmul_fp16(torch::Tensor A,
                 torch::Tensor B,
                 torch::Tensor C);
'''

# ----------------------------------------------------------------------
# CUDA kernel (simple tiled fp16 GEMM, float accumulation)
# ----------------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE_M 32
#define TILE_N 32
#define TILE_K 32

// ------------------------------------------------------------------
// Kernel: C = A * B  (row‑major, fp16 inputs, fp16 output, fp32 acc)
// ------------------------------------------------------------------
__global__ void matmul_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int N) {
    // Thread indices within the block
    const int tx = threadIdx.x; // 0 .. TILE_N-1
    const int ty = threadIdx.y; // 0 .. TILE_M-1

    // Global row & col of the element computed by this thread
    const int row = blockIdx.y * TILE_M + ty;
    const int col = blockIdx.x * TILE_N + tx;

    // Shared memory for tiles of A and B
    extern __shared__ half shared[];
    half* As = shared;                                     // TILE_M x TILE_K
    half* Bs = shared + TILE_M * TILE_K;                   // TILE_K x TILE_N

    float acc = 0.0f;

    for (int k0 = 0; k0 < N; k0 += TILE_K) {
        // Load A tile (row‑major) into shared memory
        int a_row = row;
        int a_col = k0 + tx;
        As[ty * TILE_K + tx] = (a_row < N && a_col < N)
                                   ? A[a_row * N + a_col]
                                   : __float2half(0.0f);

        // Load B tile (row‑major) into shared memory
        int b_row = k0 + ty;
        int b_col = col;
        Bs[ty * TILE_N + tx] = (b_row < N && b_col < N)
                                   ? B[b_row * N + b_col]
                                   : __float2half(0.0f);

        __syncthreads();

        // Compute partial product for this tile
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            acc += __half2float(As[ty * TILE_K + kk]) *
                   __half2float(Bs[kk * TILE_N + tx]);
        }

        __syncthreads();
    }

    // Write result
    if (row < N && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// Launcher exposed to Python
// ------------------------------------------------------------------
void matmul_fp16(torch::Tensor A,
                 torch::Tensor B,
                 torch::Tensor C) {
    const int N = A.size(0);
    TORCH_CHECK(A.is_cuda() && B.is_cuda() && C.is_cuda(),
                "All tensors must be CUDA tensors");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous() && C.is_contiguous(),
                "All tensors must be contiguous");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf && C.dtype() == torch::kHalf,
                "All tensors must be float16");
    TORCH_CHECK(A.dim() == 2 && A.size(0) == A.size(1),
                "Only square 2‑D matrices are supported");
    TORCH_CHECK(A.sizes() == B.sizes() && A.sizes() == C.sizes(),
                "All tensors must have the same shape");

    dim3 block(TILE_N, TILE_M); // (32,32) = 1024 threads per block (fits on A100)
    dim3 grid((N + TILE_N - 1) / TILE_N,
              (N + TILE_M - 1) / TILE_M);
    size_t shmem_bytes = 2 * TILE_M * TILE_K * sizeof(half); // As + Bs

    matmul_fp16_kernel<<<grid, block, shmem_bytes>>>(
        reinterpret_cast<const half*>(A.data_ptr()),
        reinterpret_cast<const half*>(B.data_ptr()),
        reinterpret_cast<half*>(C.data_ptr()),
        N);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch failed: ") +
                                 cudaGetErrorString(err));
    }
}
'''

# ----------------------------------------------------------------------
# Compile the inline extension
# ----------------------------------------------------------------------
matmul_ext = load_inline(
    name='matmul_fp16_ext',
    cpp_sources=[cpp_src],
    cuda_sources=[cuda_src],
    functions=['matmul_fp16'],
    verbose=False,
)

# ----------------------------------------------------------------------
# Autograd Function wrapping the custom kernel
# ----------------------------------------------------------------------
class MatMulFP16Function(torch.autograd.Function):
    @staticmethod
    def forward(ctx, A, B):
        N = A.size(0)
        A = A.contiguous()
        B = B.contiguous()
        C = torch.empty_like(A, dtype=torch.float16, device='cuda')
        # Use custom kernel when dimensions are multiples of 32 (tile size)
        if N % 32 == 0:
            matmul_ext.matmul_fp16(A, B, C)
        else:
            C = torch.matmul(A, B)  # fallback
        ctx.save_for_backward(A, B)
        return C

    @staticmethod
    def backward(ctx, grad_output):
        A, B = ctx.saved_tensors
