// Launcher
// ---------------------------------------------------------------
void launch_matmul_fp16(const __half* A,
                        const __half* B,
                        __half* C,
                        int N) {
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    matmul_fp16_kernel<<<grid, block, 0,
                         at::cuda::getCurrentCUDAStream()>>>(A, B, C, N);
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA launch error: %s\\n", cudaGetErrorString(err));
