// Vectorized sigmoid kernel for fp16 (process 2 elements per thread)
// Uses fast math on float2 after converting from half2.
// ---------------------------------------------------------------------
template <int VecSize>
__global__ __launch_bounds__(1024, 2)
void sigmoid_kernel_half2(const __half* __restrict__ input,
                          __half* __restrict__ output,
                          int64_t N) {
    // number of half2 elements (pairs)
    int64_t total_pairs = N / 2;               // floor(N/2)

    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = blockDim.x * gridDim.x;

    const __half2* __restrict__ in2_ptr  = reinterpret_cast<const __half2*>(input);
    __half2*       __restrict__ out2_ptr = reinterpret_cast<__half2*>(output);

    // each thread processes VecSize half2 values per iteration
    for (int64_t i = idx; i < total_pairs; i += stride) {
        #pragma unroll
        for (int v = 0; v < VecSize; ++v) {
            int64_t pair_idx = i + v * stride;
