    if (N & 1) {
        int64_t last_idx = N - 1;
        if (idx == 0) { // only one thread writes the tail
            float x = __half2float(input[last_idx]);
            float y = __fdividef(1.0f, 1.0f + __expf(-x));
            output[last_idx] = __float2half_rn(y);
