__launch_bounds__(THREADS_PER_BLOCK) void swish_kernel(const __half* __restrict__ input,
                                                       __half* __restrict__ output,
                                                       int64_t N) {
    const int64_t half2_cnt = (N + 1) >> 1;          // ceil(N/2)
    const int64_t tid   = threadIdx.x;
    const int64_t stride = blockDim.x * gridDim.x;
    int64_t idx = blockIdx.x * blockDim.x + tid;    // half2 index

