    // Origin of the CTA's output tile
    const int tile_m = blockIdx.y * BLOCK_M;
    const int tile_n = blockIdx.x * BLOCK_N;

    // Shared memory partitions
    half* shmem_A = shared_mem;                                   // BLOCK_M x BLOCK_K
    half* shmem_B = shmem_A + BLOCK_M * BLOCK_K;                  // BLOCK_K x BLOCK_N

