        for (int i = threadIdx.y; i < BLOCK_K; i += blockDim.y) {
            for (int j = threadIdx.x; j < BLOCK_N; j += blockDim.x) {
                int row = tile_k + i;
                int col = tile_n + j;
                half val = (row < K && col < N) ? B[row * N + col] : __float2half(0.0f);
                shmem_B[i * BLOCK_N + j] = val;
