        // Compute product for the tile
        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            acc += __half2float(As[threadRow][k]) *
                   __half2float(Bs[k][threadCol]);
        }

        __syncthreads();
    }

    // Write result (with bounds check)
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
