# C++ source – implements half‑precision GEMM via cuBLAS Tensor Cores
# ---------------------------------------------------------------------------
_cpp_source = r'''
#include <torch/extension.h>
#include <cublas_v2.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

// ---------------------------------------------------------------------------
// Launcher that calls cuBLAS GEMM (row‑major emulated with transposes)
// ---------------------------------------------------------------------------
void matmul_fp16_launcher(const torch::Tensor& A,
                          const torch::Tensor& B,
                          torch::Tensor& C) {
    // cuBLAS handle
    cublasHandle_t handle;
    cublasCreate(&handle);
    // Enable Tensor Core ops
    cublasSetMathMode(handle, CUBLAS_TENSOR_OP_MATH);

    const half* A_ptr = reinterpret_cast<const half*>(A.data_ptr<torch::Half>());
    const half* B_ptr = reinterpret_cast<const half*>(B.data_ptr<torch::Half>());
    half*       C_ptr = reinterpret_cast<half*>(C.data_ptr<torch::Half>());

    int M = static_cast<int>(A.size(0));
    int K = static_cast<int>(A.size(1));
    int N = static_cast<int>(B.size(1));

    const float alpha = 1.0f;
    const float beta  = 0.0f;

    // cuBLAS assumes column‑major layout.  PyTorch tensors are row‑major,
    // so we compute Cᵀ = Bᵀ * Aᵀ (both transposed) which yields the same
    // result as C = A * B in row‑major order.
    cublasStatus_t status = cublasGemmEx(
        handle,
        CUBLAS_OP_T,               // opB  (Bᵀ)
        CUBLAS_OP_T,               // opA  (Aᵀ)
        N,                         // m = cols of Bᵀ
        M,                         // n = rows of Aᵀ
        K,                         // k = shared dim
        &alpha,
        B_ptr, CUDA_R_16F, N,      // Bᵀ, leading dim = N
        A_ptr, CUDA_R_16F, K,      // Aᵀ, leading dim = K
        &beta,
        C_ptr, CUDA_R_16F, N,      // Cᵀ, leading dim = N
        CUDA_R_32F,                // compute in FP32
        CUBLAS_GEMM_DEFAULT_TENSOR_OP);

    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS,
                "cublasGemmEx failed with error code ", status);

    cublasDestroy(handle);
}

// ---------------------------------------------------------------------------
// Public wrapper exposed to Python
// ---------------------------------------------------------------------------
torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "Both inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "Both inputs must be float16 (torch.half)");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "Both inputs must be 2‑D matrices");
    TORCH_CHECK(A.size(1) == B.size(0),
                "Inner dimensions must match for matrix multiplication");

    auto options = torch::TensorOptions()
                       .dtype(torch::kHalf)
                       .device(A.device());

    torch::Tensor C = torch::empty({A.size(0), B.size(1)}, options);
    matmul_fp16_launcher(A, B, C);
    return C;
}

// ---------------------------------------------------------------------------
// PyBind11 module definition
// ---------------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16,
          "Half‑precision matrix multiplication using cuBLAS Tensor Cores");
}
'''

# Compile the extension (no CUDA source needed – cuBLAS is a host API)
_matmul_ext = load_inline(name='matmul_fp16_ext',
                          cpp_sources=[_cpp_source],
                          functions=['matmul_fp16'],
                          verbose=False)

