    """
    Replacement for the reference Model that uses the custom half‑precision
    GEMM implemented above.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Convert inputs to CUDA half‑precision, ensure contiguity
        A_fp16 = A.to(dtype=torch.float16, device='cuda').contiguous()
        B_fp16 = B.to(dtype=torch.float16, device='cuda').contiguous()
        # Invoke the compiled kernel
        return _matmul_ext.matmul_fp16(A_fp16, B_fp16)

