__global__ void compute_mean_kernel(const __half* __restrict__ input,
                                    float* __restrict__ mean,
                                    int N, int C, int H, int W) {
    int c = blockIdx.x;                     // channel index
    int elems_per_channel = N * H * W;      // number of elements for this channel
    float sum = 0.0f;

