    for (int stride = TPB / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sh_sum[threadIdx.x]  += sh_sum[threadIdx.x + stride];
            sh_sum2[threadIdx.x] += sh_sum2[threadIdx.x + stride];
        }
        __syncthreads();
    }

