template <int TPB_>
__global__ void bn_reduce_kernel(const __half* __restrict__ input,
                                 int N, int C, int H, int W,
                                 float* __restrict__ mean,
                                 float* __restrict__ var) {
    const int c = blockIdx.x;                 // one block per channel
    const int HW = H * W;
    const int total = N * HW;                 // elements per channel

    float sum  = 0.f;
    float sum2 = 0.f;

