    for (int idx = threadIdx.x; idx < total; idx += TPB_) {
        int n  = idx / HW;
        int hw = idx % HW;
        int h  = hw / W;
        int w  = hw % W;
        int offset = ((n * C + c) * H + h) * W + w;
        __half v = input[offset];
        float fv = __half2float(v);
        sum  += fv;
        sum2 += fv * fv;
    }

    // block‑wise reduction
    __shared__ float s_sum[TPB_];
    __shared__ float s_sum2[TPB_];
    s_sum[threadIdx.x]  = sum;
    s_sum2[threadIdx.x] = sum2;
    __syncthreads();

    for (int stride = TPB_ / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x]  += s_sum[threadIdx.x + stride];
            s_sum2[threadIdx.x] += s_sum2[threadIdx.x + stride];
        }
        __syncthreads();
    }

