#include <torch/extension.h>
#include <ATen/ATen.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

constexpr int TPB = 256;   // threads per block for reductions

// ------------------------------------------------------------------
// Kernel: compute per‑channel mean
// ------------------------------------------------------------------
__global__ void compute_mean_kernel(const __half* __restrict__ x,
                                    float* __restrict__ mean,
                                    int N, int H, int W, int C) {
    int c = blockIdx.x;               // channel index
    int tid = threadIdx.x;
    int HWN = H * W * N;
    float sum = 0.0f;

    // stride over HWN elements belonging to this channel
    for (int idx = tid; idx < HWN; idx += blockDim.x) {
        int n  = idx / (H * W);
        int hw = idx % (H * W);
        int offset = ((n * C + c) * H * W) + hw;
        sum += __half2float(x[offset]);
    }

    // reduction in shared memory
    __shared__ float shmem[TPB];
    shmem[tid] = sum;
    __syncthreads();

    for (int s = TPB / 2; s > 0; s >>= 1) {
        if (tid < s) shmem[tid] += shmem[tid + s];
        __syncthreads();
    }

    if (tid == 0) {
        mean[c] = shmem[0] / static_cast<float>(HWN);
    }
}

// ------------------------------------------------------------------
// Kernel: compute per‑channel variance
// ------------------------------------------------------------------
__global__ void compute_var_kernel(const __half* __restrict__ x,
                                   const float* __restrict__ mean,
                                   float* __restrict__ var,
                                   int N, int H, int W, int C) {
    int c = blockIdx.x;
    int tid = threadIdx.x;
    int HWN = H * W * N;
    float m = mean[c];
    float sum = 0.0f;

    for (int idx = tid; idx < HWN; idx += blockDim.x) {
        int n  = idx / (H * W);
        int hw = idx % (H * W);
        int offset = ((n * C + c) * H * W) + hw;
        float diff = __half2float(x[offset]) - m;
        sum += diff * diff;
    }

    __shared__ float shmem[TPB];
    shmem[tid] = sum;
    __syncthreads();

    for (int s = TPB / 2; s > 0; s >>= 1) {
        if (tid < s) shmem[tid] += shmem[tid + s];
        __syncthreads();
    }

    if (tid == 0) {
        var[c] = shmem[0] / static_cast<float>(HWN);
    }
}

// ------------------------------------------------------------------
// Kernel: apply batch‑norm (normalize + affine)
// ------------------------------------------------------------------
__global__ void apply_bn_kernel(const __half* __restrict__ x,
                                __half* __restrict__ y,
                                const float* __restrict__ mean,
                                const float* __restrict__ var,
                                const __half* __restrict__ weight,
                                const __half* __restrict__ bias,
                                const float eps,
