#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

template <int BLOCK_SIZE>
__global__ void bn_reduce_kernel(
    const __half* __restrict__ input,
    int N, int C, int H, int W,
    float eps,
    float* __restrict__ mean_out,
    float* __restrict__ inv_std_out)
{
    int c = blockIdx.x;
    if (c >= C) return;

    int spatial = H * W;
    int channel_elems = N * spatial;          // #elements per channel

    // grid‑stride reduction for sum and sum‑sq
    float sum = 0.0f;
    float sumsq = 0.0f;
    for (int idx = threadIdx.x; idx < channel_elems; idx += BLOCK_SIZE) {
        int n = idx / spatial;
        int rem = idx - n * spatial;
        int h = rem / W;
        int w = rem - h * W;
        int offset = ((n * C + c) * H + h) * W + w;
        float v = __half2float(input[offset]);
        sum   += v;
        sumsq += v * v;
    }

    // reduction in shared memory
    __shared__ float s_sum[BLOCK_SIZE];
    __shared__ float s_sumsq[BLOCK_SIZE];
    s_sum[threadIdx.x]   = sum;
    s_sumsq[threadIdx.x] = sumsq;
    __syncthreads();

    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
