#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void group_norm_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    int total_elements,
    int num_features,
    int num_groups,
    int elements_per_feature
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    int batch_idx = idx / (num_features * elements_per_feature);
    int feature_idx = (idx % (num_features * elements_per_feature)) / elements_per_feature;
    int element_idx = idx % elements_per_feature;

    int group_idx = feature_idx / (num_features / num_groups);

    // Get group statistics
    float group_mean = mean[batch_idx * num_groups + group_idx];
    float group_var = var[batch_idx * num_groups + group_idx];

    // Apply normalization
    float inv_std = rsqrtf(group_var + 1e-5f);
    float val = __half2float(input[idx]);
    float normalized = (val - group_mean) * inv_std;
    float result = normalized * __half2float(weight[feature_idx]) + __half2float(bias[feature_idx]);

    output[idx] = __float2half(result);
}

__global__ void group_norm_stats_kernel(
    const half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ var,
    int batch_size,
    int num_features,
    int num_groups,
    int elements_per_feature
) {
    extern __shared__ float shared_mem[];

    int batch_idx = blockIdx.x;

    if (batch_idx >= batch_size) return;

    // Each thread block handles one batch
    int group_size = num_features / num_groups;
    int total_group_elements = group_size * elements_per_feature;

    for (int g = 0; g < num_groups; ++g) {
        int start_feat = g * group_size;
        int end_feat = (g + 1) * group_size;

        float sum = 0.0f;
        float sum_sq = 0.0f;

        // Compute sum and sum of squares for this group
        for (int f = start_feat; f < end_feat; ++f) {
            for (int e = 0; e < elements_per_feature; ++e) {
                int idx = batch_idx * (num_features * elements_per_feature) + f * elements_per_feature + e;
                float val = __half2float(input[idx]);
                sum += val;
                sum_sq += val * val;
            }
        }

        float group_mean = sum / total_group_elements;
        float group_var = sum_sq / total_group_elements - group_mean * group_mean;

        mean[batch_idx * num_groups + g] = group_mean;
        var[batch_idx * num_groups + g] = group_var;
