# ----------------------------------------------------------------------
# CUDA source implementing GroupNorm with fp16 I/O.
# Two kernels:
#   1) gn_accumulate_kernel: computes per-(batch,group) sum and sumsq via atomicAdd.
#   2) gn_normalize_kernel: performs normalization using the accumulated stats,
#      applies affine weight and bias, and writes fp16 output.
# ----------------------------------------------------------------------
cuda_source = r'''
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>

#ifndef CHECK
#define CHECK(x) TORCH_CHECK(x, #x)
#endif

// ------------------------------------------------------------------
// Kernel 1: accumulate sum and sum of squares per (batch, group)
// ------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void gn_accumulate_kernel(const __half* __restrict__ x,
                                     float* __restrict__ sum,
                                     float* __restrict__ sumsq,
                                     int N, int C, int H, int W, int G) {
    const int total = N * C * H * W;
    int idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    if (idx >= total) return;

    // decode indices
    int n = idx / (C * H * W);
    int c = (idx / (H * W)) % C;
    int g = c / (C / G);                 // group index

    // load input value (fp16) and convert to float
    __half v_h = __ldg(x + idx);
    float v = __half2float(v_h);

    // atomic accumulation
    atomicAdd(&sum[n * G + g], v);
    atomicAdd(&sumsq[n * G + g], v * v);
}

// ------------------------------------------------------------------
// Kernel 2: normalize using stats, apply affine, write fp16 output
// ------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void gn_normalize_kernel(const __half* __restrict__ x,
                                    const float* __restrict__ sum,
                                    const float* __restrict__ sumsq,
                                    const __half* __restrict__ weight,
                                    const __half* __restrict__ bias,
                                    __half* __restrict__ y,
                                    int N, int C, int H, int W, int G,
                                    float eps,
                                    int elems_per_group) {
    const int total = N * C * H * W;
    int idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    if (idx >= total) return;

    // decode indices
    int n = idx / (C * H * W);
    int c = (idx / (H * W)) % C;
    int g = c / (C / G);                 // group index

    // fetch accumulated stats
    float s = sum[n * G + g];
    float ss = sumsq[n * G + g];
    float mean = s / elems_per_group;
    float var = ss / elems_per_group - mean * mean;
    float inv_std = rsqrtf(var + eps);

    // load input
    __half v_h = __ldg(x + idx);
    float v = __half2float(v_h);

    // normalize
    float norm = (v - mean) * inv_std;

    // affine
    float w = __half2float(__ldg(weight + c));
    float b = __half2float(__ldg(bias   + c));
    float out = norm * w + b;

    // write output
    y[idx] = __float2half(out);
}

// ------------------------------------------------------------------
// Host launchers
// ------------------------------------------------------------------
void gn_forward_launcher(torch::Tensor x,
                         torch::Tensor weight,
                         torch::Tensor bias,
                         torch::Tensor y,
