#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

#ifndef EPS
#define EPS 1e-5f
#endif

// -----------------------------------------------------------------------------
// 1) Compute per‑group sum and sum‑of‑squares (fp32 accumulation)
// -----------------------------------------------------------------------------
__global__ void groupnorm_sum_kernel(
    const __half* __restrict__ input,
    float* __restrict__ sum,
    float* __restrict__ sumsq,
    const int N,
    const int C,
    const int H,
    const int W,
    const int G,
    const int channels_per_group)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * H * W;
    if (idx >= total) return;

    // unravel idx -> (n, c, h, w)
    const int c = (idx / (H * W)) % C;
    const int n = idx / (C * H * W);

    const int g = c / channels_per_group;          // group index
    const int group_idx = n * G + g;               // flattened (sample,group)

    const float val = __half2float(input[idx]);

    atomicAdd(&sum[group_idx],   val);
    atomicAdd(&sumsq[group_idx], val * val);
}

// -----------------------------------------------------------------------------
// 2) Derive mean and variance from the sums (fp32)
// -----------------------------------------------------------------------------
__global__ void compute_mean_var_kernel(
    const float* __restrict__ sum,
    const float* __restrict__ sumsq,
    float* __restrict__ mean,
    float* __restrict__ var,
    const int groups_total,
    const int group_size)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= groups_total) return;

    const float s  = sum[idx];
    const float ss = sumsq[idx];
    const float m  = s  / static_cast<float>(group_size);
    const float v  = ss / static_cast<float>(group_size) - m * m;
    mean[idx] = m;
    var[idx]  = v;
}

// -----------------------------------------------------------------------------
// 3) Normalise each element using per‑group stats and affine params
// -----------------------------------------------------------------------------
__global__ void groupnorm_norm_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    const int N,
    const int C,
    const int H,
    const int W,
    const int G,
    const int channels_per_group)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * H * W;
    if (idx >= total) return;

    // unravel idx -> (n, c, h, w)
    const int c = (idx / (H * W)) % C;
    const int n = idx / (C * H * W);

    const int g = c / channels_per_group;
    const int group_idx = n * G + g;

    const float mu   = mean[group_idx];
    const float sigma = sqrtf(var[group_idx] + EPS);
    const float x    = __half2float(input[idx]);

    const float norm = (x - mu) / sigma;

    const float wgt = __half2float(weight[c]);
    const float b   = __half2float(bias[c]);

    const float y = norm * wgt + b;
    output[idx] = __float2half(y);
}

// -----------------------------------------------------------------------------
// Public entry point
// -----------------------------------------------------------------------------
std::vector<torch::Tensor> groupnorm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    const int64_t num_groups)
