import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------------- #
# Optimized CUDA kernel for FP16 GroupNorm (fp32 accumulation, vectorized loads)
# --------------------------------------------------------------------------- #
cuda_source = r'''
#include <cuda_fp16.h>
#include <cuda_runtime.h>

template <int BLOCK_THREADS>
__inline__ __device__ float block_reduce_sum(float val) {
    // warp reduction
    for (int offset = BLOCK_THREADS / 2; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

// one block processes one (batch, group) pair
extern "C" __global__
void group_norm_forward_kernel(const half* __restrict__ input,
                               half* __restrict__ output,
                               const half* __restrict__ weight,
                               const half* __restrict__ bias,
                               const int N,
                               const int C,
                               const int H,
                               const int W,
                               const int G,
                               const float eps) {
    const int block_id = blockIdx.x;
    const int n = block_id / G;          // batch index
    const int g = block_id % G;          // group index

    const int tid = threadIdx.x;
    const int lane = tid & 31;           // thread lane in warp
    const int warp_id = tid >> 5;        // warp id

    const int C_per_g = C / G;
    const int spatial = H * W;
    const int numel   = C_per_g * spatial;          // elements per group
    const int numel2  = (numel + 1) / 2;             // half2 elements (ceil)

    // base offset of this group in NCHW layout (in half elements)
    const size_t group_base = ((size_t)n * C + (size_t)g * C_per_g) * spatial;

    // ---- first pass: compute sum & sumsq (vectorized half2) ----
    float sum = 0.0f;
    float sumsq = 0.0f;

    const half2* __restrict__ in2 = reinterpret_cast<const half2*>(input);
    size_t base2 = group_base / 2; // start index for half2 loads

    for (int idx2 = tid; idx2 < numel2; idx2 += blockDim.x) {
        half2 h2 = __ldg(&in2[base2 + idx2]);
        float2 f2 = __half22float2(h2);
        // first element
        sum   += f2.x;
        sumsq += f2.x * f2.x;
        // second element (guard against odd length)
        int global_idx = (idx2 * 2 + 1);
        if (global_idx < numel) {
            sum   += f2.y;
            sumsq += f2.y * f2.y;
        }
    }

    // ---- block-wide reduction using shuffles ----
    // reduce within warp
    sum   = block_reduce_sum<blockDim.x>(sum);
    sumsq = block_reduce_sum<blockDim.x>(sumsq);

    // store warp leaders' results
    __shared__ float warp_sum[32];
    __shared__ float warp_sumsq[32];
    if (lane == 0) {
        warp_sum[warp_id]   = sum;
        warp_sumsq[warp_id] = sumsq;
    }
    __syncthreads();

    // final reduction by first warp
    if (warp_id == 0) {
        sum   = (lane < (blockDim.x / 32)) ? warp_sum[lane]   : 0.0f;
        sumsq = (lane < (blockDim.x / 32)) ? warp_sumsq[lane] : 0.0f;
        sum   = block_reduce_sum<32>(sum);
        sumsq = block_reduce_sum<32>(sumsq);
    }
    __syncthreads();

    // broadcast mean & inv_std
    float mean, inv_std;
    if (tid == 0) {
        mean = sum / static_cast<float>(numel);
        float var = sumsq / static_cast<float>(numel) - mean * mean;
        inv_std = rsqrtf(var + eps);
    }
    __shared__ float mean_s, inv_std_s;
    if (tid == 0) {
        mean_s = mean;
        inv_std_s = inv_std;
    }
    __syncthreads();
    mean = mean_s;
    inv_std = inv_std_s;

    // ---- second pass: normalize and apply affine ----
    const half2* __restrict__ weight2 = reinterpret_cast<const half2*>(weight);
    const half2* __restrict__ bias2   = reinterpret_cast<const half2*>(bias);
    half2* __restrict__ out2 = reinterpret_cast<half2*>(output);

    for (int idx2 = tid; idx2 < numel2; idx2 += blockDim.x) {
        // compute global element indices for the two half values
        int idx0 = idx2 * 2;
        int idx1 = idx0 + 1;

        // load input values
        half2 h_in = __ldg(&in2[base2 + idx2]);
        float2 f_in = __half22float2(h_in);

        // process first element
        if (idx0 < numel) {
            int c0 = (idx0 / spatial);                 // channel inside group
            int global_c0 = g * C_per_g + c0;
            float val = f_in.x;
            float norm = (val - mean) * inv_std;
            float w = __half2float(weight[global_c0]);
            float b = __half2float(bias[global_c0]);
            float out = norm * w + b;
            out2[base2 + idx2].x = __float2half(out);
        } else {
            out2[base2 + idx2].x = __float2half(0.f);
        }

        // process second element
        if (idx1 < numel) {
            int c1 = (idx1 / spatial);
            int global_c1 = g * C_per_g + c1;
            float val = f_in.y;
            float norm = (val - mean) * inv_std;
            float w = __half2float(weight[global_c1]);
            float b = __half2float(bias[global_c1]);
            float out = norm * w + b;
            out2[base2 + idx2].y = __float2half(out);
        } else {
            out2[base2 + idx2].y = __float2half(0.f);
        }
    }
}

// --------------------------------------------------------------------------- //
extern "C" void group_norm_forward_launcher(const half* input,
                                            half* output,
                                            const half* weight,
                                            const half* bias,
                                            const int N,
                                            const int C,
                                            const int H,
                                            const int W,
                                            const int G,
                                            const float eps,
                                            cudaStream_t stream) {
    const int blocks = N * G;
    const int threads = 256;   // 8 warps, good occupancy
    group_norm_forward_kernel<<<blocks, threads, 0, stream>>>(
        input, output, weight, bias,
        N, C, H, W, G, eps);
}
'''

