                                            const half* bias,
                                            const int N,
                                            const int C,
                                            const int H,
                                            const int W,
                                            const int G,
                                            const float eps,
                                            cudaStream_t stream);

void group_norm_forward(at::Tensor input,
                        at::Tensor output,
                        at::Tensor weight,
                        at::Tensor bias,
                        int N, int C, int H, int W, int G,
                        float eps) {
    const half* input_ptr  = reinterpret_cast<const half*>(input.data_ptr<at::Half>());
    half*       output_ptr = reinterpret_cast<half*>(output.data_ptr<at::Half>());
    const half* weight_ptr = reinterpret_cast<const half*>(weight.data_ptr<at::Half>());
    const half* bias_ptr   = reinterpret_cast<const half*>(bias.data_ptr<at::Half>());

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    group_norm_forward_launcher(input_ptr, output_ptr,
                                weight_ptr, bias_ptr,
                                N, C, H, W, G, eps,
                                stream);
}
'''

# --------------------------------------------------------------------------- #
# Compile the extension
# --------------------------------------------------------------------------- #
gn_mod = load_inline(name='group_norm_opt',
                     cpp_sources=[cpp_source],
                     cuda_sources=[cuda_source],
                     functions=['group_norm_forward'],
                     verbose=False)

# --------------------------------------------------------------------------- #
# Autograd Function – forward uses custom kernel, backward falls back to PyTorch
# --------------------------------------------------------------------------- #
class GroupNormFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, weight, bias, num_groups, eps):
        if not input.is_cuda or input.dtype != torch.float16:
            raise RuntimeError("Input must be CUDA tensor of dtype torch.float16")
        N, C, H, W = input.shape
        output = torch.empty_like(input)

        gn_mod.group_norm_forward(
            input, output, weight, bias,
            N, C, H, W, num_groups, float(eps)
        )
        ctx.save_for_backward(input, weight, bias)
        ctx.num_groups = num_groups
        ctx.eps = eps
        return output

    @staticmethod
    def backward(ctx, grad_output):
        # Use native autograd for correctness
        input, weight, bias = ctx.saved_tensors
        gn = nn.GroupNorm(ctx.num_groups, input.shape[1],
                          eps=ctx.eps, affine=True).to(input.device, dtype=torch.float16)
        gn.weight = nn.Parameter(weight)
        gn.bias = nn.Parameter(bias)
        input.requires_grad = True
        out = gn(input)
        out.backward(grad_output)
        return input.grad, weight.grad, bias.grad, None, None

# --------------------------------------------------------------------------- #
# Model wrapper exposing the custom GroupNorm
# --------------------------------------------------------------------------- #
class ModelNew(nn.Module):
    def __init__(self, num_features: int, num_groups: int, eps: float = 1e-5):
        super().__init__()
        self.num_groups = num_groups
        self.eps = eps
        self.weight = nn.Parameter(torch.ones(num_features,
                                              dtype=torch.float16,
                                              device='cuda'))
        self.bias   = nn.Parameter(torch.zeros(num_features,
                                              dtype=torch.float16,
                                              device='cuda'))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            x = x.half()
        return GroupNormFunction.apply(x, self.weight, self.bias,
                                       self.num_groups, self.eps)

# --------------------------------------------------------------------------- #
# Helper functions matching the original interface
# --------------------------------------------------------------------------- #
def get_inputs():
    return [torch.rand(112, 64, 512, 512,
                       dtype=torch.float16,
                       device='cuda')]

def get_init_inputs():
    return [64, 8]   # num_features, num_groups

# --------------------------------------------------------------------------- #
# Simple sanity check (executed when run as script)
# --------------------------------------------------------------------------- #
if __name__ == "__main__":
    feats, groups = get_init_inputs()
    # Reference PyTorch GroupNorm
    model_ref = nn.GroupNorm(groups, feats, eps=1e-5, affine=True).cuda().half()
