#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

#ifndef CUDA_1D_BLOCK
#define CUDA_1D_BLOCK 256
#endif

// ---------------------------------------------------------------
// Kernel: RMSNorm over dimension 1 (features)
// ---------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void rms_norm_kernel(const half* __restrict__ x,
                                half* __restrict__ y,
                                const int batch,
                                const int num_features,
                                const int rest,
                                const float eps) {
    // each block processes one (batch, rest) element
    const int idx = blockIdx.x;
    const int batch_idx = idx / rest;
    const int rest_idx  = idx % rest;

    const int stride = rest;                     // distance between consecutive feature elements
    const int base   = batch_idx * num_features * rest + rest_idx;

    // ---- step 1: compute sum of squares (partial) ----
    float sum = 0.0f;
    for (int f = threadIdx.x; f < num_features; f += BLOCK_SIZE) {
        half hv = x[base + f * stride];
        float fv = __half2float(hv);
        sum += fv * fv;
    }

    // ---- step 2: block-wide reduction ----
    __shared__ float shm[BLOCK_SIZE];
    shm[threadIdx.x] = sum;
    __syncthreads();

    #pragma unroll
    for (int offset = BLOCK_SIZE / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            shm[threadIdx.x] += shm[threadIdx.x + offset];
        }
        __syncthreads();
    }

    const float rms = sqrtf(shm[0] / static_cast<float>(num_features) + eps);

    // ---- step 3: write normalized values ----
    for (int f = threadIdx.x; f < num_features; f += BLOCK_SIZE) {
        half hv = x[base + f * stride];
        float fv = __half2float(hv);
        float norm = fv / rms;
        y[base + f * stride] = __float2half(norm);
    }
}

// ---------------------------------------------------------------
// Host wrapper exposed to Python
// ---------------------------------------------------------------
torch::Tensor rms_norm_cuda(torch::Tensor x, const float eps) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kHalf, "input must be float16");
    TORCH_CHECK(x.dim() >= 2, "input must have at least 2 dimensions");

    const int batch = static_cast<int>(x.size(0));
    const int num_features = static_cast<int>(x.size(1));

    // Collapse remaining dimensions into one 'rest' dimension
    int64_t rest64 = 1;
    for (int i = 2; i < x.dim(); ++i) {
        rest64 *= x.size(i);
    }
    TORCH_CHECK(rest64 <= INT_MAX, "rest dimension too large");
    const int rest = static_cast<int>(rest64);

    auto y = torch::empty_like(x);

    // Choose block size (power of two, up to 1024)
    int block_size = 256;
    if (num_features > 256) block_size = 512;
    if (num_features > 512) block_size = 1024;

    const dim3 block(block_size);
    const dim3 grid(batch * rest);
    const size_t shared_mem = block_size * sizeof(float);

    // Launch appropriate template specialization
    if (block_size == 256) {
        rms_norm_kernel<256><<<grid, block, shared_mem>>>(
            reinterpret_cast<const half*>(x.data_ptr()),
            reinterpret_cast<half*>(y.data_ptr()),
            batch, num_features, rest, eps);
    } else if (block_size == 512) {
        rms_norm_kernel<512><<<grid, block, shared_mem>>>(
            reinterpret_cast<const half*>(x.data_ptr()),
            reinterpret_cast<half*>(y.data_ptr()),
            batch, num_features, rest, eps);
    } else { // 1024
        rms_norm_kernel<1024><<<grid, block, shared_mem>>>(
            reinterpret_cast<const half*>(x.data_ptr()),
            reinterpret_cast<half*>(y.data_ptr()),
            batch, num_features, rest, eps);
    }

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch error: ") + cudaGetErrorString(err));
    }

    return y;
}

// ---------------------------------------------------------------
// PyBind11 binding
// ---------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("rms_norm_cuda", &rms_norm_cuda, "RMSNorm forward (CUDA, fp16)");
}
'''

