    int linear_idx = blockIdx.x;          // 0 .. batch*N-1
    int b = linear_idx / N;               // batch index
    int n = linear_idx % N;               // flattened spatial index

    int tid = threadIdx.x;

    // ---------------------------------------------------------------
    // 1) Compute sum of squares over channel dimension
    // ---------------------------------------------------------------
    float sum = 0.0f;
    for (int c = tid; c < C; c += BLOCK_SIZE) {
        // Layout: (B, C, N) contiguous in memory
        int idx = ((b * C + c) * N) + n;
        __half v = x[idx];
        float fv = __half2float(v);
        sum += fv * fv;
    }

    // ---------------------------------------------------------------
    // 2) Block‑wide reduction (shared memory tree)
    // ---------------------------------------------------------------
    __shared__ float shared[BLOCK_SIZE];
    shared[tid] = sum;
    __syncthreads();

