import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------------------------------------------------------------
# CUDA source: contains kernel, wrapper and pybind module
# -------------------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

constexpr int THREADS = 256;

// ---------------------------------------------------------------------
// Kernel: per‑row L2‑norm and normalization (fp16 I/O, fp32 accumulation)
// ---------------------------------------------------------------------
__global__ void l2norm_kernel(const __half* __restrict__ input,
                              __half* __restrict__ output,
                              int dim) {
    const int row = blockIdx.x;          // one block per batch element
    const int tid = threadIdx.x;

    const __half* in_row = input + (size_t)row * dim;
    __half*       out_row = output + (size_t)row * dim;

    // ---- compute partial sum of squares (float accumulation) ----
    float sum = 0.0f;
    for (int i = tid; i < dim; i += THREADS) {
        float v = __half2float(in_row[i]);
        sum += v * v;
    }

    // ---- reduction in shared memory ----
    __shared__ float shmem[THREADS];
    shmem[tid] = sum;
    __syncthreads();

    for (int stride = THREADS / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shmem[tid] += shmem[tid + stride];
        }
        __syncthreads();
    }

    float norm = sqrtf(shmem[0]) + 1e-12f;   // epsilon to avoid div‑by‑zero

    // ---- write normalized output ----
    for (int i = tid; i < dim; i += THREADS) {
        float v = __half2float(in_row[i]);
        out_row[i] = __float2half(v / norm);
    }
}

// ---------------------------------------------------------------------
// Wrapper called from Python
// ---------------------------------------------------------------------
torch::Tensor l2norm_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    const int64_t batch = input.size(0);
    const int64_t dim   = input.size(1);

    auto options = torch::TensorOptions()
                       .dtype(torch::kHalf)
                       .device(input.device());
    torch::Tensor output = torch::empty({batch, dim}, options);

    dim3 grid(static_cast<unsigned int>(batch));
    dim3 block(THREADS);

    // launch kernel on the current stream
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    l2norm_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        static_cast<int>(dim));

    // check launch status
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch error: ")
                                 + cudaGetErrorString(err));
    }
    return output;
}

// ---------------------------------------------------------------------
// PyBind
// ---------------------------------------------------------------------
