cpp_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

constexpr int TILE_M = 128;   // rows per thread block
constexpr int TILE_N = 128;   // cols per thread block
constexpr int TILE_K = 16;    // reduction tile size (matches WMMA)

__global__ void batched_gemm_fp16_kernel(
    const half* __restrict__ A,
    const half* __restrict__ B,
    half* __restrict__ C,
    int batch,
    int M,
    int N,
    int K,
    int64_t stride_A_batch,
    int64_t stride_A_row,
    int64_t stride_B_batch,
    int64_t stride_B_row,
    int64_t stride_C_batch,
    int64_t stride_C_row)
{
    extern __shared__ half shmem[];               // shared memory for tiles
    half* shmem_A = shmem;                        // [TILE_M][TILE_K]
    half* shmem_B = shmem + TILE_M * TILE_K;      // [TILE_K][TILE_N]

    const int batch_idx = blockIdx.z;
    const int block_tile_m = blockIdx.y;
    const int block_tile_n = blockIdx.x;

    // pointers for this batch
    const half* A_batch = A + batch_idx * stride_A_batch;
    const half* B_batch = B + batch_idx * stride_B_batch;
    half* C_batch = C + batch_idx * stride_C_batch;

    // each thread block computes a TILE_M x TILE_N output tile
    // each warp computes a 16x16 sub‑tile using WMMA
    const int warp_id   = threadIdx.y;                // 0..(blockDim.y-1)
    const int lane_id   = threadIdx.x;                // 0..31 (within warp)

    const int warps_per_block_m = TILE_M / 16;        // =8
    const int warps_per_block_n = TILE_N / 16;        // =8
    const int warp_m = warp_id % warps_per_block_m;   // 0..7
    const int warp_n = warp_id / warps_per_block_m;   // 0..7

    // accumulator in fp32
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc;
    wmma::fill_fragment(acc, 0.0f);

    // starting coordinates of the tile this block processes
    const int tile_m_start = block_tile_m * TILE_M;
    const int tile_n_start = block_tile_n * TILE_N;

    // loop over K dimension in tiles of size TILE_K
    for (int tile_k = 0; tile_k < K; tile_k += TILE_K) {
        // ------------------------------------------------------------------
        // Load A tile into shared memory (coalesced)
        // ------------------------------------------------------------------
        for (int i = threadIdx.y; i < TILE_M; i += blockDim.y) {
            for (int j = threadIdx.x; j < TILE_K; j += blockDim.x) {
                int a_row = tile_m_start + i;
                int a_col = tile_k + j;
                half val = half(0.0f);
                if (a_row < M && a_col < K) {
                    val = A_batch[a_row * stride_A_row + a_col];
                }
                shmem_A[i * TILE_K + j] = val;
            }
        }

        // ------------------------------------------------------------------
        // Load B tile into shared memory (coalesced)
        // ------------------------------------------------------------------
        for (int i = threadIdx.y; i < TILE_K; i += blockDim.y) {
            for (int j = threadIdx.x; j < TILE_N; j += blockDim.x) {
                int b_row = tile_k + i;
                int b_col = tile_n_start + j;
                half val = half(0.0f);
                if (b_row < K && b_col < N) {
                    val = B_batch[b_row * stride_B_row + b_col];
                }
                shmem_B[i * TILE_N + j] = val;
            }
        }

        __syncthreads();

        // ------------------------------------------------------------------
        // WMMA multiplication for this tile
        // ------------------------------------------------------------------
        // each warp works on one 16x16 sub‑tile
        const int sub_m = warp_m * 16;
        const int sub_n = warp_n * 16;

        wmma::fragment<wmma::matrix_a, 16, 16, 16, half, wmma::row_major> a_frag;
        wmma::fragment<wmma::matrix_b, 16, 16, 16, half, wmma::col_major> b_frag;

        // load fragments from shared memory
        const half* tile_ptr_a = &shmem_A[sub_m * TILE_K];
        const half* tile_ptr_b = &shmem_B[sub_n]; // column‑major layout

        wmma::load_matrix_sync(a_frag, tile_ptr_a, TILE_K);
        wmma::load_matrix_sync(b_frag, tile_ptr_b, TILE_N);

        // matrix multiply‑accumulate
        wmma::mma_sync(acc, a_frag, b_frag, acc);
        __syncthreads();
    }

    // ------------------------------------------------------------------
    // Write accumulator back to global memory (with fp32->fp16 conversion)
    // ------------------------------------------------------------------
    // each warp writes its 16x16 result
    half* c_tile_ptr = C_batch + (tile_m_start + warp_m * 16) * stride_C_row
                                   + (tile_n_start + warp_n * 16);
    wmma::store_matrix_sync(c_tile_ptr, acc, stride_C_row,
                            wmma::mem_row_major);
}
'''

