#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <ATen/cuda/CUDAContext.h>

template <int TILE_M = 16, int TILE_N = 16>
__global__ void batched_gemm_fp16_kernel(const half* __restrict__ A,
                                          const half* __restrict__ B,
                                          half* __restrict__ C,
                                          int M, int K, int N) {
    // Batch index
    int batch = blockIdx.z;

    // Row & column of the output element this thread computes
    int row = blockIdx.y * TILE_M + threadIdx.y;
    int col = blockIdx.x * TILE_N + threadIdx.x;

    if (row >= M || col >= N) return;

    // Pointers to the current batch (contiguous layout)
    const half* A_batch = A + batch * (size_t)M * K;
    const half* B_batch = B + batch * (size_t)K * N;
    half* C_batch = C + batch * (size_t)M * N;

    float acc = 0.0f;
    for (int k = 0; k < K; ++k) {
        half a = A_batch[row * K + k];   // A[batch, row, k]
        half b = B_batch[k * N + col];   // B[batch, k, col]
        acc += __half2float(a) * __half2float(b);
    }
    C_batch[row * N + col] = __float2half(acc);
}

// ----------------------------------------------------------------------
// Launcher (exposed to Python)
// ----------------------------------------------------------------------
void batched_gemm_fp16(torch::Tensor A,
                       torch::Tensor B,
                       torch::Tensor C) {
    // ------------------------------------------------------------------
    // Checks
    // ------------------------------------------------------------------
    TORCH_CHECK(A.is_cuda() && B.is_cuda() && C.is_cuda(),
                "All tensors must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 &&
                B.dtype() == torch::kFloat16 &&
                C.dtype() == torch::kFloat16,
                "All tensors must be fp16");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3 && C.dim() == 3,
                "All tensors must be 3‑D");

    const int64_t batch = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    const int N = B.size(2);

    TORCH_CHECK(B.size(0) == batch && B.size(1) == K,
                "B must have shape (batch, K, N)");
    TORCH_CHECK(C.size(0) == batch && C.size(1) == M && C.size(2) == N,
                "C must have shape (batch, M, N)");

    TORCH_CHECK(A.is_contiguous() && B.is_contiguous() && C.is_contiguous(),
                "Tensors must be contiguous");

    // ------------------------------------------------------------------
    // Launch configuration
    // ------------------------------------------------------------------
    const dim3 block(TILE_N, TILE_M);
    const dim3 grid((N + TILE_N - 1) / TILE_N,
                   (M + TILE_M - 1) / TILE_M,
                   batch);

    auto stream = at::cuda::getCurrentCUDAStream();
    batched_gemm_fp16_kernel<TILE_M, TILE_N><<<grid, block, 0, stream>>>(
        reinterpret_cast<const half*>(A.data_ptr()),
        reinterpret_cast<const half*>(B.data_ptr()),
        reinterpret_cast<half*>(C.data_ptr()),
        M, K, N);

    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed: ", cudaGetErrorString(err));
}
