# Autograd Function (forward uses custom kernel, backward uses torch.bmm)
# ----------------------------------------------------------------------
class BatchedGemmFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, A, B):
        if not (A.is_cuda and B.is_cuda):
            raise RuntimeError("Inputs must be CUDA tensors")
        if A.dtype != torch.float16 or B.dtype != torch.float16:
            raise RuntimeError("Inputs must be fp16")
