    int batch = blockIdx.x;

    int row = blockIdx.y * blockDim.y + threadIdx.y; // M dimension
    int col = blockIdx.z * blockDim.x + threadIdx.x; // N dimension

    if (row >= M || col >= N) return;

    const half* A_batch = A + batch * M * K;
    const half* B_batch = B + batch * K * N;
    half*       C_batch = C + batch * M * N;

    // Accumulate in FP32 for better accuracy
    float acc = 0.0f;
    for (int k = 0; k < K; ++k) {
        half a = A_batch[row * K + k];
        half b = B_batch[k * N + col];
        acc += __half2float(a) * __half2float(b);
