        int b_row = t + threadIdx.y;
        int b_col = col;
        Bs[threadIdx.y][threadIdx.x] = (b_row < K && b_col < N)
            ? B[batch_idx * K * N + b_row * N + b_col]
            : __float2half(0.0f);

