    const int tx = threadIdx.x; // col inside tile
    const int ty = threadIdx.y; // row inside tile

    // global coordinates of the element this thread computes
    const int row = blockIdx.y * TILE_M + ty;
    const int col = blockIdx.z * TILE_N + tx;

    // pointers to the current batch
    const scalar_t* __restrict__ A_batch = A + batch_idx * strideA;
    const scalar_t* __restrict__ B_batch = B + batch_idx * strideB;
    scalar_t* __restrict__ C_batch = C + batch_idx * strideC;

    // shared memory tiles
    __shared__ __half As[TILE_M][TILE_K];
    __shared__ __half Bs[TILE_K][TILE_N];

    float acc = 0.0f;

    // loop over K dimension in tiles
    for (int t = 0; t < K; t += TILE_K) {
        // load A tile (row-major)
        int a_row = row;
        int a_col = t + tx;
        if (a_row < M && a_col < K) {
            As[ty][tx] = __float2half(__half2float(A_batch[a_row * K + a_col]));
