              static_cast<unsigned int>((M + TILE_M - 1) / TILE_M),
              static_cast<unsigned int>((N + TILE_N - 1) / TILE_N));
    dim3 block(TILE_N, TILE_M); // 16 x 16 = 256 threads

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

