    const int tid       = threadIdx.x;

    // base offset of this thread inside the tile
    int base = tile_idx * BLOCK_SIZE * VEC + tid;
    float local_sum = 0.0f;
    float local_sq  = 0.0f;

    #pragma unroll
    for (int i = 0; i < VEC; ++i) {
        int offset = base + i * BLOCK_SIZE;
        if (offset < normalized_size) {
            float val = __half2float(
                input[static_cast<size_t>(batch_idx) * normalized_size + offset]);
            local_sum += val;
            local_sq  += val * val;
        }
    }

    // ---------- block‑wide reduction (shared memory) ----------
    __shared__ float sh_sum[BLOCK_SIZE];
    __shared__ float sh_sq [BLOCK_SIZE];
    sh_sum[tid] = local_sum;
    sh_sq [tid] = local_sq;
    __syncthreads();

    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh_sum[tid] += sh_sum[tid + stride];
            sh_sq [tid] += sh_sq [tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(&sums[batch_idx],    sh_sum[0]);
        atomicAdd(&sq_sums[batch_idx], sh_sq[0]);
    }
}

// --------------------------------------------------------------------
// 2️⃣ Compute mean & inv‑std from the accumulated sums
// --------------------------------------------------------------------
__global__ void compute_stats_kernel(
    const float* __restrict__ sums,
    const float* __restrict__ sq_sums,
    float* __restrict__ mean,
    float* __restrict__ inv_std,
    int normalized_size,
    int batch,
    float eps)
{
    int batch_idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    if (batch_idx >= batch) return;

    float sum = sums[batch_idx];
    float sq  = sq_sums[batch_idx];
    float m   = sum / normalized_size;
    float var = sq / normalized_size - m * m;
    mean[batch_idx]    = m;
    inv_std[batch_idx] = rsqrtf(var + eps);
}

// --------------------------------------------------------------------
// 3️⃣ Apply LayerNorm + affine transformation
// --------------------------------------------------------------------
__global__ void apply_layernorm_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ inv_std,
    int normalized_size,
    int64_t total_elements)
{
    int64_t idx = static_cast<int64_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    if (idx >= total_elements) return;

    int batch_idx = idx / normalized_size;
    int offset    = idx % normalized_size;

    float x = __half2float(input[idx]);
    float w = __half2float(weight[offset]);
    float b = __half2float(bias[offset]);

    float y = ((x - mean[batch_idx]) * inv_std[batch_idx]) * w + b;
    output[idx] = __float2half(y);
}

