// Kernel 2: normalize, scale and shift (fp16 I/O)
// ---------------------------------------------------------------
extern "C" __global__
void layernorm_forward_kernel_impl(const __half* __restrict__ input,
                                   __half* __restrict__ output,
                                   const __half* __restrict__ weight,
                                   const __half* __restrict__ bias,
                                   const float* __restrict__ mean,
                                   const float* __restrict__ var,
                                   const int64_t batch,
                                   const int64_t N,
                                   const float eps) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    for (int64_t i = idx; i < batch * N; i += stride) {
        int64_t b = i / N;
        int64_t off = i % N;

        float m = mean[b];
        float v = var[b];
        float inv_std = rsqrtf(v + eps);

        float x = __half2float(input[i]);
        float w = __half2float(weight[off]);
        float bi = __half2float(bias[off]);

        float y = (x - m) * inv_std;   // normalize
        y = y * w + bi;                // affine
        output[i] = __float2half(y);
    }
}

