    const int threads = 256;
    const int blocks = std::min(4096, int((batch * N + threads - 1) / threads));

    layernorm_sum_kernel_impl<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        sum.data_ptr<float>(),
        sumsq.data_ptr<float>(),
        batch,
        N);
