                "layernorm_sum_kernel launch failed");
}

void layernorm_forward_kernel(torch::Tensor input,
                              torch::Tensor output,
                              torch::Tensor weight,
                              torch::Tensor bias,
                              torch::Tensor mean,
                              torch::Tensor var,
                              int64_t batch,
                              int64_t N,
                              float eps) {
    const int threads = 256;
    const int blocks = std::min(4096, int((batch * N + threads - 1) / threads));

