#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef __CUDA_ARCH__
#define __CUDA_ARCH__ 0
#endif

// -------------------------------------------------------------------------
// Optimized LayerNorm kernel (fp16 I/O, float accumulation)
// -------------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void layernorm_forward_kernel(const __half* __restrict__ input,
                                         __half* __restrict__ output,
                                         const __half* __restrict__ weight,
                                         const __half* __restrict__ bias,
                                         int64_t N,
                                         float eps) {
    // one block per independent "sample" (i.e. batch element)
    const int64_t batch_idx = blockIdx.x;
    const int tid = threadIdx.x;
    const int lane = tid & 31;                 // lane within warp
    const int warp_id = tid >> 5;              // warp id within block
    const int warps_per_block = BLOCK_SIZE / 32;

    const __half* in  = input  + batch_idx * N;
    __half* out       = output + batch_idx * N;

    // -----------------------------------------------------------------
    // 1) Compute sum and sum of squares (float accumulation)
    // -----------------------------------------------------------------
    float sum = 0.f;
    float sumsq = 0.f;

    // process two half values per iteration using half2 vector loads
    int64_t i = tid * 2;
    for (; i + 1 < N; i += BLOCK_SIZE * 2) {
        const half2 h = ((const half2*)in)[i >> 1];
        float v0 = __half2float(__low2half(h));
        float v1 = __half2float(__high2half(h));
        sum   += v0 + v1;
        sumsq += v0 * v0 + v1 * v1;
    }
    // tail element if N is odd
    if ((N & 1) && (i == N - 1)) {
        float v = __half2float(in[i]);
        sum   += v;
        sumsq += v * v;
    }

    // -----------------------------------------------------------------
    // 2) Warp‑level reduction (shuffle)
    // -----------------------------------------------------------------
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum   += __shfl_down_sync(0xffffffff, sum,   offset);
        sumsq += __shfl_down_sync(0xffffffff, sumsq, offset);
    }

    // store per‑warp results in shared memory
    __shared__ float shm_sum[BLOCK_SIZE / 32];
    __shared__ float shm_sumsq[BLOCK_SIZE / 32];
    if (lane == 0) {
        shm_sum[warp_id]   = sum;
        shm_sumsq[warp_id] = sumsq;
    }
    __syncthreads();

    // -----------------------------------------------------------------
    // 3) Reduce across warps (first warp does the final reduction)
    // -----------------------------------------------------------------
    float block_sum = 0.f;
    float block_sumsq = 0.f;
    if (warp_id == 0) {
        block_sum   = (tid < warps_per_block) ? shm_sum[tid]   : 0.f;
        block_sumsq = (tid < warps_per_block) ? shm_sumsq[tid] : 0.f;

        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_sum   += __shfl_down_sync(0xffffffff, block_sum,   offset);
            block_sumsq += __shfl_down_sync(0xffffffff, block_sumsq, offset);
        }
    }
    // broadcast the final results to all threads
    block_sum   = __shfl_sync(0xffffffff, block_sum,   0);
    block_sumsq = __shfl_sync(0xffffffff, block_sumsq, 0);

    // -----------------------------------------------------------------
    // 4) Compute mean, variance and inverse stddev
    // -----------------------------------------------------------------
    const float mean = block_sum / static_cast<float>(N);
    const float var  = block_sumsq / static_cast<float>(N) - mean * mean;
    const float inv_std = rsqrtf(var + eps);

    // -----------------------------------------------------------------
    // 5) Apply normalization, affine transformation and write output
    // -----------------------------------------------------------------
    i = tid * 2;
    for (; i + 1 < N; i += BLOCK_SIZE * 2) {
        // load input, weight and bias as half2
        const half2 h_in = ((const half2*)in)[i >> 1];
        const half2 h_w  = ((const half2*)weight)[i >> 1];
        const half2 h_b  = ((const half2*)bias)[i >> 1];

        // unpack
        float x0 = __half2float(__low2half(h_in));
        float x1 = __half2float(__high2half(h_in));
        float w0 = __half2float(__low2half(h_w));
        float w1 = __half2float(__high2half(h_w));
        float b0 = __half2float(__low2half(h_b));
        float b1 = __half2float(__high2half(h_b));

        // normalize + affine
        float y0 = (x0 - mean) * inv_std;
        float y1 = (x1 - mean) * inv_std;
        y0 = y0 * w0 + b0;
        y1 = y1 * w1 + b1;

        // store back as half2
        ((half2*)out)[i >> 1] = __halves2half(y0, y1);
    }
    // tail element if N is odd
    if ((N & 1) && (i == N - 1)) {
        float x = __half2float(in[i]);
        float w = __half2float(weight[i]);
        float b = __half2float(bias[i]);
        float y = (x - mean) * inv_std;
        y = y * w + b;
        out[i] = __float2half(y);
    }
}

// -------------------------------------------------------------------------
// Launcher
// -------------------------------------------------------------------------
void layernorm_forward_cuda(at::Tensor input,
                            at::Tensor output,
                            at::Tensor weight,
                            at::Tensor bias,
                            float eps) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda() &&
                weight.is_cuda() && bias.is_cuda(),
                "All tensors must be CUDA tensors");
    TORCH_CHECK(input.dtype() == torch::kFloat16 &&
                output.dtype() == torch::kFloat16 &&
                weight.dtype() == torch::kFloat16 &&
                bias.dtype()   == torch::kFloat16,
                "All tensors must be fp16");

    const int64_t batch = input.size(0);
    const int64_t N = input.numel() / batch;   // normalized dimension product

    constexpr int BLOCK_SIZE = 256;
    dim3 grid(batch);
    dim3 block(BLOCK_SIZE);

    // no dynamic shared memory needed (only compile‑time arrays)
    layernorm_forward_kernel<BLOCK_SIZE><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<const __half*>(bias.data_ptr()),
        N,
        eps);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA error in layernorm_forward: ", cudaGetErrorString(err));
