// Kernel: one thread computes one output element (no shared memory).
// ----------------------------------------------------------------------
template <int TPB>
__global__ void maxpool1d_fp16_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const int batch,
    const int channels,
    const int seq_len,
    const int out_len,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation) {

    const int bc_idx = blockIdx.x;                     // 0 .. batch*channels-1
    const int b = bc_idx / channels;
    const int c = bc_idx % channels;

    const int tid = threadIdx.x;
    const int out_start = blockIdx.y * TPB;
    const int out_i = out_start + tid;                // global output index

    if (out_i >= out_len) return;

