# CUDA source – contains kernel, host wrapper and PyBind11 module.
# ----------------------------------------------------------------------
_cuda_source = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <cfloat>

// ---------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------
__global__ void maxpool1d_forward_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    int64_t N, int64_t C, int64_t L,
    int64_t kernel_size, int64_t stride,
    int64_t padding, int64_t dilation,
    int64_t out_len) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * out_len;
    if (idx >= total) return;

    // decode linear index -> (n, c, o)
    int n = idx / (C * out_len);
    int rem = idx % (C * out_len);
    int c = rem / out_len;
    int o = rem % out_len;

    int start = o * stride - padding;
    float max_val = -FLT_MAX;

    #pragma unroll
    for (int k = 0; k < kernel_size; ++k) {
        int in_idx = start + k * dilation;
        float val = -FLT_MAX;
        if (in_idx >= 0 && in_idx < L) {
            val = __half2float(input[(n * C + c) * L + in_idx]);
        }
        if (val > max_val) max_val = val;
    }

    output[idx] = __float2half(max_val);
}

// ---------------------------------------------------------------
// Host wrapper
// ---------------------------------------------------------------
torch::Tensor maxpool1d_forward(
    torch::Tensor input,
    int64_t kernel_size,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    bool /*return_indices*/) {

    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::ScalarType::Half,
                "input must be torch.float16");

    const int64_t N = input.size(0);
    const int64_t C = input.size(1);
    const int64_t L = input.size(2);

    const int64_t out_len = (L + 2 * padding -
                             dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C, out_len}, input.options());

    const int threads = 256;
    const int blocks = static_cast<int>((N * C * out_len + threads - 1) / threads);

    maxpool1d_forward_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, C, L,
        kernel_size, stride, padding, dilation, out_len);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch error: ", cudaGetErrorString(err));
    }

    return output;
}

// ---------------------------------------------------------------
// PyBind11 module
// ---------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("maxpool1d_forward", &maxpool1d_forward,
          "1‑D max‑pool forward (custom CUDA, fp16)");
}
