__global__ void max_pool2d_kernel(
    const half* input,
    half* output,
    int batch_size,
    int channels,
    int input_height,
    int input_width,
    int output_height,
    int output_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int output_h_idx = threadIdx.x;
    int output_w_idx = threadIdx.y;

    if (batch_idx >= batch_size || channel_idx >= channels || 
        output_h_idx >= output_height || output_w_idx >= output_width) {
        return;
    }

    int output_idx = batch_idx * channels * output_height * output_width +
                     channel_idx * output_height * output_width +
                     output_h_idx * output_width + output_w_idx;

    half max_val = __ushort_as_half(0xFBFF); // Negative infinity in fp16
    bool valid = false;

    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            int input_h = output_h_idx * stride - padding + kh * dilation;
            int input_w = output_w_idx * stride - padding + kw * dilation;

            if (input_h >= 0 && input_h < input_height && 
                input_w >= 0 && input_w < input_width) {
                int input_idx = batch_idx * channels * input_height * input_width +
                                channel_idx * input_height * input_width +
