import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# C++ source (exposes the CUDA forward function to Python)
# ----------------------------------------------------------------------
cpp_source = r'''
#include <torch/extension.h>

// Declaration of the CUDA implementation (defined in the .cu file)
torch::Tensor maxpool2d_forward_cuda(
    torch::Tensor input,
    int64_t kernel,
    int64_t stride,
    int64_t padding,
    int64_t dilation);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &maxpool2d_forward_cuda, "MaxPool2d 2D forward (fp16, CUDA)");
}
'''

# ----------------------------------------------------------------------
# CUDA source (kernel + forward implementation)
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void maxpool2d_fp16_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    int N, int C,
    int H, int W,
    int outH, int outW,
    int kernel, int stride, int padding, int dilation) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * outH * outW;
    if (idx >= total) return;

    // decode linear index -> (n, c, h_out, w_out)
    int w_out = idx % outW; idx /= outW;
    int h_out = idx % outH; idx /= outH;
    int c     = idx % C;    int n = idx / C;

    int h_start = h_out * stride - padding;
    int w_start = w_out * stride - padding;

    __half max_val = __float2half(-65504.0f); // smallest fp16 value

    for (int kh = 0; kh < kernel; ++kh) {
        int h_in = h_start + kh * dilation;
        if (h_in < 0 || h_in >= H) continue;
        for (int kw = 0; kw < kernel; ++kw) {
            int w_in = w_start + kw * dilation;
            if (w_in < 0 || w_in >= W) continue;
            int in_idx = ((n * C + c) * H + h_in) * W + w_in;
            __half val = input[in_idx];
            max_val = __hgt(val, max_val) ? val : max_val;
        }
    }

    int out_idx = ((n * C + c) * outH + h_out) * outW + w_out;
    output[out_idx] = max_val;
}

torch::Tensor maxpool2d_forward_cuda(
    torch::Tensor input,
    int64_t kernel,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {

    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");

    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    // Effective kernel size accounting for dilation
    const int kernel_eff = dilation * (kernel - 1) + 1;
    const int outH = (H + 2 * padding - kernel_eff) / stride + 1;
    const int outW = (W + 2 * padding - kernel_eff) / stride + 1;

    auto output = torch::empty({N, C, outH, outW}, input.options());

    const int threads = 256;
    const int total = N * C * outH * outW;
    const int blocks = (total + threads - 1) / threads;

    maxpool2d_fp16_kernel<<<blocks, threads, 0,
        at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        N, C, H, W,
        outH, outW,
        static_cast<int>(kernel),
        static_cast<int>(stride),
        static_cast<int>(padding),
        static_cast<int>(dilation));

    return output;
}
'''

# ----------------------------------------------------------------------
# Compile the extension
# ----------------------------------------------------------------------
maxpool_ext = load_inline(
    name="maxpool2d_ext",
    cpp_sources=[cpp_source],
    cuda_sources=[cuda_source],
    functions=["forward"],
    verbose=False,
)

