import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# C++ wrapper
# ----------------------------------------------------------------------
cpp_src = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>

extern "C" void maxpool2d_fp16_launcher(
    const half* __restrict__ input,
    half* __restrict__ output,
    int N, int C,
    int H, int W,
    int outH, int outW,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w);

torch::Tensor maxpool2d_fp16(
    torch::Tensor input,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w) {

    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::ScalarType::Half,
                "input must be fp16");
    input = input.contiguous();

    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    const int outH = (H + 2 * pad_h -
                      dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    const int outW = (W + 2 * pad_w -
                      dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, C, outH, outW}, input.options());

    maxpool2d_fp16_launcher(
        reinterpret_cast<const half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<half*>(output.data_ptr<at::Half>()),
        N, C, H, W, outH, outW,
        kernel_h, kernel_w,
        stride_h, stride_w,
        pad_h, pad_w,
        dilation_h, dilation_w);

    cudaDeviceSynchronize(); // surface launch errors early
    return output;
}
'''

# ----------------------------------------------------------------------
# CUDA kernel
# ----------------------------------------------------------------------
cuda_src = r'''
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#define NEG_INF __float2half(-65504.0f)   // smallest representable fp16

// ------------------------------------------------------------------
// Kernel
// ------------------------------------------------------------------
extern "C" __global__ void maxpool2d_fp16_kernel(
    const half* __restrict__ input,
    half* __restrict__ output,
    int N, int C,
    int H, int W,
    int outH, int outW,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w) {

    // each thread processes one output element
    int w_out = blockIdx.x * blockDim.x + threadIdx.x;   // width index
    int h_out = blockIdx.y * blockDim.y + threadIdx.y;   // height index
    int nc    = blockIdx.z;                              // combined batch*channel

    if (w_out >= outW || h_out >= outH) return;

    int n = nc / C;
    int c = nc % C;

    // base pointers for this (n,c) slice
    const half* in_ptr  = input  + ((size_t)n * C + c) * H * W;
    half*       out_ptr = output + ((size_t)n * C + c) * outH * outW;

    // top‑left corner of the kernel in the input tensor
    int h_start = h_out * stride_h - pad_h;
    int w_start = w_out * stride_w - pad_w;

    __half max_val = NEG_INF;

    // unrolled loops for small kernels – still generic
    for (int kh = 0; kh < kernel_h; ++kh) {
        int h_in = h_start + kh * dilation_h;
        if (h_in < 0 || h_in >= H) continue;

        const half* row_ptr = in_ptr + h_in * W;

        for (int kw = 0; kw < kernel_w; ++kw) {
            int w_in = w_start + kw * dilation_w;
            if (w_in < 0 || w_in >= W) continue;

            __half cur = __ldg(row_ptr + w_in);
            max_val = __hgt(cur, max_val) ? cur : max_val;
        }
    }

    out_ptr[h_out * outW + w_out] = max_val;
}

// ------------------------------------------------------------------
// Launcher
// ------------------------------------------------------------------
extern "C" void maxpool2d_fp16_launcher(
    const half* __restrict__ input,
    half* __restrict__ output,
    int N, int C,
    int H, int W,
    int outH, int outW,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w) {

    // 32x8 = 256 threads per block – a good fit for A100
    dim3 block(32, 8);
    dim3 grid(
        (outW + block.x - 1) / block.x,
        (outH + block.y - 1) / block.y,
        (unsigned long)N * C);

    maxpool2d_fp16_kernel<<<grid, block>>>(
        input, output,
        N, C,
        H, W,
        outH, outW,
        kernel_h, kernel_w,
        stride_h, stride_w,
        pad_h, pad_w,
        dilation_h, dilation_w);
}
'''

# ----------------------------------------------------------------------
# Compile extension
# ----------------------------------------------------------------------
maxpool2d_cuda = load_inline(
    name='maxpool2d_cuda_opt',
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=['maxpool2d_fp16'],
    verbose=False,
)

# ----------------------------------------------------------------------
# Autograd Function (forward only)
# ----------------------------------------------------------------------
class MaxPool2dFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input,
                kernel_h, kernel_w,
                stride_h, stride_w,
                pad_h, pad_w,
                dilation_h, dilation_w):
        return maxpool2d_cuda.maxpool2d_fp16(
            input,
            kernel_h, kernel_w,
            stride_h, stride_w,
            pad_h, pad_w,
            dilation_h, dilation_w,
