    int bc_idx   = blockIdx.y;               // [0, batch*channels)
    int out_start = blockIdx.x * blockDim.x; // first output index handled by this block

    int c = bc_idx % channels;
    int b = bc_idx / channels;

    const scalar_t* in_ptr  = input  + ((b * channels + c) * input_len);
    scalar_t*       out_ptr = output + ((b * channels + c) * output_len);

    // Shared memory for the region of the input needed by this block
    extern __shared__ __half shmem[];

    // Number of elements required in shared memory (including padding)
    int shmem_len = blockDim.x * stride + kernel - stride + 2 * padding;

