#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

constexpr int BLOCK_X = 128;   // threads per block

template <int BLOCK_SIZE>
__global__ void avg_pool1d_kernel(const __half* __restrict__ input,
                                  __half* __restrict__ output,
                                  const int N,
                                  const int C,
                                  const int in_len,
                                  const int out_len,
                                  const int kernel_size,
                                  const int stride,
                                  const int padding) {
    // (n,c) pair handled by this block
    const int nc = blockIdx.y;
    const int n = nc / C;
    const int c = nc % C;

    // pointers to the (n,c) slice
    const __half* in_ptr  = input  + ((long long)n * C + c) * in_len;
    __half*       out_ptr = output + ((long long)n * C + c) * out_len;

    // each thread works on one output index
    const int out_start = blockIdx.x * BLOCK_SIZE;
    const int tid = threadIdx.x;
    const int out_idx = out_start + tid;

    if (out_idx >= out_len) return;

    // start index of the window (including padding)
    int in_start = out_idx * stride - padding;

    const float inv_ks = 1.0f / static_cast<float>(kernel_size);
    float sum = 0.0f;

