    int k = 0;
    for (; k + 1 < kernel_size; k += 2) {
        int idx = in_start + k;
        __half2 v = __float2half2_rn(0.0f);   // default zero

        // fast path: both elements inside the valid input range
        if (idx >= 0 && idx + 1 < in_len) {
            v = *reinterpret_cast<const __half2*>(in_ptr + idx);
        } else {
            // boundary handling element‑wise
            __half a = __float2half(0.0f);
            __half b = __float2half(0.0f);
            if (idx >= 0 && idx < in_len) a = in_ptr[idx];
            if (idx + 1 >= 0 && idx + 1 < in_len) b = in_ptr[idx + 1];
