#include <cuda_runtime.h>

__global__ void mean_reduction_kernel(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t reduction_size,
    int64_t outer_size,
    int64_t inner_size
) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= outer_size * inner_size) return;

    int64_t outer_idx = idx / inner_size;
    int64_t inner_idx = idx % inner_size;

    // Compute the starting position for this thread's reduction
    int64_t base_offset = outer_idx * reduction_size * inner_size + inner_idx;

    // Perform reduction using shared memory for better performance
    extern __shared__ half sdata[];

    half sum = __float2half(0.0f);

    // Reduce within the thread
    for (int64_t i = 0; i < reduction_size; ++i) {
        int64_t offset = base_offset + i * inner_size;
        sum = __hadd(sum, input[offset]);
    }

    sdata[threadIdx.x] = sum;
    __syncthreads();

    // Reduction in shared memory
    for (int64_t s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] = __hadd(sdata[threadIdx.x], sdata[threadIdx.x + s]);
        }
        __syncthreads();
    }

    // Write result
    if (threadIdx.x == 0) {
        // Divide by reduction size to get mean
        half mean_val = __hdiv(sdata[0], __float2half(static_cast<float>(reduction_size)));
        output[idx] = mean_val;
    }
