import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA source – tiled mean reduction over an arbitrary dimension
# ------------------------------------------------------------------
cuda_src = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <ATen/cuda/CUDAContext.h>

#ifndef TILE_SIZE
#define TILE_SIZE 128
#endif

// Each block processes TILE_SIZE output elements (different `inner` indices)
// for a single `outer` index. This greatly reduces the number of launched
// blocks compared with one‑block‑per‑output.
template <int TILE>
__global__ void mean_reduce_tiled_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const int64_t outer,
    const int64_t reduced,
    const int64_t inner)
{
    const int64_t o = blockIdx.x;                         // outer coordinate
    const int64_t i = blockIdx.y * TILE + threadIdx.x;    // inner coordinate

    if (i >= inner) return;                               // out‑of‑bounds guard

    // accumulate in FP32 for accuracy
    float sum = 0.0f;
    // stride‑1 walk over the reduced dimension (layout: ((o,reduced,i)))
    for (int64_t r = 0; r < reduced; ++r) {
        const int64_t idx = ((o * reduced + r) * inner) + i;
        sum += __half2float(input[idx]);
    }
    float mean = sum / static_cast<float>(reduced);
    output[o * inner + i] = __float2half(mean);
}

// ------------------------------------------------------------------
// C++ binding
// ------------------------------------------------------------------
torch::Tensor mean_reduce_cuda(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::kHalf, "input must be fp16");
    TORCH_CHECK(dim >= 0 && dim < input.dim(), "dim out of range");

    // ensure contiguous for simple indexing
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    // compute outer, reduced, inner sizes
    int64_t reduced = input.size(dim);
    int64_t outer = 1;
    int64_t inner = 1;
    for (int64_t d = 0; d < dim; ++d)   outer *= input.size(d);
    for (int64_t d = dim + 1; d < input.dim(); ++d) inner *= input.size(d);

    // allocate output (shape without reduced dim)
    std::vector<int64_t> out_sizes;
    out_sizes.reserve(input.dim() - 1);
    for (int64_t d = 0; d < input.dim(); ++d) {
        if (d != dim) out_sizes.push_back(input.size(d));
    }
    auto output = torch::empty(out_sizes, input.options());

    // launch configuration
    const int TILE = TILE_SIZE;                               // compile‑time constant
    const dim3 blocks(static_cast<uint32_t>(outer),
                     static_cast<uint32_t>((inner + TILE - 1) / TILE));
    const dim3 threads(TILE);

    const __half* in_ptr = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    __half* out_ptr = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    // kernel launch
    mean_reduce_tiled_kernel<TILE><<<blocks, threads, 0,
        at::cuda::getCurrentCUDAStream()>>>(in_ptr, out_ptr,
                                            outer, reduced, inner);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
    return output;
}
"""

# ------------------------------------------------------------------
