cuda_source = r'''
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv_fp16_kernel(const __half* __restrict__ input,
                                 const __half* __restrict__ weight,
                                 const __half* __restrict__ bias,
                                 __half* __restrict__ output,
                                 int N,
                                 int C_in,
                                 int H_in,
                                 int W_in,
                                 int C_out,
                                 int K_h,
                                 int K_w,
                                 int stride,
                                 int padding,
                                 int H_out,
                                 int W_out) {
    // Compute output pixel coordinates
    int ow = blockIdx.x * blockDim.x + threadIdx.x; // width index
    int oh = blockIdx.y * blockDim.y + threadIdx.y; // height index
    int nz = blockIdx.z;                           // combined batch & out channel
    if (ow >= W_out || oh >= H_out) return;

    int n  = nz / C_out;   // batch index
    int oc = nz % C_out;   // output channel index

    // Load bias if present
    float sum = bias ? __half2float(bias[oc]) : 0.0f;

    // Convolution sum
    for (int ic = 0; ic < C_in; ++ic) {
        for (int kh = 0; kh < K_h; ++kh) {
            int ih = oh * stride - padding + kh;
            if (ih < 0 || ih >= H_in) continue;
            for (int kw = 0; kw < K_w; ++kw) {
                int iw = ow * stride - padding + kw;
                if (iw < 0 || iw >= W_in) continue;

                int input_idx  = ((n * C_in + ic) * H_in + ih) * W_in + iw;
                int weight_idx = ((oc * C_in + ic) * K_h + kh) * K_w + kw;

                float a = __half2float(input[input_idx]);
                float b = __half2float(weight[weight_idx]);
                sum += a * b;
            }
        }
    }

    int out_idx = ((n * C_out + oc) * H_out + oh) * W_out + ow;
    output[out_idx] = __float2half(sum);
}

