void conv_fp16_kernel_launcher(const __half* input,
                               const __half* weight,
                               const __half* bias,
                               __half* output,
                               int N,
                               int C_in,
                               int H_in,
                               int W_in,
                               int C_out,
                               int K_h,
                               int K_w,
                               int stride,
                               int padding,
                               int H_out,
                               int W_out) {
    dim3 block(16, 16);
    dim3 grid((W_out + block.x - 1) / block.x,
              (H_out + block.y - 1) / block.y,
              N * C_out);
    conv_fp16_kernel<<<grid, block>>>(input, weight, bias, output,
                                      N, C_in, H_in, W_in,
                                      C_out, K_h, K_w,
                                      stride, padding,
                                      H_out, W_out);
    // Check for launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\n", cudaGetErrorString(err));
    }
}
