                                   int pad_h, int pad_w,
                                   int H_out, int W_out) {
    // output coordinates
    int ow = blockIdx.x * blockDim.x + threadIdx.x;   // width
    int oh = blockIdx.y * blockDim.y + threadIdx.y;   // height
    if (ow >= W_out || oh >= H_out) return;

    // batch and output‑channel index packed into blockIdx.z
    int batch_chan = blockIdx.z;
    int n   = batch_chan / C_out;
    int oc  = batch_chan % C_out;

