    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp       = tmp / H_out;
    int oc    = tmp % C_out;
    int n     = tmp / C_out;

    float acc = 0.0f;

    // convolution sum
    for (int ic = 0; ic < C_in; ++ic) {
        for (int kh = 0; kh < K; ++kh) {
            int h_in = h_out * stride_h - pad_h + kh;
