        out = torch.empty(N,
                          self.out_channels,
                          H_out,
                          W_out,
                          dtype=torch.float16,
                          device='cuda')

        # Launch the custom kernel
        conv2d_mod.conv2d_fp16(
            x,
            self.weight,
            self.bias,
            out,
            self.stride,
            self.stride,
            self.padding,
            self.padding
        )
        return out

