import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# C++ source – declares the function and registers it with PyBind.
# ------------------------------------------------------------------
cpp_source = r'''
#include <torch/extension.h>

// Declaration of the function implemented in the CUDA source.
torch::Tensor conv2d_fp16_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv2d_fp16_forward", &conv2d_fp16_forward,
          "FP16 Conv2d forward custom kernel");
}
'''

# ------------------------------------------------------------------
# CUDA source – kernel, host wrapper, and includes.
# ------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void conv2d_fp16_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    const int N, const int C_in, const int H_in, const int W_in,
    const int C_out, const int K, const int stride, const int padding,
    const int H_out, const int W_out)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    // Decode linear index (N, C_out, H_out, W_out)
    int n = idx / (C_out * H_out * W_out);
    int rem = idx % (C_out * H_out * W_out);
    int c_o = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_o = rem / W_out;
    int w_o = rem % W_out;

    const int h_start = h_o * stride - padding;
    const int w_start = w_o * stride - padding;

    // Accumulate in FP32
    float acc = bias ? __half2float(bias[c_o]) : 0.0f;

    for (int c_i = 0; c_i < C_in; ++c_i) {
        for (int p = 0; p < K; ++p) {
            int h_in = h_start + p;
            if (h_in < 0 || h_in >= H_in) continue;
            for (int q = 0; q < K; ++q) {
                int w_in = w_start + q;
                if (w_in < 0 || w_in >= W_in) continue;

                int input_idx  = ((n * C_in + c_i) * H_in + h_in) * W_in + w_in;
                int weight_idx = ((c_o * C_in + c_i) * K + p) * K + q;

                acc += __half2float(input[input_idx]) *
                       __half2float(weight[weight_idx]);
            }
        }
    }

    output[idx] = __float2half(acc);
}

// ------------------------------------------------------------------
// Host wrapper exposed to Python
// ------------------------------------------------------------------
torch::Tensor conv2d_fp16_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda(),
                "input and weight must be CUDA tensors");
    TORCH_CHECK(input.dtype() == torch::kHalf && weight.dtype() == torch::kHalf,
                "input and weight must be fp16");
    TORCH_CHECK(!bias.defined() || (bias.is_cuda() && bias.dtype() == torch::kHalf),
                "bias must be CUDA fp16 if defined");

    const int stride = 4;
    const int padding = 2;

    const int N     = input.size(0);
    const int C_in  = input.size(1);
    const int H_in  = input.size(2);
    const int W_in  = input.size(3);
    const int C_out = weight.size(0);
    const int K     = weight.size(2); // square kernel

    const int H_out = (H_in + 2 * padding - K) / stride + 1;
    const int W_out = (W_in + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    const int threads = 256;
    const int total   = N * C_out * H_out * W_out;
    const int blocks  = (total + threads - 1) / threads;

    conv2d_fp16_kernel<__half><<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        bias.defined() ? reinterpret_cast<const __half*>(bias.data_ptr()) : nullptr,
        reinterpret_cast<__half*>(output.data_ptr()),
        N, C_in, H_in, W_in,
        C_out, K, stride, padding,
        H_out, W_out
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
    cudaDeviceSynchronize();

    return output;
}
'''

# ------------------------------------------------------------------
# Build the extension (separate C++ and CUDA translation units)
# ------------------------------------------------------------------
conv2d_ext = load_inline(
    name='conv2d_fp16_ext',
    cpp_sources=[cpp_source],
    cuda_sources=[cuda_source],
    functions=['conv2d_fp16_forward'],
    verbose=False,
)

# ------------------------------------------------------------------
# Autograd Function (forward only)
# ------------------------------------------------------------------
class Conv2dCUDAFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, weight, bias):
        return conv2d_ext.conv2d_fp16_forward(input, weight, bias)

    @staticmethod
    def backward(ctx, grad_output):
        raise NotImplementedError("Backward not implemented for the custom conv kernel.")

# ------------------------------------------------------------------
# Model replicating nn.Conv2d(3, 96, kernel_size=11, stride=4, padding=2)
# ------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.weight = nn.Parameter(
            torch.randn(96, 3, 11, 11, dtype=torch.float16, device='cuda')
        )
        self.bias = nn.Parameter(
            torch.zeros(96, dtype=torch.float16, device='cuda')
        )

    def forward(self, x):
        # x is expected to be fp16 CUDA tensor
        return Conv2dCUDAFunction.apply(x, self.weight, self.bias)

# ------------------------------------------------------------------
# Simple test harness (run only when executed as script)
# ------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 256
    x = torch.randn(batch_size, 3, 224, 224, dtype=torch.float16, device='cuda')
    model = ModelNew().cuda()
    out = model(x)
    print("Output shape:", out.shape)   # Expected: torch.Size([256, 96, 55, 55])

