import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <algorithm>

__device__ __forceinline__ bool half_gt(half a, half b) {
    return __hgt(a, b);
}

__global__ void argmax_kernel(
    const half* input,
    int* output,
    int batch_size,
    int dim1,
    int dim2,
    int dim_to_reduce
) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (batch_idx >= batch_size) return;

    int base_offset = batch_idx * dim1 * dim2;

    // For dim1 reduction (reduce along dim1, output has shape [batch, dim2])
    if (dim_to_reduce == 1) {
        int elements_per_batch = dim2;
        int threads_per_element = (elements_per_batch + blockDim.x - 1) / blockDim.x;

        for (int elem_idx = tid * threads_per_element; 
             elem_idx < (tid + 1) * threads_per_element && elem_idx < elements_per_batch; 
             elem_idx++) {

            half max_val = input[base_offset + elem_idx];
            int max_idx = 0;

            for (int i = 1; i < dim1; i++) {
                half val = input[base_offset + i * dim2 + elem_idx];
                if (half_gt(val, max_val)) {
                    max_val = val;
                    max_idx = i;
                }
            }

            output[batch_idx * dim2 + elem_idx] = max_idx;
        }
    } else {
        // For dim2 reduction (reduce along dim2, output has shape [batch, dim1])
        int elements_per_batch = dim1;
        int threads_per_element = (elements_per_batch + blockDim.x - 1) / blockDim.x;

        for (int elem_idx = tid * threads_per_element; 
             elem_idx < (tid + 1) * threads_per_element && elem_idx < elements_per_batch; 
             elem_idx++) {

            half max_val = input[base_offset + elem_idx * dim2];
            int max_idx = 0;

            for (int i = 1; i < dim2; i++) {
                half val = input[base_offset + elem_idx * dim2 + i];
                if (half_gt(val, max_val)) {
                    max_val = val;
                    max_idx = i;
                }
            }

            output[batch_idx * dim1 + elem_idx] = max_idx;
        }
    }
}

// Wrapper function for easier calling from Python
extern "C" {
    void launch_argmax_kernel(
        const half* input,
        int* output,
        int batch_size,
        int dim1,
        int dim2,
        int dim_to_reduce
    ) {
        int grid_size = batch_size;
        int block_size = min(1024, max(dim1, dim2));
        argmax_kernel<<<grid_size, block_size>>>(
            input, output, batch_size, dim1, dim2, dim_to_reduce
        );
        cudaDeviceSynchronize();
    }
}
"""

# Create the model class directly in Python
def create_model(dim):
    # Compile the CUDA extension
    module = load_inline(
        name="argmax_cuda",
        cpp_sources=cuda_source,
        cuda_sources=cuda_source,
        functions=["launch_argmax_kernel"],
        verbose=False
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, dim):
            super(ModelNew, self).__init__()
            self.dim = dim

        def forward(self, x):
            # Ensure input is fp16
            if x.dtype != torch.float16:
                x = x.to(torch.float16)

            batch_size, dim1, dim2 = x.shape

            # Create output tensor
            if self.dim == 1:
                output_shape = (batch_size, dim2)
            else:
                output_shape = (batch_size, dim1)

            output = torch.empty(output_shape, dtype=torch.int32, device=x.device)

            # Launch kernel
            module.launch_argmax_kernel(
                x.data_ptr(),
                output.data_ptr(),
                batch_size,
                dim1,
                dim2,
                self.dim
            )

            return output

    return ModelNew(dim)

# Create model instance
