    // (i.e., the dimensions that remain in the output).
    // For each case we map thread index to those coordinates.
    if constexpr (DIM == 0) {
        int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
        int64_t total = dim1 * dim2;
        if (idx >= total) return;
        int64_t i = idx / dim2;   // dim1 index
        int64_t j = idx % dim2;   // dim2 index

        int64_t best = 0;
        float best_val = __half2float(input[j]);  // batch 0 element

        for (int64_t b = 1; b < batch; ++b) {
            float val = __half2float(
                input[b * dim1 * dim2 + i * dim2 + j]);
            if (val > best_val) {
                best_val = val;
                best = b;
            }
