        int64_t j = idx % dim2;   // dim2 index

        int64_t best = 0;
        float best_val = __half2float(
            input[b * dim1 * dim2 + j]); // i = 0

        for (int64_t i = 1; i < dim1; ++i) {
            float val = __half2float(
                input[b * dim1 * dim2 + i * dim2 + j]);
            if (val > best_val) {
                best_val = val;
                best = i;
            }
        }
        output[idx] = best;
    }
    else { // DIM == 2
        int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
        int64_t total = batch * dim1;
        if (idx >= total) return;
        int64_t b = idx / dim1;   // batch index
        int64_t i = idx % dim1;   // dim1 index

        int64_t best = 0;
