#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cfloat>
#include <cstdint>

extern "C" __global__
void argmax_fp16_kernel(const __half* __restrict__ input,
                        int64_t* __restrict__ output,
                        int64_t outer,
                        int64_t reduce,
                        int64_t inner) {
    // One block processes one (outer, inner) slice
    int64_t slice_id = blockIdx.x;
    if (slice_id >= outer * inner) return;

    int64_t outer_idx = slice_id / inner;
    int64_t inner_idx = slice_id % inner;

    const __half* base = input + outer_idx * reduce * inner + inner_idx;

    // Shared memory: float values + int64 indices
    extern __shared__ char smem[];
    float* sh_val = reinterpret_cast<float*>(smem);
    int64_t* sh_idx = reinterpret_cast<int64_t*>(smem + blockDim.x * sizeof(float));

    float thread_max = -FLT_MAX;
    int64_t thread_idx = -1;

    // Strided loop over reduction dimension
    for (int64_t r = threadIdx.x; r < reduce; r += blockDim.x) {
        __half v = base[r * inner];
        float f = __half2float(v);
        if (f > thread_max) {
            thread_max = f;
            thread_idx = r;
        } else if (f == thread_max && r < thread_idx) {
            thread_idx = r; // tie‑break: smallest index
        }
    }

    sh_val[threadIdx.x] = thread_max;
    sh_idx[threadIdx.x] = thread_idx;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            float other_val = sh_val[threadIdx.x + stride];
            int64_t other_idx = sh_idx[threadIdx.x + stride];
            float cur_val = sh_val[threadIdx.x];
            int64_t cur_idx = sh_idx[threadIdx.x];

            if (other_val > cur_val) {
                sh_val[threadIdx.x] = other_val;
                sh_idx[threadIdx.x] = other_idx;
            } else if (other_val == cur_val && other_idx < cur_idx) {
                sh_idx[threadIdx.x] = other_idx;
            }
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        output[slice_id] = sh_idx[0];
    }
}

// Host launcher
void argmax_fp16(at::Tensor input,
                 at::Tensor output,
                 int64_t outer,
                 int64_t reduce,
                 int64_t inner) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda(),
                "Both tensors must be CUDA tensors");
    TORCH_CHECK(input.is_contiguous() && output.is_contiguous(),
                "Both tensors must be contiguous");
    TORCH_CHECK(input.scalar_type() == at::kHalf,
                "Input must be float16");
    TORCH_CHECK(output.scalar_type() == at::kLong,
                "Output must be int64");

    const __half* in_ptr = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    int64_t* out_ptr = output.data_ptr<int64_t>();

    const int threads = 256;
    const int64_t blocks = outer * inner;
    const size_t shared_mem = threads * (sizeof(float) + sizeof(int64_t));

    argmax_fp16_kernel<<<static_cast<int>(blocks), threads, shared_mem,
                         at::cuda::getCurrentCUDAStream()>>>(
        in_ptr, out_ptr, outer, reduce, inner);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUDA error in argmax_fp16 kernel launch");
}

