template <typename scalar_t>
__global__ void argmax_kernel(const scalar_t* __restrict__ input,
                              int64_t* __restrict__ output,
                              const int64_t* __restrict__ shape,
                              const int64_t* __restrict__ stride,
                              const int dim,
                              const int64_t reduction_size,
                              const int64_t total_output,
                              const int ndim) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_output) return;

    // Decode output index -> offset in input (skip reduced dim)
    int64_t residual = idx;
    int64_t offset = 0;
    for (int d = ndim - 1; d >= 0; --d) {
        if (d == dim) continue;
        int64_t cur = residual % shape[d];
        residual /= shape[d];
        offset += cur * stride[d];
    }

    // Argmax over the reduction dimension
    float best_val = -FLT_MAX;
    int64_t best_idx = 0;
    int64_t stride_dim = stride[dim];
    for (int64_t k = 0; k < reduction_size; ++k) {
        // Convert half to float for comparison
        float val = __half2float(input[offset + k * stride_dim]);
        if (val > best_val) {
            best_val = val;
            best_idx = k;
        }
    }
    output[idx] = best_idx;
}

// Launcher called from Python
void launch_argmax_kernel(at::Tensor input,
                          at::Tensor output,
                          at::Tensor shape,
                          at::Tensor stride,
                          const int64_t dim,
                          const int64_t reduction_size,
