    half* __restrict__ output,
    const int N,
    const int C_in,
    const int C_out,
    const int D,
    const int W_in,   // width  (size dim 3 of input)
    const int H_in,   // height (size dim 4 of input)
    const int K,
    const int D_out,
    const int W_out,
