    int64_t tmp = idx;
    const int h_out = tmp % H_out;   tmp /= H_out;
    const int w_out = tmp % W_out;   tmp /= W_out;
    const int d_out = tmp % D_out;   tmp /= D_out;
    const int c_out = tmp % C_out;   tmp /= C_out;
    const int n = tmp;

