        for (int kd = 0; kd < K; ++kd) {
            const int d_in = d_out + kd;
            for (int kw = 0; kw < K; ++kw) {
                const int w_in = w_out + kw;
                for (int kh = 0; kh < K; ++kh) {
                    const int h_in = h_out + kh;

                    // Input offset: ((((n*C_in + c_in)*D + d_in)*W_in + w_in)*H_in + h_in)
