    torch::Tensor output = torch::empty({N, C_out, D_out, W_out, H_out}, options);

    const half* in_ptr = reinterpret_cast<const half*>(input.data_ptr<torch::Half>());
    const half* w_ptr  = reinterpret_cast<const half*>(weight.data_ptr<torch::Half>());
    half* out_ptr      = reinterpret_cast<half*>(output.data_ptr<torch::Half>());

    int64_t total = static_cast<int64_t>(N) * C_out * D_out * W_out * H_out;
    int blocks = static_cast<int>((total + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK);

