    unsigned long long rem = idx % (C_out * D_out * W_out * H_out);
    int c_out = rem / (D_out * W_out * H_out);
    rem = rem % (D_out * W_out * H_out);
    int d = rem / (W_out * H_out);
    rem = rem % (W_out * H_out);
    int w = rem / H_out;
    int h = rem % H_out;

    // accumulate in FP32 for accuracy
    float sum = 0.0f;

    for (int c_in = 0; c_in < C_in; ++c_in) {
        for (int kd = 0; kd < K; ++kd) {
            int d_in = d + kd;   // stride=1, padding=0, dilation=1
            for (int kw = 0; kw < K; ++kw) {
                int w_in = w + kw;
                for (int kh = 0; kh < K; ++kh) {
                    int h_in = h + kh;

                    long long i_idx = ((((( (long long)n * C_in + c_in) * D_in + d_in) * W_in + w_in) * H_in) + h_in);
                    long long w_idx = ((((( (long long)c_out * C_in + c_in) * K + kd) * K + kw) * K) + kh);

                    float iv = __half2float(input[i_idx]);
                    float wv = __half2float(weight[w_idx]);
                    sum += iv * wv;
                }
            }
        }
    }
    output[idx] = __float2half(sum);
}

