    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int W_in = input.size(3);
    int H_in = input.size(4);

    // Weight shape: (C_out, C_in, K, K, K)
    int C_out = weight.size(0);
    int K = weight.size(2);
    TORCH_CHECK(weight.size(1) == C_in, "weight in_channels must match input");
    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K,
                "kernel must be cubic");

