cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

extern "C" __global__
void conv_transpose2d_fp16_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    __half* __restrict__ output,
    int batch,
    int in_c,
    int out_c,
    int H_in,
    int W_in,
    int K,
    int H_out,
    int W_out)
{
    int x = blockIdx.x * blockDim.x + threadIdx.x;   // width index in output
    int y = blockIdx.y * blockDim.y + threadIdx.y;   // height index in output
    int oc = blockIdx.z % out_c;                     // output channel
    int n  = blockIdx.z / out_c;                     // batch index

    if (n >= batch || oc >= out_c || y >= H_out || x >= W_out) return;

    float acc = 0.0f;   // FP32 accumulator

    // For each input channel and kernel position that maps to (y,x)
    for (int ic = 0; ic < in_c; ++ic) {
        for (int ky = 0; ky < K; ++ky) {
            int in_y = y - ky;                 // input coordinate that contributed
            if (in_y < 0 || in_y >= H_in) continue;
            for (int kx = 0; kx < K; ++kx) {
                int in_x = x - kx;
                if (in_x < 0 || in_x >= W_in) continue;

                // input index: (n, ic, in_y, in_x)
                int inp_idx = ((n * in_c + ic) * H_in + in_y) * W_in + in_x;

                // weight must be flipped for full (transposed) convolution
                int wky = K - 1 - ky;
                int wkx = K - 1 - kx;
                // weight index: (ic, oc, wky, wkx)
                int wgt_idx = ((ic * out_c + oc) * K + wky) * K + wkx;

                __half in_val = input[inp_idx];
                __half w_val  = weight[wgt_idx];
                acc += __half2float(in_val) * __half2float(w_val);
            }
        }
    }

    int out_idx = ((n * out_c + oc) * H_out + y) * W_out + x;
    output[out_idx] = __float2half(acc);
}

at::Tensor conv_transpose2d_fp16_cuda(at::Tensor input, at::Tensor weight) {
    const int batch = input.size(0);
    const int in_c  = input.size(1);
    const int H_in  = input.size(2);
    const int W_in  = input.size(3);

    const int out_c = weight.size(1);
    const int K     = weight.size(2);
    TORCH_CHECK(weight.size(2) == weight.size(3), "kernel must be square");

    // Output dimensions for stride=1, padding=0, output_padding=0
    const int H_out = H_in + K - 1;
    const int W_out = W_in + K - 1;

    auto opts = torch::TensorOptions()
                    .dtype(torch::kHalf)
                    .device(input.device())
                    .layout(torch::kStrided);
    at::Tensor output = torch::empty({batch, out_c, H_out, W_out}, opts);

    const dim3 block(16, 16);
    const dim3 grid(
        (W_out + block.x - 1) / block.x,
        (H_out + block.y - 1) / block.y,
        static_cast<unsigned int>(batch * out_c));

    const cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    conv_transpose2d_fp16_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        batch, in_c, out_c,
        H_in, W_in,
        K,
        H_out, W_out);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUDA kernel launch failed");
    return output;
}
'''

