# ----------------------------------------------------------------------
cuda_src = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_INPUT
#define CHECK_INPUT(x) CHECK_CUDA(x); CHECK_CONTIGUOUS(x);
#endif

// ------------------------------------------------------------------
// Transposed convolution kernel (stride=1, padding=0, groups=1, bias=0)
// The weight is accessed with a flip to match nn.ConvTranspose2d semantics.
// ------------------------------------------------------------------
__global__ void conv_transpose2d_fp16_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    __half* __restrict__ output,
    const int batch,
    const int in_c,
    const int out_c,
    const int in_h,
    const int in_w,
    const int k)                     // square kernel
{
    // blockIdx.z encodes (batch, out_channel)
    const int bz = blockIdx.z;
    const int n  = bz / out_c;          // batch index
    const int oc = bz % out_c;          // output channel index

    const int y = blockIdx.y * blockDim.y + threadIdx.y; // output y
    const int x = blockIdx.x * blockDim.x + threadIdx.x; // output x

    const int out_h = in_h + k - 1;
    const int out_w = in_w + k - 1;

    if (y >= out_h || x >= out_w) return;

    // Accumulate in FP32 for numerical stability
    float acc = 0.0f;

    // Iterate over all input channels and kernel positions
    for (int ic = 0; ic < in_c; ++ic) {
        // For transposed convolution the kernel is *flipped* relative to conv2d.
        // Weight layout of nn.ConvTranspose2d is (in_c, out_c, k, k).
        for (int p = 0; p < k; ++p) {
            int in_y = y - p;                // map output y -> input y
            if (in_y < 0 || in_y >= in_h) continue;
            for (int q = 0; q < k; ++q) {
                int in_x = x - q;            // map output x -> input x
                if (in_x < 0 || in_x >= in_w) continue;

                // Input index: ((n * in_c + ic) * in_h + in_y) * in_w + in_x
                const int in_idx = ((n * in_c + ic) * in_h + in_y) * in_w + in_x;

                // Flipped weight index:
                // ((ic * out_c + oc) * k + (k-1-p)) * k + (k-1-q)
                const int w_idx = ((ic * out_c + oc) * k + (k - 1 - p)) * k + (k - 1 - q);

                float in_val = __half2float(input[in_idx]);
                float w_val  = __half2float(weight[w_idx]);
                acc += in_val * w_val;
            }
        }
    }

    // Write result back as FP16
    const int out_idx = ((n * out_c + oc) * out_h + y) * out_w + x;
    output[out_idx] = __float2half(acc);
}

// ------------------------------------------------------------------
// Launcher exposed to Python
// ------------------------------------------------------------------
void conv_transpose2d_fp16_launcher(at::Tensor input,
                                   at::Tensor weight,
                                   at::Tensor output)
{
    CHECK_INPUT(input);
    CHECK_INPUT(weight);
    CHECK_INPUT(output);
    TORCH_CHECK(input.dtype() == torch::kFloat16 &&
                weight.dtype() == torch::kFloat16 &&
                output.dtype() == torch::kFloat16,
                "All tensors must be float16");

    const int batch = input.size(0);
    const int in_c  = input.size(1);
    const int in_h  = input.size(2);
    const int in_w  = input.size(3);
    const int out_c = weight.size(1);
    const int k     = weight.size(2);   // assume square kernel

    const int out_h = in_h + k - 1;
    const int out_w = in_w + k - 1;

    const dim3 block(16, 16);
    const dim3 grid(
        (out_w + block.x - 1) / block.x,
        (out_h + block.y - 1) / block.y,
        static_cast<unsigned int>(batch * out_c)
    );

    conv_transpose2d_fp16_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        batch, in_c, out_c, in_h, in_w, k
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR(cudaGetErrorString(err));
    }
}
'''

