#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>

__global__ void fp32_to_fp16_kernel(
    const float* __restrict__ src,
    __half* __restrict__ dst,
    int64_t N)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        dst[idx] = __float2half(src[idx]);
    }
}

__global__ void add_bias_kernel(
    float* __restrict__ out,
    const __half* __restrict__ bias,
    int batch,
    int out_channels,
    int H_out,
    int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * out_channels * H_out * W_out;
    if (idx >= total) return;
    int oc = (idx / (H_out * W_out)) % out_channels;
    float b = __half2float(bias[oc]);
    out[idx] += b;
}

// Transposed convolution kernel (FP16 I/O, FP32 accumulation)
__global__ void conv_transpose2d_fp16_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,   // unused inside kernel, kept for signature compatibility
    float* __restrict__ out,
    int batch,
    int in_channels,
    int out_channels,
    int H_in,
    int W_in,
    int K,
    int stride,
    int padding,
    int output_padding,
    int groups,
    int H_out,
    int W_out,
    bool has_bias)
{
    // One thread per input element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * in_channels * H_in * W_in;
    if (idx >= total) return;

    // Decode indices
    int w_in = idx % W_in;
    int tmp = idx / W_in;
    int h_in = tmp % H_in;
    int ic = (tmp / H_in) % in_channels;
    int n = tmp / (H_in * in_channels);

    float in_val = __half2float(input[idx]);

    int ic_per_group = in_channels / groups;
    int oc_per_group = out_channels / groups;
    int group_idx = ic / ic_per_group;
    int ic_local = ic % ic_per_group;

    // Pointer to start of weight slice for this group
    const __half* w_ptr = weight + group_idx * oc_per_group * ic_per_group * K * K;

    // Iterate over kernel spatial dimensions
    for (int kh = 0; kh < K; ++kh) {
        int h_out = h_in * stride - padding + kh;
        if (h_out < 0 || h_out >= H_out) continue;
        for (int kw = 0; kw < K; ++kw) {
            int w_out = w_in * stride - padding + kw;
            if (w_out < 0 || w_out >= W_out) continue;

            // Base address for this (n, group) slice in output
            int out_base = ((n * groups + group_idx) * oc_per_group) * H_out * W_out
                         + h_out * W_out + w_out;

            // Accumulate over output channels within the group
            for (int ocg = 0; ocg < oc_per_group; ++ocg) {
                int w_idx = (ocg * ic_per_group + ic_local) * K * K + kh * K + kw;
                float w_val = __half2float(w_ptr[w_idx]);
                atomicAdd(&out[out_base + ocg * H_out * W_out],
                          in_val * w_val);
            }
        }
    }
}

// Launcher wrappers
void conv_transpose2d_fp16_kernel_launcher(
    const at::Half* input,
    const at::Half* weight,
    const at::Half* bias,
    float* out,
    int batch,
    int in_channels,
    int out_channels,
    int H_in,
    int W_in,
    int K,
    int stride,
    int padding,
    int output_padding,
    int groups,
    int H_out,
    int W_out,
    bool has_bias)
{
    const int threads = 256;
    const int total = batch * in_channels * H_in * W_in;
    const int blocks = (total + threads - 1) / threads;

    // Zero output buffer
    cudaMemsetAsync(out,
                    0,
                    sizeof(float) * batch * out_channels * H_out * W_out,
                    0);

    conv_transpose2d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input),
        reinterpret_cast<const __half*>(weight),
        reinterpret_cast<const __half*>(bias),
        out,
        batch,
        in_channels,
        out_channels,
        H_in,
        W_in,
        K,
        stride,
        padding,
        output_padding,
        groups,
        H_out,
        W_out,
        has_bias);

    if (has_bias) {
        int total_out = batch * out_channels * H_out * W_out;
        int bias_blocks = (total_out + threads - 1) / threads;
        add_bias_kernel<<<bias_blocks, threads>>>(
            out,
            reinterpret_cast<const __half*>(bias),
            batch,
            out_channels,
            H_out,
            W_out);
    }

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("conv_transpose2d_fp16 kernel launch failed: ", cudaGetErrorString(err));
    }
}

void fp32_to_fp16_kernel_launcher(
    const float* src,
    at::Half* dst,
    int64_t N)
{
    const int threads = 256;
    const int blocks = (N + threads - 1) / threads;
    fp32_to_fp16_kernel<<<blocks, threads>>>(
        src,
        reinterpret_cast<__half*>(dst),
        N);
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("fp32_to_fp16 kernel launch failed: ", cudaGetErrorString(err));
    }
}
