    Mirrors torch.nn.ConvTranspose2d API.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size if isinstance(kernel_size, int) else kernel_size[0]
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.use_bias = bias

        self.weight = nn.Parameter(
            torch.empty(out_channels,
                        in_channels // groups,
                        self.kernel_size,
                        self.kernel_size,
                        dtype=torch.float16,
                        device='cuda')
        )
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if self.use_bias:
            self.bias = nn.Parameter(
                torch.empty(out_channels,
                            dtype=torch.float16,
                            device='cuda')
            )
            nn.init.zeros_(self.bias)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.dtype == torch.float16, "Input must be fp16"
        N, C_in, H_in, W_in = x.shape
        K = self.kernel_size
        stride = self.stride
        pad = self.padding
        out_pad = self.output_padding
        groups = self.groups

        H_out = (H_in - 1) * stride - 2 * pad + K + out_pad
        W_out = (W_in - 1) * stride - 2 * pad + K + out_pad

        # Allocate FP32 accumulation buffer
        out_fp32 = torch.empty(N,
                               self.out_channels,
                               H_out,
                               W_out,
                               dtype=torch.float32,
                               device='cuda')

        conv_ext.conv_transpose2d_fp16(
            x,
            self.weight,
            self.bias if self.use_bias else torch.empty(0, dtype=torch.float16, device='cuda'),
            out_fp32,
            N,
            C_in,
            self.out_channels,
            H_in,
            W_in,
            K,
            stride,
            pad,
            out_pad,
            groups,
            H_out,
            W_out,
            self.use_bias
        )

        # Convert back to FP16
        out_fp16 = torch.empty_like(out_fp32, dtype=torch.float16)
        conv_ext.fp32_to_fp16(out_fp32, out_fp16, out_fp32.numel())

        return out_fp16

