#include <cuda_fp16.h>
#include <cuda_runtime.h>

extern "C" __global__
void conv_transpose2d_fp16_kernel(
    const __half* __restrict__ input,      // [N, C_in, H_in, W_in]
    const __half* __restrict__ weight,     // [C_in, C_out_per_g, K, K]
    __half* __restrict__ output,           // [N, C_out, H_out, W_out]
    int N,
    int C_in,
    int H_in,
    int W_in,
    int C_out,
    int K,
    int stride,
    int padding,
    int output_padding,
    int groups)
{
    // thread maps to one input element (n, c_in, h_in, w_in)
    const int w_in = blockIdx.x * blockDim.x + threadIdx.x;
    const int h_in = blockIdx.y * blockDim.y + threadIdx.y;
    const int n_c  = blockIdx.z;                     // packed n and c_in
    const int n    = n_c / C_in;
    const int c_in = n_c % C_in;

    if (n >= N || h_in >= H_in || w_in >= W_in) return;

    const int C_in_per_group  = C_in / groups;
    const int C_out_per_group = C_out / groups;
    const int group_id        = c_in / C_in_per_group;
    const int c_in_in_group   = c_in % C_in_per_group;

    const __half in_val = input[ (( (n * C_in) + c_in) * H_in + h_in) * W_in + w_in ];

    const int H_out = (H_in - 1) * stride - 2 * padding + K + output_padding;
    const int W_out = (W_in - 1) * stride - 2 * padding + K + output_padding;

    // iterate over output channels belonging to the same group
    for (int c_out_rel = 0; c_out_rel < C_out_per_group; ++c_out_rel) {
        const int c_out = group_id * C_out_per_group + c_out_rel;
        // iterate over kernel spatial dimensions
        for (int kh = 0; kh < K; ++kh) {
            const int h_out = h_in * stride - padding + kh;
            if (h_out < 0 || h_out >= H_out) continue;
            for (int kw = 0; kw < K; ++kw) {
                const int w_out = w_in * stride - padding + kw;
                if (w_out < 0 || w_out >= W_out) continue;

                // weight layout: [c_in_in_group, c_out_rel, kh, kw]
                const int w_idx = ((c_in_in_group * C_out_per_group + c_out_rel) * K + kh) * K + kw;
                const __half w_val = weight[w_idx];

                const __half prod = __hmul(in_val, w_val);
                const int out_idx = (( (n * C_out) + c_out) * H_out + h_out) * W_out + w_out;

                // atomic add on half (supported on compute capability >= 7.0)
                atomicAdd(&output[out_idx], prod);
            }
        }
    }
}

// ----------------------------------------------------------------------
// Optional bias addition kernel
// ----------------------------------------------------------------------
extern "C" __global__
void add_bias_fp16_kernel(
    __half* __restrict__ output,
    const __half* __restrict__ bias,
    int N,
    int C_out,
    int H_out,
    int W_out)
{
    const int w = blockIdx.x * blockDim.x + threadIdx.x;
    const int h = blockIdx.y * blockDim.y + threadIdx.y;
    const int c = blockIdx.z % C_out;
    const int n = blockIdx.z / C_out;

    if (n >= N || c >= C_out || h >= H_out || w >= W_out) return;

    const int idx = (( (n * C_out) + c) * H_out + h) * W_out + w;
    atomicAdd(&output[idx], bias[c]);
}

// ----------------------------------------------------------------------
// Launch wrappers called from C++
// ----------------------------------------------------------------------
extern "C" void conv_transpose2d_fp16_forward(
