cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void conv_transpose2d_fp16_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    const int N,
    const int C_in,
    const int C_out,
    const int H,
    const int W,
    const int K,
    const int stride,
    const int padding,
    const int groups,
    const int H_out,
    const int W_out)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    // decode linear index
    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp       = tmp / H_out;
    int c_out = tmp % C_out;
    int n     = tmp / C_out;

    const int out_channels_per_group = C_out / groups;
    const int in_channels_per_group  = C_in / groups;
    const int group = c_out / out_channels_per_group;
    const int c_out_in_group = c_out % out_channels_per_group;
    const int c_in_start = group * in_channels_per_group;
    const int c_in_end   = c_in_start + in_channels_per_group;

    float acc = 0.0f;

    // iterate over contributing input channels and kernel positions
    for (int c_in = c_in_start; c_in < c_in_end; ++c_in) {
        for (int kh = 0; kh < K; ++kh) {
            const int out_h_base = h_out + padding - kh;
            if (out_h_base < 0) continue;
            if (out_h_base % stride != 0) continue;
            const int h_in = out_h_base / stride;
            if (h_in >= H) continue;

            for (int kw = 0; kw < K; ++kw) {
                const int out_w_base = w_out + padding - kw;
                if (out_w_base < 0) continue;
                if (out_w_base % stride != 0) continue;
                const int w_in = out_w_base / stride;
                if (w_in >= W) continue;

                const int input_idx  = ((n * C_in + c_in) * H + h_in) * W + w_in;
                const int weight_idx = ((c_in * out_channels_per_group + c_out_in_group) * K + kh) * K + kw;

                const float in_val  = __half2float(input[input_idx]);
                const float w_val   = __half2float(weight[weight_idx]);
                acc += in_val * w_val;
            }
        }
    }

    if (bias != nullptr) {
        acc += __half2float(bias[c_out]);
    }

    output[idx] = __float2half(acc);
}

void conv_transpose2d_fp16_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor output,
    int stride,
    int padding,
    int groups)
{
    const int N = input.size(0);
    const int C_in = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int K = weight.size(2);
    const int C_out = weight.size(1) * groups; // out_channels
    const int H_out = output.size(2);
    const int W_out = output.size(3);

    const dim3 block(256);
    const dim3 grid((N * C_out * H_out * W_out + block.x - 1) / block.x);

    const __half* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = reinterpret_cast<const __half*>(bias.data_ptr<at::Half>());
    }

    conv_transpose2d_fp16_kernel<__half><<<grid, block>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
        bias_ptr,
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        N, C_in, C_out, H, W, K,
        stride, padding, groups,
        H_out, W_out);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
}
'''

# -------------------------------------------------------------------------
# Compile the inline extension
# -------------------------------------------------------------------------
_ext = load_inline(name='conv_transpose2d_fp16',
                   cpp_sources=cpp_src,
                   cuda_sources=cuda_src,
                   verbose=False)

# -------------------------------------------------------------------------
# PyTorch module that mirrors torch.nn.ConvTranspose2d using the custom kernel
# -------------------------------------------------------------------------
class ModelNew(torch.nn.Module):
    """
    Drop‑in replacement for nn.ConvTranspose2d using a custom fp16 CUDA kernel.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        # Use PyTorch's ConvTranspose2d to obtain the same weight/bias init
        self._conv = torch.nn.ConvTranspose2d(in_channels,
                                              out_channels,
                                              kernel_size,
                                              stride=stride,
                                              padding=padding,
                                              output_padding=output_padding,
                                              groups=groups,
                                              bias=bias)

        # Move to half precision on GPU
        self.weight = self._conv.weight.detach().to(dtype=torch.float16, device='cuda')
        if bias:
            self.bias = self._conv.bias.detach().to(dtype=torch.float16, device='cuda')
        else:
            self.bias = torch.empty(0,
                                    dtype=torch.float16,
                                    device='cuda')

        # Store parameters needed for kernel launch
        self.stride = stride
        self.padding = padding
        self.groups = groups
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.output_padding = output_padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C_in, H, W = x.shape
        K = self.kernel_size
        # Compute output spatial dimensions following PyTorch's formula
        H_out = (H - 1) * self.stride - 2 * self.padding + K + self.output_padding
        W_out = (W - 1) * self.stride - 2 * self.padding + K + self.output_padding

        out = torch.empty(N,
                          self.out_channels,
                          H_out,
                          W_out,
                          dtype=torch.float16,
                          device='cuda')

        _ext.forward(x,
                     self.weight,
                     self.bias,
                     out,
                     self.stride,
                     self.padding,
                     self.groups)
        return out

