  int oc  = tmp / L_out;
  int pos = tmp % L_out;

  float acc = 0.0f;
  for (int ic = 0; ic < C_in; ++ic) {
    for (int k = 0; k < K; ++k) {
      int in_idx = ((b * C_in + ic) * L) + (pos + k);
      int w_idx  = ((oc * C_in + ic) * K) + k;
      acc += __half2float(input[in_idx]) * __half2float(weight[w_idx]);
    }
  }
  output[idx] = __float2half(acc);
}

