    const int C_in  = input.size(1);
    const int L_in  = input.size(2);
    const int C_out = weight.size(0);
    const int K     = weight.size(2);
    const int L_out = (L_in + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    const int threads = 256;
    const int blocks_x = (L_out + threads - 1) / threads;

    dim3 block(threads);
    dim3 grid(blocks_x, C_out, N);

    const __half* in_ptr = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    const __half* w_ptr  = reinterpret_cast<const __half*>(weight.data_ptr<at::Half>());
    const __half* b_ptr  = bias.defined() ? reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()) : nullptr;
    __half* out_ptr       = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    const bool has_bias = bias.defined() && bias.numel() > 0;

