                   verbose=False)

# ------------------------------------------------------------------
# Autograd Function using the custom kernel for forward,
# and PyTorch's built‑in functions for backward.
# ------------------------------------------------------------------
class Conv1dFp16Function(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, weight, bias, stride, padding, dilation, groups):
        # input, weight, bias are expected to be half and contiguous
        N, C_in, L_in = input.shape
        C_out, _, K   = weight.shape
        L_out = (L_in + 2 * padding - dilation * (K - 1) - 1) // stride + 1

        output = torch.empty((N, C_out, L_out),
                             dtype=torch.float16,
                             device=input.device)

        _ext.launch_conv1d_fp16(input, weight,
                                bias if bias is not None else torch.tensor([], dtype=torch.float16, device=input.device),
                                output,
                                stride, padding, dilation, groups)

        ctx.save_for_backward(input, weight, bias if bias is not None else torch.tensor([], dtype=torch.float16, device=input.device))
        ctx.stride = stride
        ctx.padding = padding
        ctx.dilation = dilation
        ctx.groups = groups
        return output

    @staticmethod
    def backward(ctx, grad_output):
        input, weight, bias = ctx.saved_tensors
        stride = ctx.stride
        padding = ctx.padding
        dilation = ctx.dilation
        groups = ctx.groups

        # grad_input
        grad_input = torch.nn.grad.conv1d_input(
            input_shape=input.shape,
            grad_output=grad_output,
            weight=weight,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups)

        # grad_weight
        grad_weight = torch.nn.grad.conv1d_weight(
            input=input,
            grad_output=grad_output,
            weight_shape=weight.shape,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups)

        # grad_bias
        grad_bias = None
        if bias.numel() != 0 and bias.requires_grad:
            grad_bias = grad_output.sum(dim=[0, 2])

        return grad_input, grad_weight, grad_bias, None, None, None, None

# ------------------------------------------------------------------
# ModelNew – drop‑in replacement for nn.Conv1d (all tensors fp16)
# ------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        # weight in fp16, but init using float32 kaiming_uniform_
        w_fp32 = torch.empty(out_channels,
                             in_channels // groups,
                             kernel_size,
                             dtype=torch.float32,
                             device='cuda')
        nn.init.kaiming_uniform_(w_fp32, a=math.sqrt(5))
        self.weight = nn.Parameter(w_fp32.half())

        if bias:
            b_fp32 = torch.empty(out_channels,
                                 dtype=torch.float32,
                                 device='cuda')
            fan_in = in_channels * kernel_size // groups
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(b_fp32, -bound, bound)
            self.bias = nn.Parameter(b_fp32.half())
        else:
            self.bias = None

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        x = x.to(torch.float16).contiguous()
        w = self.weight.contiguous()
        b = self.bias.contiguous() if self.bias is not None else None
        return Conv1dFp16Function.apply(x, w, b,
                                        self.stride,
                                        self.padding,
                                        self.dilation,
                                        self.groups)

