#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int dilation
) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int output_pos = threadIdx.x;

    if (batch_idx >= batch_size || channel_idx >= out_channels || output_pos >= output_length) {
        return;
    }

    // Each thread processes one output position for one output channel
    float sum = 0.0f;

    for (int k = 0; k < kernel_size; ++k) {
        int input_pos = output_pos * stride + k * dilation;
        if (input_pos >= 0 && input_pos < input_length) {
            for (int c = 0; c < in_channels; ++c) {
                half input_val = input[batch_idx * (in_channels * input_length) + 
                                     c * input_length + input_pos];
                half weight_val = weight[channel_idx * (in_channels * kernel_size) + 
                                       c * kernel_size + k];
                sum += __half2float(input_val) * __half2float(weight_val);
            }
        }
    }

    output[batch_idx * (out_channels * output_length) + 
           channel_idx * output_length + output_pos] = __float2half(sum);
}

extern "C" {
void launch_conv1d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int dilation
) {
    dim3 grid(batch_size, out_channels);
    dim3 block(min(output_length, 1024));  // Limit block size for better occupancy

    conv1d_kernel<<<grid, block>>>(
        input, weight, output,
        batch_size, in_channels, out_channels,
        input_length, output_length,
        kernel_size, stride, dilation
    );

    cudaDeviceSynchronize();
}
}
