def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="conv1d_cuda",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["launch_conv1d"],
        verbose=False
    )

    class ModelNew(torch.nn.Module):
        def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, dilation: int = 1, bias: bool = False):
            super(ModelNew, self).__init__()
            self.in_channels = in_channels
            self.out_channels = out_channels
            self.kernel_size = kernel_size
            self.stride = stride
            self.dilation = dilation
            self.bias = bias

            # Initialize weights
            self.weight = torch.nn.Parameter(torch.randn(out_channels, in_channels, kernel_size, dtype=torch.float16))
            if bias:
                self.bias = torch.nn.Parameter(torch.randn(out_channels, dtype=torch.float16))
            else:
                self.register_parameter('bias', None)

        def forward(self, x: torch.Tensor) -> torch.Tensor:
            batch_size, _, input_length = x.shape

            # Compute output length
            output_length = (input_length + 2 * 0 - (self.dilation * (self.kernel_size - 1) + 1)) // self.stride + 1

            # Allocate output tensor
            output = torch.zeros(batch_size, self.out_channels, output_length, dtype=torch.float16, device=x.device)

            # Launch CUDA kernel
            module.launch_conv1d(
                x.contiguous().data_ptr(),
