                output.data_ptr(),
                batch_size,
                self.in_channels,
                self.out_channels,
                input_length,
                output_length,
                self.kernel_size,
                self.stride,
                self.dilation
            )

            # Add bias if present
            if self.bias is not None:
                output += self.bias.view(1, -1, 1)

            return output

    return ModelNew

