void conv1d_kernel(const __half* __restrict__ input,
                   const __half* __restrict__ weight,
                   __half* __restrict__ output,
                   int batch, int in_c, int out_c,
                   int length, int kernel_size,
                   int stride, int dilation, int out_len) {
