cuda_src = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

extern "C" __global__
void depthwise_conv2d_fp16_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N, int C,
    int H, int W,
    int K,
    int stride,
    int padding,
    int H_out,
    int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    // unravel linear index -> (n, c, oh, ow)
    int ow = idx % W_out;
    int tmp = idx / W_out;
    int oh = tmp % H_out;
    tmp = tmp / H_out;
    int c = tmp % C;
    int n = tmp / C;

    float sum = 0.0f;
    int h_start = oh * stride - padding;
    int w_start = ow * stride - padding;

    const __half* w_ptr = weight + c * K * K;   // per‑channel kernel

    for (int kh = 0; kh < K; ++kh) {
        int ih = h_start + kh;
        if (ih < 0 || ih >= H) continue;
        for (int kw = 0; kw < K; ++kw) {
            int iw = w_start + kw;
            if (iw < 0 || iw >= W) continue;
            int in_off = ((n * C + c) * H + ih) * W + iw;
            float val = __half2float(input[in_off]);
            float wgt = __half2float(w_ptr[kh * K + kw]);
            sum += val * wgt;
        }
    }

    if (bias != nullptr) {
        sum += __half2float(bias[c]);
    }

    output[idx] = __float2half(sum);
}

// ------------------------------------------------------------------
// Wrapper callable from Python (compiled with NVCC)
// ------------------------------------------------------------------
extern "C"
torch::Tensor depthwise_conv2d_fp16(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat16, "input must be fp16");
    TORCH_CHECK(weight.dtype() == torch::kFloat16, "weight must be fp16");
    if (bias.defined()) {
        TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias.dtype() == torch::kFloat16, "bias must be fp16");
    }

    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int K = weight.size(2);
    const int H_out = (H + 2 * padding - K) / stride + 1;
    const int W_out = (W + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    const int threads = 256;
    const int total = N * C * H_out * W_out;
    const int blocks = (total + threads - 1) / threads;

    const __half* input_ptr  = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    const __half* weight_ptr = reinterpret_cast<const __half*>(weight.data_ptr<at::Half>());
    const __half* bias_ptr   = (bias.defined() && bias.numel() > 0)
                               ? reinterpret_cast<const __half*>(bias.data_ptr<at::Half>())
                               : nullptr;
    __half* output_ptr = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    depthwise_conv2d_fp16_kernel<<<blocks, threads>>>(
        input_ptr,
        weight_ptr,
        bias_ptr,
        output_ptr,
        N, C,
        H, W,
        K,
        stride,
        padding,
        H_out,
        W_out
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch failed: ") + cudaGetErrorString(err));
    }

    return output;
}
