#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

template <int K>
__global__ void depthwise_conv_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,   // nullptr if not used
    __half* __restrict__ output,
    int batch,
    int channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int stride,
    int padding)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * out_h * out_w;
    for (int i = idx; i < total; i += blockDim.x * gridDim.x) {
        int w_out = i % out_w;
        int tmp = i / out_w;
        int h_out = tmp % out_h;
        int tmp2 = tmp / out_h;
        int c = tmp2 % channels;
        int b = tmp2 / channels;

        float acc = 0.0f;
        #pragma unroll
        for (int ky = 0; ky < K; ++ky) {
            int in_y = h_out * stride - padding + ky;
            if (in_y < 0 || in_y >= in_h) continue;
            #pragma unroll
            for (int kx = 0; kx < K; ++kx) {
                int in_x = w_out * stride - padding + kx;
                if (in_x < 0 || in_x >= in_w) continue;

                int input_idx = ((b * channels + c) * in_h + in_y) * in_w + in_x;
                int weight_idx = (c * K + ky) * K + kx;   // (C, K, K)

                acc += __half2float(input[input_idx]) *
                       __half2float(weight[weight_idx]);
            }
        }

        if (bias != nullptr) {
            acc += __half2float(bias[c]);
        }

        output[i] = __float2half(acc);
    }
}

torch::Tensor depthwise_conv_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(weight.dtype() == torch::kHalf, "weight must be fp16");
    if (bias.defined()) {
        TORCH_CHECK(bias.is_cuda(), "bias must be CUDA tensor");
        TORCH_CHECK(bias.dtype() == torch::kHalf, "bias must be fp16");
    }

    const int batch   = input.size(0);
    const int channels = input.size(1);
    const int in_h    = input.size(2);
    const int in_w    = input.size(3);
    const int k       = weight.size(1);   // weight shape (C, K, K)

    const int out_h = (in_h + 2 * padding - k) / stride + 1;
    const int out_w = (in_w + 2 * padding - k) / stride + 1;

    auto output = torch::empty({batch, channels, out_h, out_w}, input.options());

    const dim3 block(256);
    const dim3 grid((batch * channels * out_h * out_w + block.x - 1) / block.x);

    const __half* input_ptr  = reinterpret_cast<const __half*>(input.data_ptr());
    const __half* weight_ptr = reinterpret_cast<const __half*>(weight.data_ptr());

    const __half* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = reinterpret_cast<const __half*>(bias.data_ptr());
    }

    __half* output_ptr = reinterpret_cast<__half*>(output.data_ptr());

    // launch the appropriate specialization based on kernel size
    if (k == 1) {
        depthwise_conv_kernel<1><<<grid, block>>>(
            input_ptr, weight_ptr, bias_ptr, output_ptr,
            batch, channels, in_h, in_w, out_h, out_w,
            static_cast<int>(stride), static_cast<int>(padding));
    } else if (k == 2) {
        depthwise_conv_kernel<2><<<grid, block>>>(
            input_ptr, weight_ptr, bias_ptr, output_ptr,
            batch, channels, in_h, in_w, out_h, out_w,
            static_cast<int>(stride), static_cast<int>(padding));
    } else if (k == 3) {
        depthwise_conv_kernel<3><<<grid, block>>>(
            input_ptr, weight_ptr, bias_ptr, output_ptr,
            batch, channels, in_h, in_w, out_h, out_w,
            static_cast<int>(stride), static_cast<int>(padding));
    } else if (k == 5) {
        depthwise_conv_kernel<5><<<grid, block>>>(
            input_ptr, weight_ptr, bias_ptr, output_ptr,
            batch, channels, in_h, in_w, out_h, out_w,
            static_cast<int>(stride), static_cast<int>(padding));
    } else {
        // generic fallback for any other kernel size up to 7 (unrolled)
        depthwise_conv_kernel<7><<<grid, block>>>(
            input_ptr, weight_ptr, bias_ptr, output_ptr,
            batch, channels, in_h, in_w, out_h, out_w,
            static_cast<int>(stride), static_cast<int>(padding));
    }

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("depthwise_conv_forward", &depthwise_conv_forward,
