#include <cuda_runtime.h>

extern "C" __global__
void depthwise_conv2d_forward_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N, int C, int H, int W,
    int K, int stride, int padding,
    int H_out, int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int tmp   = idx / W_out;
    int h_out = tmp % H_out;
    tmp       = tmp / H_out;
    int c     = tmp % C;
    int n     = tmp / C;

    float sum = 0.0f;

    #pragma unroll
    for (int kh = 0; kh < K; ++kh) {
        int h_in = h_out * stride - padding + kh;
        if (h_in < 0 || h_in >= H) continue;
        #pragma unroll
        for (int kw = 0; kw < K; ++kw) {
            int w_in = w_out * stride - padding + kw;
            if (w_in < 0 || w_in >= W) continue;

            int input_idx  = ((n * C + c) * H + h_in) * W + w_in;
            int weight_idx = ((c * K) + kh) * K + kw;   // (C, K, K) layout

            sum += __half2float(input[input_idx]) *
                   __half2float(weight[weight_idx]);
        }
    }

    if (bias != nullptr) {
        sum += __half2float(bias[c]);
    }

    output[idx] = __float2half(sum);
}

