extern "C" void depthwise_conv2d_forward_cuda(
    const __half* input,
    const __half* weight,
    const __half* bias,
    __half* output,
    int N, int C, int H, int W,
    int K, int stride, int padding,
    int H_out, int W_out,
    cudaStream_t stream)
{
    int total   = N * C * H_out * W_out;
    int threads = 256;
    int blocks  = (total + threads - 1) / threads;

    depthwise_conv2d_forward_kernel<<<blocks, threads, 0, stream>>>(
        input, weight, bias, output,
        N, C, H, W,
        K, stride, padding,
        H_out, W_out);
}
