# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__device__ __forceinline__ half add_half(half a, half b) {
    return __hadd(a, b);
}

__device__ __forceinline__ half make_half(float f) {
    return __float2half(f);
}

__device__ __forceinline__ float half_to_float(half h) {
    return __half2float(h);
}

// Optimized parallel prefix sum using shared memory
__global__ void scan_kernel(const half* input, half* output, int total_elements, int scan_dim_size, int prefix_elements) {
    extern __shared__ half shared_data[];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Process each element in the scan dimension
    for (int elem_offset = 0; elem_offset < scan_dim_size; elem_offset += blockDim.x) {
        int global_idx = batch_idx * prefix_elements * scan_dim_size + elem_offset + tid;

        // Load data into shared memory
        if (elem_offset + tid < scan_dim_size) {
            shared_data[tid] = input[global_idx];
        } else {
            shared_data[tid] = make_half(0.0f);
        }

        __syncthreads();

        // Up-sweep (reduce) phase
        for (int stride = 1; stride < blockDim.x; stride *= 2) {
            int index = (tid + 1) * stride * 2 - 1;
            if (index < blockDim.x) {
                shared_data[index] = add_half(shared_data[index], shared_data[index - stride]);
            }
            __syncthreads();
        }

