__global__ void scan_kernel(const half* input, half* output, int total_elements, int dim_size, int stride) {
    extern __shared__ half shared_data[];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Each block processes one batch
    int base_offset = batch_idx * stride;

    // Load data into shared memory
    if (base_offset + tid < total_elements && tid < dim_size) {
        shared_data[tid] = input[base_offset + tid];
    } else if (tid < dim_size) {
        shared_data[tid] = __float2half(0.0f);
    }
    __syncthreads();

    // Up-sweep (reduce) phase
    for (int stride_size = 1; stride_size < dim_size; stride_size *= 2) {
        int index = (tid + 1) * stride_size * 2 - 1;
        if (index < dim_size) {
            shared_data[index] = __hadd(shared_data[index], shared_data[index - stride_size]);
        }
        __syncthreads();
    }

    // Clear the last element for down-sweep
    if (tid == 0 && dim_size > 0) {
        shared_data[dim_size - 1] = __float2half(0.0f);
    }
    __syncthreads();

    // Down-sweep phase
    for (int stride_size = dim_size / 2; stride_size > 0; stride_size /= 2) {
        int index = (tid + 1) * stride_size * 2 - 1;
        if (index < dim_size) {
            half temp = shared_data[index];
            shared_data[index] = __hadd(shared_data[index], shared_data[index - stride_size]);
            shared_data[index - stride_size] = temp;
        }
        __syncthreads();
    }

    // Write results back
    if (base_offset + tid < total_elements && tid < dim_size) {
        output[base_offset + tid] = shared_data[tid];
    }
}

__global__ void scan_kernel_simple(const half* input, half* output, int total_elements, int dim_size, int stride) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    int base_offset = batch_idx * stride;

    // Simple sequential scan for small arrays
    if (base_offset + tid < total_elements && tid < dim_size) {
        half sum = __float2half(0.0f);
        for (int i = 0; i <= tid; i++) {
            sum = __hadd(sum, input[base_offset + i]);
        }
        output[base_offset + tid] = sum;
    }
}

