#include <thrust/equal.h>
#include <thrust/execution_policy.h>
#include <thrust/iterator/counting_iterator.h>
#include <thrust/iterator/transform_iterator.h>
#include <thrust/scan.h>

// Functor that extracts the segment id (row index) for a flattened index
struct SegmentKeyFunctor {
    const int64_t segment_len; // length of the scan dimension
    __host__ __device__ SegmentKeyFunctor(int64_t seg_len) : segment_len(seg_len) {}
    __host__ __device__ int64_t operator()(int64_t idx) const {
        return idx / segment_len;
    }
};

// Half addition functor (uses native __hadd for fp16)
struct HalfAdd {
    __host__ __device__
    __half operator()(const __half& a, const __half& b) const {
#if __CUDA_ARCH__ >= 530
        return __hadd(a, b);
#else
        // Fallback: promote to float
        return __float2half(__half2float(a) + __half2float(b));
#endif
    }
};

void launch_cumsum(const torch::Tensor& input,
                   torch::Tensor& output,
                   int64_t dim) {
    // ---------------------------------------------------------------
    // Checks
    // ---------------------------------------------------------------
    TORCH_CHECK(input.is_cuda() && output.is_cuda(),
                "launch_cumsum expects CUDA tensors");
    TORCH_CHECK(input.dtype() == torch::kHalf && output.dtype() == torch::kHalf,
                "launch_cumsum expects fp16 tensors");
    TORCH_CHECK(input.is_contiguous() && output.is_contiguous(),
                "launch_cumsum expects contiguous tensors");

