    // Flatten so that the scan dimension becomes the innermost one.
    // ---------------------------------------------------------------
    int64_t dim_len = input.size(dim);
    int64_t outer = input.numel() / dim_len;          // number of independent scans

    const __half* in_ptr  = reinterpret_cast<const __half*>(input.data_ptr());
    __half*       out_ptr = reinterpret_cast<__half*>(output.data_ptr());

    thrust::device_ptr<const __half> d_in (in_ptr);
    thrust::device_ptr<__half>       d_out(out_ptr);

