    auto idx_begin = thrust::make_counting_iterator<int64_t>(0);
    auto idx_end   = idx_begin + outer * dim_len;

    // Transform iterator that yields the segment/key for each index
    auto key_begin = thrust::make_transform_iterator(
                        idx_begin,
                        SegmentKeyFunctor(dim_len));

    // Inclusive segmented scan: for each row (key) compute prefix sum
    thrust::inclusive_scan_by_key(
        thrust::device,               // execution policy
        key_begin,                    // keys first
        key_begin + outer * dim_len,  // keys last
        d_in,                         // values first
        d_out,                        // output
