#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void cumsum_kernel(const scalar_t* __restrict__ input,
                              scalar_t* __restrict__ output,
                              int64_t outer,
                              int64_t dim_size,
                              int64_t inner) {
    // each thread processes one (outer, inner) line
    int64_t tid  = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = outer * inner;

    for (int64_t idx = tid; idx < total; idx += blockDim.x * gridDim.x) {
        int64_t outer_idx = idx / inner;
        int64_t inner_idx = idx % inner;

        float acc = 0.0f;
        #pragma unroll 8
        for (int64_t d = 0; d < dim_size; ++d) {
            // linear offset for element (outer_idx, d, inner_idx)
            int64_t offset = ((outer_idx * dim_size) + d) * inner + inner_idx;
            acc += __half2float(input[offset]);
            output[offset] = __float2half(acc);
        }
    }
