void cumsum_cuda(at::Tensor input, at::Tensor output, int64_t dim) {
    const int threads = 256;

    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(output.is_contiguous(), "output must be contiguous");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be float16");
    TORCH_CHECK(output.dtype() == torch::kHalf, "output must be float16");

    // compute sizes surrounding the scan dimension
    int64_t dim_size = input.size(dim);
    int64_t outer = 1;
    for (int i = 0; i < dim; ++i) outer *= input.size(i);
    int64_t inner = 1;
    for (int i = dim + 1; i < input.dim(); ++i) inner *= input.size(i);

    int64_t total_pairs = outer * inner;
    int64_t blocks = (total_pairs + threads - 1) / threads;

    const __half* in_ptr  = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    __half* out_ptr = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    cumsum_kernel<__half><<<blocks, threads>>>(
        in_ptr, out_ptr, outer, dim_size, inner);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
