    uint64_t offset = static_cast<uint64_t>(line) * static_cast<uint64_t>(size_dim);
    const __half* in_line  = in + offset;
    __half*       out_line = out + offset;

    float acc = 0.0f;
    #pragma unroll 4
    for (int64_t i = 0; i < size_dim; ++i) {
        acc += __half2float(in_line[i]);
        out_line[i] = __float2half(acc);
    }
}

