void cumsum_fp16_launch(const torch::Tensor& input,
                        torch::Tensor& output,
                        int64_t size_dim,
                        int64_t lines) {
    const dim3 grid(static_cast<unsigned int>(lines));
    const dim3 block(1);   // one thread per block suffices for sequential scan

