#include <torch/extension.h>
#include <ATen/Functions.h>
#include <ATen/cuda/CUDAContext.h>

torch::Tensor wmma_matmul_fp16(torch::Tensor A, torch::Tensor B) {
    // sanity checks – match reference expectations
    TORCH_CHECK(A.dtype() == torch::kHalf, "A must be fp16");
    TORCH_CHECK(B.dtype() == torch::kHalf, "B must be fp16");
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(),
                "inputs must be contiguous");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "inputs must be 2‑D matrices");
    TORCH_CHECK(A.size(1) == B.size(0), "inner dimensions must match");

    // Delegate to ATen's mm (cuBLAS) – works for half precision and uses Tensor Cores.
    return at::mm(A, B);
}
'''

