    __shared__ __half As[TILE_M][TILE_K];
    __shared__ __half Bs[TILE_K][TILE_N];

    int tx = threadIdx.x;   // column inside tile
    int ty = threadIdx.y;   // row inside tile

    int row = blockIdx.y * TILE_M + ty;
    int col = blockIdx.x * TILE_N + tx;

