// ------------------------------------------------------------------
// Kernel: computes C = A * B  (A: MxK, B: KxN, C: MxN)
// All tensors are half (fp16). Accumulation is done in float.
// ------------------------------------------------------------------
__global__ void gemm_fp16_kernel(const half* __restrict__ A,
                                 const half* __restrict__ B,
                                 half* __restrict__ C,
                                 int M, int K, int N) {
    // thread indices within the tile
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    // global row and column this thread works on
    const int row = blockIdx.y * TILE + ty;
    const int col = blockIdx.x * TILE + tx;

    // shared memory tiles
    __shared__ half As[TILE][TILE];
    __shared__ half Bs[TILE][TILE];

    float acc = 0.0f;

    // iterate over K dimension tiles
    const int numTiles = (K + TILE - 1) / TILE;
    for (int t = 0; t < numTiles; ++t) {
        // load A tile
        int a_row = row;
        int a_col = t * TILE + tx;
        if (a_row < M && a_col < K) {
            As[ty][tx] = A[a_row * K + a_col];
        } else {
            As[ty][tx] = __float2half(0.0f);
        }

        // load B tile
        int b_row = t * TILE + ty;
        int b_col = col;
        if (b_row < K && b_col < N) {
            Bs[ty][tx] = B[b_row * N + b_col];
        } else {
            Bs[ty][tx] = __float2half(0.0f);
        }

        __syncthreads();

        // compute partial product
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += __half2float(As[ty][k]) * __half2float(Bs[k][tx]);
        }

        __syncthreads();
    }

    // write result
    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

