    half* shmem_A = shmem;                                   // BLOCK_M * BLOCK_K
    half* shmem_B = shmem + BLOCK_M * BLOCK_K;               // BLOCK_K * BLOCK_N

    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    int thread_lane = threadIdx.x; // 0..31 within a warp
    int warp_id = threadIdx.y;     // 0..3 (4 warps per block)

    int warp_row = warp_id / 2;    // 0 or 1
    int warp_col = warp_id % 2;    // 0 or 1

    int c_tile_row = block_row * BLOCK_M + warp_row * WMMA_M;
    int c_tile_col = block_col * BLOCK_N + warp_col * WMMA_N;

    wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, half, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, half, wmma::col_major> b_frag;
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> c_frag;

    wmma::fill_fragment(c_frag, 0.0f);

