                         ? A[global_row * K + global_col]
                         : __float2half(0.0f);
        }

        // ---- load B tile into shared memory ----
        for (int i = thread_lane; i < BLOCK_K * BLOCK_N; i += 32) {
            int row = i / BLOCK_N;
            int col = i % BLOCK_N;
            int global_row = tile_k * BLOCK_K + row;
            int global_col = block_col * BLOCK_N + col;
            shmem_B[i] = (global_row < K && global_col < N)
                         ? B[global_row * N + global_col]
                         : __float2half(0.0f);
