#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#define TILE_M 32
#define TILE_N 32
#define TILE_K 32

// -----------------------------------------------------------------------------
// Tiled FP16 GEMM with FP32 accumulation
// -----------------------------------------------------------------------------
__global__ void matmul_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int M, int K, int N) {
    // Block indices
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Thread indices within the block
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    // Global row/col this thread computes
    int row = blockRow * TILE_M + threadRow;
    int col = blockCol * TILE_N + threadCol;

    // Shared memory tiles
    __shared__ half As[TILE_M][TILE_K];
    __shared__ half Bs[TILE_K][TILE_N];

    float acc = 0.0f;  // FP32 accumulator

    int numTiles = (K + TILE_K - 1) / TILE_K;
    for (int t = 0; t < numTiles; ++t) {
        // Load tile of A
        int aRow = row;
        int aCol = t * TILE_K + threadCol;
        As[threadRow][threadCol] = (aRow < M && aCol < K)
                                   ? A[aRow * K + aCol]
                                   : __float2half(0.0f);

        // Load tile of B
        int bRow = t * TILE_K + threadRow;
        int bCol = col;
        Bs[threadRow][threadCol] = (bRow < K && bCol < N)
                                   ? B[bRow * N + bCol]
                                   : __float2half(0.0f);

        __syncthreads();

