#define CHECK_SAME_SHAPE(x, y) TORCH_CHECK(x.sizes() == y.sizes(), #x " and " #y " must have the same shape")
#endif

// ---------------------------------------------------------------
// Kernel: sum of squared differences (float32 accumulation)
// Vectorized loads via __half2, block‑level reduction using warp shuffles.
// ---------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void mse_kernel(const __half* __restrict__ pred,
                           const __half* __restrict__ target,
                           float* __restrict__ global_sum,
                           size_t N) {
    constexpr int WARP_SIZE = 32;
    float thread_sum = 0.0f;

    size_t idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    size_t stride = gridDim.x * BLOCK_SIZE;

    for (size_t i = idx; i < N; i += stride) {
        if (i + 1 < N) {
            // load two half values at once
            __half2 p = __halves2half2(pred[i], pred[i + 1]);
            __half2 t = __halves2half2(target[i], target[i + 1]);
            float2 pf = __half22float2(p);
            float2 tf = __half22float2(t);
            float d0 = pf.x - tf.x;
            float d1 = pf.y - tf.y;
            thread_sum += d0 * d0 + d1 * d1;
        } else {
            float d = __half2float(pred[i]) - __half2float(target[i]);
            thread_sum += d * d;
        }
    }

    // -------- warp‑level reduction (shuffle) --------
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        thread_sum += __shfl_down_sync(0xffffffff, thread_sum, offset);
    }

    // store one value per warp
    __shared__ float warp_sums[BLOCK_SIZE / WARP_SIZE];
    if (threadIdx.x % WARP_SIZE == 0) {
        warp_sums[threadIdx.x / WARP_SIZE] = thread_sum;
    }
    __syncthreads();

    // second reduction across warps (first warp does the work)
    if (threadIdx.x < BLOCK_SIZE / WARP_SIZE) {
        float sum = warp_sums[threadIdx.x];
        for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        if (threadIdx.x == 0) {
            atomicAdd(global_sum, sum);
        }
    }
}

