// ------------------------------------------------------------------
// kernel: each thread accumulates in FP32, block‑wise reduction in shared mem
// ------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void mse_kernel(const half* __restrict__ pred,
                           const half* __restrict__ target,
                           float* __restrict__ out,
                           size_t N) {
    float sum = 0.0f;
    // stride loop over the whole tensor
    for (size_t idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
         idx < N;
         idx += gridDim.x * BLOCK_SIZE) {
        float p = __half2float(pred[idx]);
        float t = __half2float(target[idx]);
        float d = p - t;
        sum += d * d;
    }

    // ---- block reduction in shared memory ----
    __shared__ float shmem[BLOCK_SIZE];
    shmem[threadIdx.x] = sum;
    __syncthreads();

    // reduction tree (BLOCK_SIZE assumed power‑of‑two)
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shmem[threadIdx.x] += shmem[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // first thread writes block result to global accumulator
    if (threadIdx.x == 0) {
        atomicAdd(out, shmem[0]);
    }
}

