    const int BLOCK_SIZE = 256;
    const int MAX_BLOCKS = 65535;

    int blocks = static_cast<int>((N + BLOCK_SIZE - 1) / BLOCK_SIZE);
    if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;

