    const half* target_ptr = reinterpret_cast<const half*>(target.data_ptr<at::Half>());
    float* out_ptr         = out.data_ptr<float>();

    // launch kernel
    mse_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE>>>(
        pred_ptr,
        target_ptr,
        out_ptr,
        N
    );

    cudaError_t err = cudaGetLastError();
