    val.x += __shfl_down_sync(0xffffffff, val.x, 1);
    val.y += __shfl_down_sync(0xffffffff, val.y, 1);
    return val;
}

__global__ void scaled_dot_product_attention_kernel(
    const half* Q,
    const half* K,
    const half* V,
    half* output,
    int batch_size,
    int num_heads,
    int sequence_length,
    int embedding_dimension
) {
    int batch_idx = blockIdx.x;
    int head_idx = blockIdx.y;

    if (batch_idx >= batch_size || head_idx >= num_heads) return;

    const int stride = sequence_length * embedding_dimension;
    const int q_offset = batch_idx * num_heads * stride + head_idx * stride;
    const int k_offset = batch_idx * num_heads * stride + head_idx * stride;
    const int v_offset = batch_idx * num_heads * stride + head_idx * stride;
    const int out_offset = batch_idx * num_heads * stride + head_idx * stride;

    const float scale = 1.0f / sqrtf(static_cast<float>(embedding_dimension));

    // Shared memory for attention scores and values
    extern __shared__ char shared_mem[];
    float* shared_scores = reinterpret_cast<float*>(shared_mem);

    for (int i = 0; i < sequence_length; ++i) {
        const int q_row_offset = i * embedding_dimension;

        // Compute attention scores for this query position
        for (int j = 0; j < sequence_length; ++j) {
            float sum = 0.0f;
            for (int k = 0; k < embedding_dimension; ++k) {
                float q_val = __half2float(Q[q_offset + q_row_offset + k]);
                float k_val = __half2float(K[k_offset + j * embedding_dimension + k]);
                sum += q_val * k_val;
            }
            shared_scores[j] = sum * scale;
        }

        // Apply softmax to attention scores
        float max_val = shared_scores[0];
        for (int j = 1; j < sequence_length; ++j) {
            max_val = fmaxf(max_val, shared_scores[j]);
        }

        float sum_exp = 0.0f;
        for (int j = 0; j < sequence_length; ++j) {
            shared_scores[j] = expf(shared_scores[j] - max_val);
            sum_exp += shared_scores[j];
        }

        for (int j = 0; j < sequence_length; ++j) {
            shared_scores[j] /= sum_exp;
        }

        // Compute output for this query position
        for (int k = 0; k < embedding_dimension; ++k) {
            float result = 0.0f;
            for (int j = 0; j < sequence_length; ++j) {
                float attn_weight = shared_scores[j];
                float v_val = __half2float(V[v_offset + j * embedding_dimension + k]);
                result += attn_weight * v_val;
            }
            output[out_offset + i * embedding_dimension + k] = __float2half(result);
        }
    }
}

