    // Shared memory for attention scores (float)
    extern __shared__ float shm[];
    float* scores = shm;               // size = S

    // ----------------------------------------------------------------
    // 1) Compute raw scores = (Q_i · K_j) * scale for all j
    // ----------------------------------------------------------------
    if (tid == 0) {
        int base_q = ((b * H + h) * S + i) * D;
        float max_score = -FLT_MAX;

