// ---------------------------------------------------------------------------
// Dot product for half vectors with float accumulation
// ---------------------------------------------------------------------------
__device__ __forceinline__ float dot_half(const __half* a,
                                          const __half* b,
                                          const int D) {
    float acc = 0.0f;
#pragma unroll
    for (int i = 0; i < D; ++i) {
        acc += __half2float(a[i]) * __half2float(b[i]);
    }
    return acc;
}

// ---------------------------------------------------------------------------
// Scaled dot‑product attention kernel
// Q, K, V, out : [B, H, S, D] row‑major, half
// ---------------------------------------------------------------------------
extern "C" __global__
void attn_forward_kernel(const __half* __restrict__ Q,
                         const __half* __restrict__ K,
                         const __half* __restrict__ V,
                         __half* __restrict__ out,
                         const int B,
                         const int H,
                         const int S,
                         const int D) {
    const int bh   = blockIdx.x;   // batch * head index
    const int qpos = blockIdx.y;   // query position
    const int d    = threadIdx.x;  // feature dimension index
    if (d >= D) return;

    const __half* Q_ptr = Q + ((bh * S) + qpos) * D;   // Q[bh, qpos, :]
    const __half* K_ptr = K + (bh * S) * D;           // K[bh, :, :]
    const __half* V_ptr = V + (bh * S) * D;           // V[bh, :, :]

    const float scale = 1.0f / sqrtf(static_cast<float>(D));

    // -----------------------------------------------------------------------
    // 1) max score (for numerical stability)
    // -----------------------------------------------------------------------
    float max_score = -FLT_MAX;
    for (int j = 0; j < S; ++j) {
        const __half* K_row = K_ptr + j * D;
        float score = dot_half(Q_ptr, K_row, D) * scale;
        max_score = fmaxf(score, max_score);
    }

    // -----------------------------------------------------------------------
    // 2) sum of exp(score - max)
    // -----------------------------------------------------------------------
    float sum_exp = 0.0f;
    for (int j = 0; j < S; ++j) {
        const __half* K_row = K_ptr + j * D;
        float score = dot_half(Q_ptr, K_row, D) * scale;
        sum_exp += expf(score - max_score);
    }

    // -----------------------------------------------------------------------
    // 3) weighted sum over V
    // -----------------------------------------------------------------------
    float out_val = 0.0f;
    for (int j = 0; j < S; ++j) {
        const __half* K_row = K_ptr + j * D;
        const __half* V_elem = V_ptr + j * D + d;
        float score = dot_half(Q_ptr, K_row, D) * scale;
        float weight = expf(score - max_score) / sum_exp;
        out_val += weight * __half2float(*V_elem);
    }

    out[((bh * S) + qpos) * D + d] = __float2half(out_val);
}

// ---------------------------------------------------------------------------
// Host launcher (exposed to Python via pybind11)
// ---------------------------------------------------------------------------
void attn_forward(at::Tensor Q,
                  at::Tensor K,
                  at::Tensor V,
                  at::Tensor out) {
    const int B = Q.size(0);
    const int H = Q.size(1);
    const int S = Q.size(2);
    const int D = Q.size(3);

    const dim3 grid(B * H, S);
    const dim3 block(D);

    attn_forward_kernel<<<grid, block, 0,
        at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(out.data_ptr<at::Half>()),
        B, H, S, D);

    cudaGetLastError(); // propagate launch errors
}
