cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cfloat>
#include <cmath>

// ------------------------------------------------------------------
// Helper to convert half to float for accumulation
// ------------------------------------------------------------------
inline __device__ float to_float(__half x) { return __half2float(x); }
inline __device__ float to_float(float x) { return x; }

// ------------------------------------------------------------------
// Kernel: naive fused scaled dot‑product attention
// ------------------------------------------------------------------
template <typename scalar_t>
__global__ void fused_sdpa_kernel(
    const scalar_t* __restrict__ Q,
    const scalar_t* __restrict__ K,
    const scalar_t* __restrict__ V,
    scalar_t* __restrict__ Out,
    int B, int H, int S, int D)
{
    // One thread per output element (b, h, i, d)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    long long total = 1LL * B * H * S * D;
    if (idx >= total) return;

    // Decode linear index
    int d = idx % D;      idx /= D;
    int i = idx % S;      idx /= S;
    int h = idx % H;      idx /= H;
    int b = idx;          // remaining

    const int q_offset = ((b * H + h) * S + i) * D;
    const int out_offset = q_offset + d;

    const float scale = rsqrtf(static_cast<float>(D));

    // ---------- 1) Max score ----------
    float max_score = -FLT_MAX;
    for (int j = 0; j < S; ++j) {
        float dot = 0.0f;
        const int k_offset = ((b * H + h) * S + j) * D;
        #pragma unroll 4
        for (int dd = 0; dd < D; ++dd) {
            float qv = to_float(Q[q_offset + dd]);
            float kv = to_float(K[k_offset + dd]);
            dot += qv * kv;
        }
        dot *= scale;
        max_score = fmaxf(max_score, dot);
    }

    // ---------- 2) Sum of exp ----------
    float sum_exp = 0.0f;
    for (int j = 0; j < S; ++j) {
        float dot = 0.0f;
        const int k_offset = ((b * H + h) * S + j) * D;
        #pragma unroll 4
        for (int dd = 0; dd < D; ++dd) {
            float qv = to_float(Q[q_offset + dd]);
            float kv = to_float(K[k_offset + dd]);
            dot += qv * kv;
        }
        dot *= scale;
        sum_exp += expf(dot - max_score);
    }

    // ---------- 3) Weighted sum over V ----------
    float out_val = 0.0f;
    for (int j = 0; j < S; ++j) {
        float dot = 0.0f;
        const int k_offset = ((b * H + h) * S + j) * D;
        #pragma unroll 4
        for (int dd = 0; dd < D; ++dd) {
            float qv = to_float(Q[q_offset + dd]);
            float kv = to_float(K[k_offset + dd]);
            dot += qv * kv;
        }
        dot *= scale;
        float prob = expf(dot - max_score) / sum_exp;

        const int v_offset = ((b * H + h) * S + j) * D + d;
        float vv = to_float(V[v_offset]);
        out_val += prob * vv;
    }

    Out[out_offset] = static_cast<scalar_t>(out_val);
}

// ------------------------------------------------------------------
// Host wrapper that launches the kernel
// ------------------------------------------------------------------
torch::Tensor fused_sdpa(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(),
                "All inputs must be CUDA tensors");
    TORCH_CHECK(Q.dtype() == torch::kFloat16 &&
                K.dtype() == torch::kFloat16 &&
                V.dtype() == torch::kFloat16,
                "All inputs must be float16");

    const int B = Q.size(0);
    const int H = Q.size(1);
    const int S = Q.size(2);
    const int D = Q.size(3);

    auto Out = torch::empty_like(Q);

    const int threads = 256;
    const int64_t total = 1LL * B * H * S * D;
    const int blocks = static_cast<int>((total + threads - 1) / threads);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(Q.scalar_type(), "fused_sdpa_kernel", [&] {
        fused_sdpa_kernel<scalar_t><<<blocks, threads>>>(
            Q.data_ptr<scalar_t>(),
            K.data_ptr<scalar_t>(),
            V.data_ptr<scalar_t>(),
            Out.data_ptr<scalar_t>(),
            B, H, S, D);
    });

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch failed: ") +
                                 cudaGetErrorString(err));
    }
    return Out;
}
'''

