            dot += __half2float(q_ptr[d]) * __half2float(k_ptr[d]);
        }
        float scaled = dot * scale;
        if (scaled > max_score) max_score = scaled;
    }

    // ---------- sum of exp ----------
    float sum_exp = 0.0f;
    for (int k = 0; k < S; ++k) {
        const half* k_ptr = K + (((b * H) + h) * S + k) * D;
        float dot = 0.0f;
        #pragma unroll 4
        for (int d = 0; d < D; ++d) {
            dot += __half2float(q_ptr[d]) * __half2float(k_ptr[d]);
        }
        float scaled = dot * scale;
        sum_exp += expf(scaled - max_score);
    }

    // ---------- weighted sum of V ----------
    // D ≤ 1024 in the reference; static allocation is safe.
    float acc[1024];
    #pragma unroll 4
    for (int d = 0; d < D; ++d) acc[d] = 0.0f;

    for (int k = 0; k < S; ++k) {
        const half* k_ptr = K + (((b * H) + h) * S + k) * D;
        const half* v_ptr = V + (((b * H) + h) * S + k) * D;
        float dot = 0.0f;
