.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // --------------------------------------------------------------------
    // Load parameters
    // --------------------------------------------------------------------
    .reg .u64 a_ptr, b_ptr, c_ptr;
    .reg .u32 M_reg, N_reg, K_reg;

    ld.param.u64 a_ptr, [A_ptr];
    ld.param.u64 b_ptr, [B_ptr];
    ld.param.u64 c_ptr, [C_ptr];
    ld.param.u32 M_reg, [M];
    ld.param.u32 N_reg, [N];
    ld.param.u32 K_reg, [K];

    // --------------------------------------------------------------------
    // Thread/block indices
    // --------------------------------------------------------------------
    .reg .u32 tid_x, tid_y;
    mov.u32 tid_x, %tid.x;
    mov.u32 tid_y, %tid.y;

    .reg .u32 blk_x, blk_y;
    mov.u32 blk_x, %ctaid.x;
    mov.u32 blk_y, %ctaid.y;

    .reg .u32 dim_x, dim_y;
    mov.u32 dim_x, %ntid.x;
    mov.u32 dim_y, %ntid.y;

    // --------------------------------------------------------------------
    // Compute output coordinates (row, col)
    // --------------------------------------------------------------------
    .reg .u32 row, col;
    mad.lo.u32 row, blk_y, dim_y, tid_y;   // row = blk_y * dim_y + tid_y
    mad.lo.u32 col, blk_x, dim_x, tid_x;   // col = blk_x * dim_x + tid_x

    // --------------------------------------------------------------------
    // Bounds check
    // --------------------------------------------------------------------
    .reg .pred p_out;
    setp.ge.u32 p_out, row, M_reg;
    @p_out bra DONE;
    setp.ge.u32 p_out, col, N_reg;
    @p_out bra DONE;

    // --------------------------------------------------------------------
    // Accumulator (float32)
    // --------------------------------------------------------------------
    .reg .f32 sum;
    mov.f32 sum, 0f;

    // --------------------------------------------------------------------
    // Main K-loop
    // --------------------------------------------------------------------
    .reg .u32 k;
    mov.u32 k, 0;

K_LOOP:
    setp.ge.u32 p_out, k, K_reg;
    @p_out bra K_DONE;

    // Load A[row, k] (half)
    .reg .u32 a_idx;
    mad.lo.u32 a_idx, row, K_reg, k;          // row*K + k
    .reg .u64 a_off;
    cvt.u64.u32 a_off, a_idx;
    shl.b64 a_off, a_off, 1;                  // *2 bytes
    .reg .u64 a_addr;
    add.u64 a_addr, a_ptr, a_off;
    .reg .f16 a_val;
    ld.global.f16 a_val, [a_addr];

    // Load B[col, k] (half)  (B is stored as (N, K), we need B.T)
    .reg .u32 b_idx;
    mad.lo.u32 b_idx, col, K_reg, k;          // col*K + k
    .reg .u64 b_off;
    cvt.u64.u32 b_off, b_idx;
    shl.b64 b_off, b_off, 1;
    .reg .u64 b_addr;
    add.u64 b_addr, b_ptr, b_off;
    .reg .f16 b_val;
    ld.global.f16 b_val, [b_addr];

    // Convert to fp32
    .reg .f32 a_f, b_f;
    cvt.rn.f32.f16 a_f, a_val;
    cvt.rn.f32.f16 b_f, b_val;

    // Accumulate
    .reg .f32 tmp;
    fma.rn.f32 tmp, a_f, b_f, sum;
    mov.f32 sum, tmp;

    // Increment k
    add.u32 k, k, 1;
    bra K_LOOP;

K_DONE:
    // --------------------------------------------------------------------
    // Write result (convert back to half)
    // --------------------------------------------------------------------
    .reg .f16 c_val;
    cvt.rn.f16.f32 c_val, sum;

    .reg .u32 c_idx;
    mad.lo.u32 c_idx, row, N_reg, col;        // row*N + col
    .reg .u64 c_off;
    cvt.u64.u32 c_off, c_idx;
    shl.b64 c_off, c_off, 1;
    .reg .u64 c_addr;
    add.u64 c_addr, c_ptr, c_off;
    st.global.f16 [c_addr], c_val;

DONE:
    ret;
}
'''

# ----------------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel
# ----------------------------------------------------------------------
import torch

# The harness is assumed to provide these functions:
#   ptx_load(source: str) -> module_handle
#   ptx_launch(module, kernel_name: str, grid: tuple, block: tuple, args: list)

class ModelNew(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self._module = ptx_load(PTX_SOURCE)
        self._kernel_name = "matmul_kernel"
        # 32 x 8 threads per block = 256 threads; suitable for A100
        self._block = (32, 8, 1)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        A: (M, K) fp16 CUDA tensor
        B: (N, K) fp16 CUDA tensor   (interpreted as transposed inside kernel)
        Returns:
            C: (M, N) fp16 CUDA tensor
        """
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float16 and B.dtype == torch.float16, "Inputs must be fp16"

        M, K = A.shape
        N, Kb = B.shape
        assert K == Kb, "Inner dimensions must match"

        C = torch.empty((M, N), dtype=torch.float16, device='cuda')

        grid_x = (N + self._block[0] - 1) // self._block[0]
        grid_y = (M + self._block[1] - 1) // self._block[1]
        grid = (grid_x, grid_y, 1)

        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            int(M),
            int(N),
            int(K)
        ]

        ptx_launch(self._module, self._kernel_name, grid, self._block, args)

        return C

