    mov.u32 %tid_y,  %tid.y;
    mov.u32 %bid_x,  %ctaid.x;
    mov.u32 %bid_y,  %ctaid.y;
    mov.u32 %ntid_x, %ntid.x;
    mov.u32 %ntid_y, %ntid.y;

