    shl.b64       %tmp64, %tmp64, 1;    // *2 bytes (fp16)
    add.u64       %addr, %A_ptr, %tmp64;
    ld.global.u16 %a_u16, [%addr];
    cvt.f16.u16.rn %a_f16, %a_u16;
    cvt.f32.f16.rn %a_f32, %a_f16;

    // ---- load B[col, k] (B is N×K, we need element (col,k)) ----
    mul.wide.u32 %tmp64, %col, %K;       // col * K
