    cvt.u64.u32 %tmp64, %c;
    shl.b64 %tmp64, %tmp64, 1;
    add.u64 %tmp64, %tmp64, %beta_ptr;
    ld.global.f16 %beta_h, [%tmp64];
    cvt.f32.f16 %beta_f, %beta_h;

    // -------------------------------------------------
    // compute channel offset (bytes) = c * N * sizeof(fp16)
    // -------------------------------------------------
    cvt.u64.u32 %tmp64, %c;
    cvt.u64.u32 %addr, %N;
    mul.lo.u64 %chan_off, %tmp64, %addr;
    shl.b64 %chan_off, %chan_off, 1;            // *2 for fp16

    // -------------------------------------------------
    // initialize shared sums
    // -------------------------------------------------
    setp.eq.u32 %p0, %tid_x, 0;
    @%p0 mov.f32 s_sum, 0f00000000;
    @%p0 mov.f32 s_sq_sum, 0f00000000;
    bar.sync 0;

    // -------------------------------------------------
    // first pass: compute sum and sum of squares
    // -------------------------------------------------
    mov.u32 %i, %tid_x;
first_sum_loop:
    setp.ge.u32 %p1, %i, %N;
    @%p1 bra first_sum_done;

    // compute element address: x_ptr + chan_off + i*2
    cvt.u64.u32 %tmp64, %i;
    shl.b64 %elem_off, %tmp64, 1;                // *2 bytes
    add.u64 %addr, %x_ptr, %chan_off;
    add.u64 %addr, %addr, %elem_off;

    ld.global.f16 %val_h, [%addr];
    cvt.f32.f16 %val_f, %val_h;

    // atomic adds to shared sums
    atom.add.shared.f32 [s_sum], %val_f;
    mul.f32 %tmp_f, %val_f, %val_f;
    atom.add.shared.f32 [s_sq_sum], %tmp_f;

    // stride loop
    add.u32 %i, %i, %ntid_x;
    bra.uni first_sum_loop;

first_sum_done:
    bar.sync 0;

    // -------------------------------------------------
    // compute mean and variance (thread 0)
    // -------------------------------------------------
    setp.eq.u32 %p2, %tid_x, 0;
    @%p2 {
        // mean = sum / N
        cvt.f32.u32 %tmp_f, %N;
        div.f32 %mean_f, s_sum, %tmp_f;

        // var = (sq_sum / N) - mean*mean
        div.f32 %var_f, s_sq_sum, %tmp_f;
        mul.f32 %tmp_f, %mean_f, %mean_f;
        sub.f32 %var_f, %var_f, %tmp_f;

        // add epsilon and compute inv_std
        add.f32 %var_f, %var_f, %eps;
        rsqrt.approx.f32 %inv_std_f, %var_f;

        // store to shared
        st.shared.f32 [s_mean], %mean_f;
        st.shared.f32 [s_inv_std], %inv_std_f;
    }
    bar.sync 0;

    // load mean and inv_std for all threads
    ld.shared.f32 %mean_f, [s_mean];
    ld.shared.f32 %inv_std_f, [s_inv_std];

    // -------------------------------------------------
    // second pass: write normalized output
    // -------------------------------------------------
    mov.u32 %i, %tid_x;
write_loop:
    setp.ge.u32 %p3, %i, %N;
    @%p3 bra write_done;

    // address of input element
    cvt.u64.u32 %tmp64, %i;
    shl.b64 %elem_off, %tmp64, 1;
    add.u64 %addr, %x_ptr, %chan_off;
    add.u64 %addr, %addr, %elem_off;

    ld.global.f16 %val_h, [%addr];
    cvt.f32.f16 %val_f, %val_h;

    // normalize: (x - mean) * inv_std * gamma + beta
    sub.f32 %val_f, %val_f, %mean_f;
    mul.f32 %val_f, %val_f, %inv_std_f;
    mul.f32 %val_f, %val_f, %gamma_f;
    add.f32 %val_f, %val_f, %beta_f;

    // convert back to fp16
    cvt.f16.f32 %val_h, %val_f;

    // address of output element (same offset from out_ptr)
    add.u64 %addr, %out_ptr, %chan_off;
    add.u64 %addr, %addr, %elem_off;
    st.global.f16 [%addr], %val_h;

    // stride
    add.u32 %i, %i, %ntid_x;
    bra.uni write_loop;

write_done:
    ret;
}
