// -------------------------------------------------------------------------
// Kernel 1: accumulate per‑channel sum and sum‑of‑squares (FP32)
// -------------------------------------------------------------------------
.visible .entry bn_accumulate(
    .param .u64 src_ptr,
    .param .u64 sum_ptr,
    .param .u64 sumsq_ptr,
    .param .u32 num_features,
    .param .u32 channel_stride,
    .param .u64 total_elements
)
{
    // registers
    .reg .b64  %src, %sum_base, %sumsq_base, %total_elems, %stride, %gid, %addr, %cstride64, %tmp64, %idx64;
    .reg .u32  %tid_x, %blockDim_x, %blockIdx_x, %gridDim_x;
    .reg .u32  %num_feat, %cstride, %channel, %idx32;
    .reg .f16  %val_f16;
    .reg .f32  %val_f32, %sq_f32, %old;
    .reg .pred %p_done;

    // load parameters
    ld.param.u64 %src,          [src_ptr];
    ld.param.u64 %sum_base,     [sum_ptr];
    ld.param.u64 %sumsq_base,   [sumsq_ptr];
    ld.param.u32 %num_feat,     [num_features];
    ld.param.u32 %cstride,      [channel_stride];
    ld.param.u64 %total_elems,  [total_elements];

    // thread indices
    mov.u32 %tid_x,      %tid.x;
    mov.u32 %blockDim_x, %ntid.x;
    mov.u32 %blockIdx_x, %ctaid.x;
    mov.u32 %gridDim_x,  %nctaid.x;

    // linear thread id (64‑bit)
    mad.lo.u32 %tid_x, %blockIdx_x, %blockDim_x, %tid_x;
    cvt.u64.u32 %gid, %tid_x;

    // total stride (gridDim * blockDim)
    mul.wide.u32 %stride, %gridDim_x, %blockDim_x;

    // channel stride as 64‑bit
    cvt.u64.u32 %cstride64, %cstride;

LOOP_ACC:
    setp.ge.u64 %p_done, %gid, %total_elems;
    @%p_done bra DONE_ACC;

    // idx = gid / channel_stride
    div.u64 %idx64, %gid, %cstride64;
    cvt.u32.u64 %idx32, %idx64;

    // channel = idx % num_features
    rem.u32 %channel, %idx32, %num_feat;

    // load input half
    shl.b64 %addr, %gid, 1;               // *2 bytes per fp16
    add.u64 %addr, %src, %addr;
    ld.global.f16 %val_f16, [%addr];

    // convert to fp32
    cvt.f32.f16 %val_f32, %val_f16;

    // square
    mul.f32 %sq_f32, %val_f32, %val_f32;

    // atomic add to sum
    mul.wide.u32 %tmp64, %channel, 4;      // offset = channel * 4 (size of fp32)
    add.u64 %tmp64, %sum_base, %tmp64;
    atom.global.add.f32 %old, [%tmp64], %val_f32;

    // atomic add to sum‑of‑squares
    mul.wide.u32 %tmp64, %channel, 4;
    add.u64 %tmp64, %sumsq_base, %tmp64;
    atom.global.add.f32 %old, [%tmp64], %sq_f32;

    // advance to next element handled by this thread
    add.u64 %gid, %gid, %stride;
    bra LOOP_ACC;

DONE_ACC:
    ret;
}

// -------------------------------------------------------------------------
// Kernel 2: normalize using per‑channel statistics
// -------------------------------------------------------------------------
.visible .entry bn_normalize(
    .param .u64 src_ptr,
    .param .u64 dst_ptr,
    .param .u64 sum_ptr,
    .param .u64 sumsq_ptr,
    .param .u32 num_features,
    .param .u32 channel_stride,
    .param .u64 total_elements,
    .param .f32 eps
)
{
    // registers
    .reg .b64  %src, %dst, %sum_base, %sumsq_base, %total_elems, %stride, %gid, %addr, %cstride64, %tmp64, %idx64, %cnt_u64;
    .reg .u32  %tid_x, %blockDim_x, %blockIdx_x, %gridDim_x;
    .reg .u32  %num_feat, %cstride, %channel, %idx32;
    .reg .f16  %val_f16, %out_f16;
    .reg .f32  %val_f32, %mean, %var, %inv_std, %cnt_f32;
    .reg .f32  %sum_c, %sumsq_c, %mean_sq, %norm_f32, %eps_f32;
    .reg .pred %p_done;
    .reg .f32  %old;   // dummy for atomics (not used)

    // load parameters
    ld.param.u64 %src,          [src_ptr];
    ld.param.u64 %dst,          [dst_ptr];
    ld.param.u64 %sum_base,     [sum_ptr];
    ld.param.u64 %sumsq_base,   [sumsq_ptr];
    ld.param.u32 %num_feat,     [num_features];
    ld.param.u32 %cstride,      [channel_stride];
    ld.param.u64 %total_elems,  [total_elements];
    ld.param.f32 %eps_f32,      [eps];

    // thread indices
    mov.u32 %tid_x,      %tid.x;
    mov.u32 %blockDim_x, %ntid.x;
    mov.u32 %blockIdx_x, %ctaid.x;
    mov.u32 %gridDim_x,  %nctaid.x;

    // linear thread id (64‑bit)
    mad.lo.u32 %tid_x, %blockIdx_x, %blockDim_x, %tid_x;
    cvt.u64.u32 %gid, %tid_x;

    // total stride
    mul.wide.u32 %stride, %gridDim_x, %blockDim_x;

    // channel stride as 64‑bit
    cvt.u64.u32 %cstride64, %cstride;

    // elements per channel = total_elements / num_features (as float)
    cvt.u64.u32 %cnt_u64, %num_feat;
    div.u64 %cnt_u64, %total_elems, %cnt_u64;
    cvt.rn.f32.u64 %cnt_f32, %cnt_u64;

LOOP_NORM:
    setp.ge.u64 %p_done, %gid, %total_elems;
    @%p_done bra DONE_NORM;

    // idx = gid / channel_stride
    div.u64 %idx64, %gid, %cstride64;
    cvt.u32.u64 %idx32, %idx64;

    // channel = idx % num_features
    rem.u32 %channel, %idx32, %num_feat;

    // load per‑channel sum
    mul.wide.u32 %tmp64, %channel, 4;
    add.u64 %tmp64, %sum_base, %tmp64;
    ld.global.f32 %sum_c, [%tmp64];

    // load per‑channel sum‑of‑squares
    mul.wide.u32 %tmp64, %channel, 4;
    add.u64 %tmp64, %sumsq_base, %tmp64;
    ld.global.f32 %sumsq_c, [%tmp64];

    // mean = sum_c / cnt
    div.approx.f32 %mean, %sum_c, %cnt_f32;

    // var = (sumsq_c / cnt) - mean*mean + eps
    div.approx.f32 %var, %sumsq_c, %cnt_f32;
    mul.f32 %mean_sq, %mean, %mean;
    sub.f32 %var, %var, %mean_sq;
    add.f32 %var, %var, %eps_f32;

    // inv_std = rsqrt(var)
    rsqrt.approx.f32 %inv_std, %var;

    // load input half
    shl.b64 %addr, %gid, 1;
    add.u64 %addr, %src, %addr;
    ld.global.f16 %val_f16, [%addr];
    cvt.f32.f16 %val_f32, %val_f16;

    // normalize
    sub.f32 %norm_f32, %val_f32, %mean;
    mul.f32 %norm_f32, %norm_f32, %inv_std;

    // store output half
    cvt.rn.f16.f32 %out_f16, %norm_f32;
    shl.b64 %addr, %gid, 1;
    add.u64 %addr, %dst, %addr;
    st.global.f16 [%addr], %out_f16;

    // advance to next element
    add.u64 %gid, %gid, %stride;
    bra LOOP_NORM;

DONE_NORM:
    ret;
}
