class ModelNew:
    def __init__(self, num_features: int):
        self.module = ptx_load(PTX_SOURCE)
        self.num_features = num_features

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure fp16 on CUDA
        x = x.to(dtype=torch.float16, device='cuda')
        B, C, H, W = x.shape
        total_elements = x.numel()
        channel_stride = H * W
        eps = 1e-5

        out = torch.empty_like(x)

        # per‑channel buffers (FP32)
        sum_buf   = torch.zeros(C, dtype=torch.float32, device='cuda')
        sumsq_buf = torch.zeros(C, dtype=torch.float32, device='cuda')

        # launch accumulation kernel
        block = 256
        grid = (total_elements + block - 1) // block
        args_acc = [
            x.data_ptr(),
            sum_buf.data_ptr(),
            sumsq_buf.data_ptr(),
            C,
            channel_stride,
            total_elements
        ]
        ptx_launch(self.module, "bn_accumulate",
                   (grid, 1, 1), (block, 1, 1, 1), args_acc)

        # launch normalization kernel
        args_norm = [
            x.data_ptr(),
            out.data_ptr(),
            sum_buf.data_ptr(),
            sumsq_buf.data_ptr(),
            C,
            channel_stride,
            total_elements,
            eps
        ]
        ptx_launch(self.module, "bn_normalize",
                   (grid, 1, 1), (block, 1, 1, 1), args_norm)

        return out

