    .reg .f32 %N_f, %mean, %E_x2, %var, %var_eps, %std, %tmp;
    cvt.f32.u32 %N_f, %N;
    div.approx.f32 %mean, %sum_f, %N_f;
    div.approx.f32 %E_x2, %sumsq_f, %N_f;
    mul.f32 %tmp, %mean, %mean;
    sub.f32 %var, %E_x2, %tmp;
