    div.approx.f32 %val_f, %val_f, %std;

    // store back as fp16
    cvt.f16.f32 %val_h, %val_f;
    st.global.f16 [%addr_out], %val_h;

    // next index
    add.u32 %idx, %idx, %ntid.x;
    bra LOOP_NORM;
END_NORM:
    ret;
