        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16
        N, C, H, W = x.shape
        out = torch.empty_like(x)

        grid = (N * self.num_groups,)
        block = (256,)

        eps = 1e-5
        args = [
            x.data_ptr(),
            out.data_ptr(),
            N,
            C,
            self.num_groups,
            H,
            W,
            eps
        ]

        ptx_launch(self.module, "gn_kernel", grid, block, args)
