PTX_SOURCE = r'''
.version 7.4
.target sm_80
.address_size 64

.visible .entry rmsnorm_kernel (
    .param .u64   inp_ptr,
    .param .u64   out_ptr,
    .param .u32   batch,
    .param .u32   num_feat,
    .param .u32   dim1,
    .param .u32   dim2,
    .param .f32   eps
)
{
    // --------------------------------------------------------------
    // Load kernel arguments
    // --------------------------------------------------------------
    .reg .u64   %in_ptr, %out_ptr;
    .reg .u32   %batch, %num_feat, %dim1, %dim2;
    .reg .f32   %eps_f32;

    ld.param.u64    %in_ptr,    [inp_ptr];
    ld.param.u64    %out_ptr,   [out_ptr];
    ld.param.u32    %batch,     [batch];
    ld.param.u32    %num_feat,  [num_feat];
    ld.param.u32    %dim1,      [dim1];
    ld.param.u32    %dim2,      [dim2];
    ld.param.f32    %eps_f32,   [eps];

    // --------------------------------------------------------------
    // Compute linear thread id for (batch, dim1, dim2)
    // --------------------------------------------------------------
    .reg .u32   %tid_x, %ctaid_x, %ntid_x, %global_idx, %tmp;
    mov.u32 %tid_x,   %tid.x;
    mov.u32 %ctaid_x, %ctaid.x;
    mov.u32 %ntid_x,  %ntid.x;
    mul.lo.u32 %tmp, %ctaid_x, %ntid_x;
    add.u32 %global_idx, %tmp, %tid_x;

    // total = batch * dim1 * dim2
    .reg .u32   %total;
    mul.lo.u32 %tmp, %batch, %dim1;
    mul.lo.u32 %total, %tmp, %dim2;

    // if (global_idx >= total) return;
    .reg .pred %p_exit;
    setp.ge.u32 %p_exit, %global_idx, %total;
    @%p_exit ret;

    // --------------------------------------------------------------
    // Decompose global_idx into (b, i, j)
    // --------------------------------------------------------------
    .reg .u32 %stride_batch, %b, %rem, %i, %j;
    mul.lo.u32 %stride_batch, %dim1, %dim2;          // dim1*dim2

    // b = global_idx / stride_batch
    div.u32 %b, %global_idx, %stride_batch;
    // rem = global_idx - b*stride_batch
    mul.lo.u32 %tmp, %b, %stride_batch;
    sub.u32 %rem, %global_idx, %tmp;

    // i = rem / dim2
    div.u32 %i, %rem, %dim2;
    // j = rem - i*dim2
    mul.lo.u32 %tmp, %i, %dim2;
    sub.u32 %j, %rem, %tmp;

    // --------------------------------------------------------------
    // Compute base byte offset for this (b,i,j) across the feature dim
    // offset = (((b*dim1 + i)*dim2 + j) * num_feat) * 2
    // --------------------------------------------------------------
    .reg .u64 %base_off, %tmp64, %addr64;
    mul.lo.u32 %tmp, %b, %dim1;          // b*dim1
    add.u32 %tmp, %tmp, %i;              // + i
    mul.lo.u32 %tmp, %tmp, %dim2;        // * dim2
    add.u32 %tmp, %tmp, %j;              // + j
    mul.lo.u32 %tmp, %tmp, %num_feat;    // * num_feat
    cvt.u64.u32 %tmp64, %tmp;
    shl.b64 %base_off, %tmp64, 1;        // *2 (sizeof(half))

    // --------------------------------------------------------------
    // First pass: compute sum of squares over feature dimension
    // --------------------------------------------------------------
    .reg .f32 %sum_sq, %val_f32, %mean, %rms, %num_feat_f32;
    .reg .f16 %val_f16;
    .reg .u32 %c;
    .reg .pred %p_done;

    mov.f32 %sum_sq, 0f00000000;          // 0.0f
    xor.b32 %c, %c, %c;                  // c = 0

LOOP_SUM:
    setp.ge.u32 %p_done, %c, %num_feat;
    @%p_done bra END_SUM;

    // addr = in_ptr + base_off + c*2
    mul.wide.u32 %tmp64, %c, 2;          // offset for this feature (bytes)
    add.u64 %addr64, %in_ptr, %base_off;
    add.u64 %addr64, %addr64, %tmp64;
    ld.global.f16 %val_f16, [%addr64];

    // convert to fp32 and square
    cvt.rn.f32.f16 %val_f32, %val_f16;
    mul.f32 %val_f32, %val_f32, %val_f32;
    add.f32 %sum_sq, %sum_sq, %val_f32;

    add.u32 %c, %c, 1;
    bra LOOP_SUM;
END_SUM:

    // mean = sum_sq / num_feat
    cvt.f32.u32 %num_feat_f32, %num_feat;
    div.rn.f32 %mean, %sum_sq, %num_feat_f32;
    add.f32 %mean, %mean, %eps_f32;
    sqrt.approx.f32 %rms, %mean;               // rms = sqrt(mean)

    // --------------------------------------------------------------
    // Second pass: write normalized values
    // --------------------------------------------------------------
    xor.b32 %c, %c, %c;                  // reset c = 0

LOOP_WRITE:
    setp.ge.u32 %p_done, %c, %num_feat;
    @%p_done bra END_WRITE;

    // addr = in_ptr + base_off + c*2
    mul.wide.u32 %tmp64, %c, 2;
    add.u64 %addr64, %in_ptr, %base_off;
    add.u64 %addr64, %addr64, %tmp64;
    ld.global.f16 %val_f16, [%addr64];
    cvt.rn.f32.f16 %val_f32, %val_f16;

    // normalize: val_f32 = val_f32 / rms
    div.rn.f32 %val_f32, %val_f32, %rms;

    // convert back to half
    cvt.rn.f16.f32 %val_f16, %val_f32;

    // store to out_ptr
    add.u64 %addr64, %out_ptr, %base_off;
    add.u64 %addr64, %addr64, %tmp64;
    st.global.f16 [%addr64], %val_f16;

    add.u32 %c, %c, 1;
    bra LOOP_WRITE;
END_WRITE:
    ret;
}
'''

import torch
from ptx_harness import ptx_load, ptx_launch

class ModelNew:
    def __init__(self, num_features: int, eps: float = 1e-5):
        self.num_features = int(num_features)
        self.eps = float(eps)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            raise TypeError("Input must be torch.float16")
        out = torch.empty_like(x)

        batch, _, dim1, dim2 = x.shape
        threads_per_block = 256
        total_locs = batch * dim1 * dim2
        grid_x = (total_locs + threads_per_block - 1) // threads_per_block

        args = [
            x.data_ptr(),
            out.data_ptr(),
            batch,
            self.num_features,
            dim1,
            dim2,
            self.eps,
        ]

        ptx_launch(
            self.module,
            "rmsnorm_kernel",
            (grid_x, 1, 1),               # grid dimensions
            (threads_per_block, 1, 1),    # block dimensions
            args
        )
        return out

