.version 7.5
.target sm_80
.address_size 64

.visible .entry rmsnorm_kernel(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u32 batch,
    .param .u32 features,
    .param .u32 dim1,
    .param .u32 dim2,
    .param .f32 eps
)
{
    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .b64 x_ptr_reg, y_ptr_reg;
    .reg .u32 batch_reg, feat_reg, dim1_reg, dim2_reg;
    .reg .f32 eps_reg;

    ld.param.u64   x_ptr_reg, [x_ptr];
    ld.param.u64   y_ptr_reg, [y_ptr];
    ld.param.u32   batch_reg, [batch];
    ld.param.u32   feat_reg,  [features];
    ld.param.u32   dim1_reg,  [dim1];
    ld.param.u32   dim2_reg,  [dim2];
    ld.param.f32   eps_reg,   [eps];

    // -------------------------------------------------
    // Thread / block identifiers
    // -------------------------------------------------
    .reg .u32 tid, block_id;
    mov.u32        tid, %tid.x;      // feature index inside block
    mov.u32        block_id, %ctaid.x; // linear block id = b*dim1*dim2 + d1*dim2 + d2

    // -------------------------------------------------
    // Decompose block_id into (batch, d1, d2)
    // -------------------------------------------------
    .reg .u32 dim1dim2, b_idx, rem, d1_idx, d2_idx, tmp;
    mul.lo.u32     dim1dim2, dim1_reg, dim2_reg;          // dim1 * dim2
    div.u32        b_idx,    block_id,    dim1dim2;      // batch index
    mul.lo.u32     tmp,      b_idx,       dim1dim2;
    sub.u32        rem,      block_id,    tmp;           // remainder = d1*dim2 + d2
    div.u32        d1_idx,   rem,         dim2_reg;      // d1 index
    mul.lo.u32     tmp,      d1_idx,      dim2_reg;
    sub.u32        d2_idx,   rem,         tmp;           // d2 index

    // -------------------------------------------------
    // Compute linear element index:
    // idx = ((b*features + tid) * dim1 + d1) * dim2 + d2
    // -------------------------------------------------
    .reg .u32 idx, base;
    mul.lo.u32     base, b_idx, feat_reg;   // b * features
    add.u32        base, base, tid;         // + feature
    mul.lo.u32     idx,  base, dim1_reg;    // * dim1
    add.u32        idx,  idx,  d1_idx;      // + d1
    mul.lo.u32     idx,  idx,  dim2_reg;    // * dim2
    add.u32        idx,  idx,  d2_idx;      // + d2

    // -------------------------------------------------
    // Compute byte address (sizeof(half) = 2)
    // -------------------------------------------------
    .reg .b64 byte_off, in_addr, out_addr;
    cvt.u64.u32    byte_off, idx;
    shl.b64        byte_off, byte_off, 1;    // *2 => bytes
    add.u64        in_addr,  x_ptr_reg, byte_off;
    add.u64        out_addr, y_ptr_reg, byte_off;

    // -------------------------------------------------
    // Load FP16 element, convert to FP32
    // -------------------------------------------------
    .reg .f16 x_h;
    .reg .f32 x_f;
    ld.global.f16  x_h, [in_addr];
    cvt.f32.f16    x_f, x_h;

    // -------------------------------------------------
    // Square (FP32) and store into shared memory
    // -------------------------------------------------
    .reg .f32 sq;
    mul.f32        sq, x_f, x_f;            // x_f * x_f

    .shared .align 4 .b32 sdata[1024];      // one float per feature (max 1024)

    .reg .u32 sh_off;
    shl.b32        sh_off, tid, 2;          // offset in bytes
    st.shared.b32 [sdata+sh_off], sq;      // store square

    // -------------------------------------------------
    // Block-wide reduction: thread 0 computes RMS
    // -------------------------------------------------
    bar.sync 0;

    .reg .pred p0;
    setp.eq.u32    p0, tid, 0;
    @p0 {
        .reg .u32 i;
        .reg .f32 sum;
        mov.u32       i,   0;
        mov.f32       sum, 0f0;
    sum_loop:
        .reg .b32 roff;
        shl.b32       roff, i, 2;            // i * 4
        .reg .f32 val;
        ld.shared.b32 val, [sdata+roff];
        add.f32       sum, sum, val;
        add.u32       i, i, 1;
        .reg .pred p1;
        setp.lt.u32   p1, i, feat_reg;
        @p1 bra       sum_loop;

