        .reg .f32 ffeat;
        cvt.f32.u32   ffeat, feat_reg;
        div.rn.f32    sum, sum, ffeat;

        // add epsilon and sqrt -> RMS
        add.f32       sum, sum, eps_reg;
        sqrt.rn.f32   sum, sum;              // RMS

        // store RMS at shared[0]
        st.shared.b32 [sdata], sum;
    }

    bar.sync 0;

    // Load RMS
    .reg .f32 rms;
    ld.shared.b32  rms, [sdata];

    // -------------------------------------------------
    // Normalize, convert back to FP16, store result
    // -------------------------------------------------
    div.rn.f32     x_f, x_f, rms;
    cvt.rn.f16.f32 x_h, x_f;
    st.global.f16  [out_addr], x_h;

    ret;
}
