    // Registers
    // -------------------------------------------------
    .reg .u64   %in_ptr, %out_ptr, %addr, %offset64, %tmp64;
    .reg .u32   %C, %batch, %H, %W, %HW, %b, %h, %w;
    .reg .u32   %tid, %ctaid, %i, %rem;
    .reg .f16   %x_f16, %y_f16;
    .reg .f32   %x_f32, %sq_f32, %acc, %mean_f32, %rms_f32, %eps_f32;
    .reg .pred %p, %p2;

