    // Compute (b, h, w) from linear blockIdx.x
    // -------------------------------------------------
    mul.lo.u32 %HW, %H, %W;                // HW = H * W

    // b = blockIdx / HW
    div.u32 %b, %ctaid, %HW;
    mul.lo.u32 %i, %b, %HW;
    sub.u32 %rem, %ctaid, %i;              // rem = blockIdx % HW

    // h = rem / W
    div.u32 %h, %rem, %W;
    mul.lo.u32 %i, %h, %W;
    sub.u32 %w, %rem, %i;                  // w = rem % W

    // -------------------------------------------------
    // Bounds check on feature dimension
    // -------------------------------------------------
    setp.ge.u32 %p, %tid, %C;
    @%p bra END_KERNEL;

