    add.u32 %i, %i, %tid;           // b*C + tid
    mul.lo.u32 %i, %i, %H;          // * H
    add.u32 %i, %i, %h;             // + h
    mul.lo.u32 %i, %i, %W;          // * W
    add.u32 %i, %i, %w;             // + w

