.version 7.0
.target sm_80
.address_size 64

.visible .entry batched_gemm_fp16 (
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 batch,
    .param .u32 m,
    .param .u32 k,
    .param .u32 n
)
{
    // -----------------------------------------------------------------
    // Parameter loading
    // -----------------------------------------------------------------
    .reg .u64 a_ptr, b_ptr, c_ptr;
    .reg .u32 batch_u32, m_u32, k_u32, n_u32;
    ld.param.u64 a_ptr, [A_ptr];
    ld.param.u64 b_ptr, [B_ptr];
    ld.param.u64 c_ptr, [C_ptr];
    ld.param.u32 batch_u32, [batch];
    ld.param.u32 m_u32, [m];
    ld.param.u32 k_u32, [k];
    ld.param.u32 n_u32, [n];

    // -----------------------------------------------------------------
    // Thread identifiers
    // -----------------------------------------------------------------
    .reg .u32 tid, cta, ntid;
    mov.u32 tid, %tid.x;
    mov.u32 cta, %ctaid.x;
    mov.u32 ntid, %ntid.x;
    .reg .u64 gid;
    mad.wide.u32 gid, cta, ntid, tid;        // gid = blockIdx.x * blockDim.x + threadIdx.x

    // -----------------------------------------------------------------
    // Compute total number of output elements = batch * m * n
    // -----------------------------------------------------------------
    .reg .u64 batch_u64, m_u64, n_u64, total, tmp;
    cvt.u64.u32 batch_u64, batch_u32;
    cvt.u64.u32 m_u64, m_u32;
    cvt.u64.u32 n_u64, n_u32;
    mul.lo.u64 tmp, m_u64, n_u64;            // m * n
    mul.lo.u64 total, batch_u64, tmp;        // batch * m * n

    // Bounds check
    .reg .pred p_out;
    setp.ge.u64 p_out, gid, total;
    @p_out ret;

    // -----------------------------------------------------------------
    // Decompose gid into (batch_idx, row_i, col_j)
    // -----------------------------------------------------------------
    .reg .u64 mn, b_idx, rem, i_idx, j_idx;
    mul.lo.u64 mn, m_u64, n_u64;             // m * n
    div.u64 b_idx, gid, mn;                  // batch index
    mul.lo.u64 tmp, b_idx, mn;
    sub.u64 rem, gid, tmp;                   // remainder = gid % (m*n)

    div.u64 i_idx, rem, n_u64;               // row index
    mul.lo.u64 tmp, i_idx, n_u64;
    sub.u64 j_idx, rem, tmp;                 // col index

    // -----------------------------------------------------------------
    // Compute base pointers for this batch element
    // -----------------------------------------------------------------
    .reg .u64 k_u64;
    cvt.u64.u32 k_u64, k_u32;

    // A row start: ((b * m) + i) * k
    .reg .u64 a_row_off, a_ptr_row;
    mul.lo.u64 tmp, b_idx, m_u64;
    add.u64 tmp, tmp, i_idx;                 // (b*m) + i
    mul.lo.u64 a_row_off, tmp, k_u64;        // *k
    mul.lo.u64 a_row_off, a_row_off, 2;      // *sizeof(half)
    add.u64 a_ptr_row, a_ptr, a_row_off;     // address of first element of A row

    // B batch start: b * k * n
    .reg .u64 b_batch_off, b_ptr_batch;
    mul.lo.u64 tmp, b_idx, k_u64;
    mul.lo.u64 b_batch_off, tmp, n_u64;      // b*k*n
    mul.lo.u64 b_batch_off, b_batch_off, 2;  // *sizeof(half)
    add.u64 b_ptr_batch, b_ptr, b_batch_off; // start of B for this batch

    // C element address: ((b * m) + i) * n + j
    .reg .u64 c_off, c_ptr_elem;
    mul.lo.u64 tmp, b_idx, m_u64;
    add.u64 tmp, tmp, i_idx;                 // (b*m) + i
    mul.lo.u64 c_off, tmp, n_u64;            // *n
    add.u64 c_off, c_off, j_idx;             // +j
    mul.lo.u64 c_off, c_off, 2;              // *sizeof(half)
    add.u64 c_ptr_elem, c_ptr, c_off;        // final address of C element

    // -----------------------------------------------------------------
    // Accumulate dot product over k (using fp32 accumulator)
    // -----------------------------------------------------------------
    .reg .f32 sum;
    mov.f32 sum, 0f0;

    .reg .u32 kk;
    mov.u32 kk, 0;

    .reg .u64 a_elem_ptr, b_elem_off, b_elem_ptr;
    .reg .f16 a16, b16, c16;
    .reg .f32 a32, b32;
    .reg .pred p_done;

K_LOOP:
    setp.ge.u32 p_done, kk, k_u32;
    @p_done bra K_END;

    // Load A[b, i, kk]
    mul.lo.u64 a_elem_ptr, kk, 2;
    add.u64 a_elem_ptr, a_ptr_row, a_elem_ptr;
    ld.global.f16 a16, [a_elem_ptr];
    cvt.rn.f32.f16 a32, a16;

    // Load B[b, kk, j]
    mul.lo.u64 b_elem_off, kk, n_u64;        // kk * n
    add.u64 b_elem_off, b_elem_off, j_idx;   // kk*n + j
    mul.lo.u64 b_elem_ptr, b_elem_off, 2;    // *sizeof(half)
    add.u64 b_elem_ptr, b_ptr_batch, b_elem_ptr;
    ld.global.f16 b16, [b_elem_ptr];
    cvt.rn.f32.f16 b32, b16;

    // FMA
    fma.rn.f32 sum, a32, b32, sum;

    // kk++
    add.u32 kk, kk, 1;
    bra K_LOOP;

K_END:
    // Store result (fp32 -> fp16)
    cvt.rn.f16.f32 c16, sum;
    st.global.f16 [c_ptr_elem], c16;

    ret;
