    add.u32 %wt_off, %wt_off, %ic;
    mul.lo.u32 %wt_off, %wt_off, %KH;
    add.u32 %wt_off, %wt_off, %kh;
    mul.lo.u32 %wt_off, %wt_off, %KW;
    add.u32 %wt_off, %wt_off, %kw;
    cvt.u64.u32 %addr, %wt_off;
    shl.b64 %addr, %addr, 1;
    add.u64 %addr, %wt_ptr, %addr;
    ld.global.f16 %wt_val, [%addr];
    cvt.f32.f16 %wt_f32, %wt_val;

    // MAC accumulation (fp32)
    mad.rn.f32 %acc, %in_f32, %wt_f32, %acc;

SKIP_PIXEL:
    add.s32 %kw, %kw, 1;
    bra KW_LOOP;
KW_END:
    add.s32 %kh, %kh, 1;
    bra KH_LOOP;
KH_END:
    add.s32 %ic, %ic, 1;
    bra IC_LOOP;
IC_END:

    // ----------------------------------------------------------------
    // Add bias (fp16 -> fp32)
    // ----------------------------------------------------------------
    cvt.u64.u32 %addr, %c;
    shl.b64 %addr, %addr, 1;
    add.u64 %addr, %bias_ptr, %addr;
    ld.global.f16 %bias_val, [%addr];
    cvt.f32.f16 %bias_f32, %bias_val;
    add.f32 %acc, %acc, %bias_f32;

    // ----------------------------------------------------------------
    // Write output (convert back to fp16)
    // ----------------------------------------------------------------
    cvt.f16.f32 %out_val, %acc;

    // output offset = ((n*OC + c)*OH + h)*OW + w
    mul.lo.u32 %out_off, %n, %OC;
    add.u32 %out_off, %out_off, %c;
    mul.lo.u32 %out_off, %out_off, %OH;
    add.u32 %out_off, %out_off, %h;
    mul.lo.u32 %out_off, %out_off, %OW;
    add.u32 %out_off, %out_off, %w;
    cvt.u64.u32 %addr, %out_off;
    shl.b64 %addr, %addr, 1;
    add.u64 %addr, %out_ptr, %addr;
    st.global.f16 [%addr], %out_val;

    ret;
}
