# --------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel
# --------------------------------------------------------------
import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_h = 11
        self.kernel_w = 11
        self.stride = 4
        self.pad = 2

        # FP16 weights and bias matching nn.Conv2d
        self.weight = nn.Parameter(
            torch.randn(self.out_channels, self.in_channels,
                        self.kernel_h, self.kernel_w,
                        dtype=torch.float16, device='cuda')
        )
        self.bias = nn.Parameter(
            torch.randn(self.out_channels,
                        dtype=torch.float16, device='cuda')
        )

        # Load PTX module once
        self._ptx_module = ptx_load(PTX_SOURCE)

    def forward(self, x):
        B, _, H, W = x.shape
        out_h = (H + 2 * self.pad - self.kernel_h) // self.stride + 1
        out_w = (W + 2 * self.pad - self.kernel_w) // self.stride + 1

        out = torch.empty(B, self.out_channels, out_h, out_w,
                          dtype=torch.float16, device='cuda')

        total_threads = B * self.out_channels * out_h * out_w
        block_dim = 256
        grid_dim = (total_threads + block_dim - 1) // block_dim

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            out.data_ptr(),
            B,
            self.out_channels,
            out_h,
            out_w,
            self.in_channels,
            H,
            W,
            self.stride,
            self.pad,
            self.kernel_h,
            self.kernel_w
        ]

        ptx_launch(self._ptx_module,
                   "conv1_fp16",
                   (grid_dim,),
                   (block_dim,),
                   args)

        return out

# PTX implementation of the 2‑D convolution (fp16 I/O, fp32 accumulation) for NVIDIA A100 (sm_80)

PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry conv_fp16_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 out_c,
    .param .u32 out_h,
    .param .u32 out_w,
    .param .u32 in_c,
    .param .u32 in_h,
    .param .u32 in_w,
    .param .u32 k_h,
    .param .u32 k_w,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w
)
{
    // --------------------------------------------------------------
    // Registers
    .reg .u64 %inp_ptr, %wgt_ptr, %bias_ptr, %out_ptr;
    .reg .u32 %batch, %outC, %outH, %outW;
    .reg .u32 %inC, %inH, %inW;
    .reg .u32 %kH, %kW, %sH, %sW, %pH, %pW;

    .reg .u32 %tid_x, %ctaid_x, %ntid_x;
    .reg .u64 %tid64, %blockIdx64, %blockDim64, %gid, %total;
    .reg .pred %p_exit;

    .reg .u32 %gid32, %tmp32;
    .reg .u32 %b, %oc, %oh, %ow;
    .reg .u64 %out_off, %addr, %tmp64;
    .reg .f32 %acc, %inp_f, %wgt_f, %bias_f;
    .reg .f16 %inp_h, %wgt_h, %bias_h, %out_h;
    .reg .u32 %ic, %kh, %kw, %in_y, %in_x;

    // --------------------------------------------------------------
    // Load scalar parameters
    ld.param.u64 %inp_ptr,    [input_ptr];
    ld.param.u64 %wgt_ptr,    [weight_ptr];
    ld.param.u64 %bias_ptr,   [bias_ptr];
    ld.param.u64 %out_ptr,    [output_ptr];
    ld.param.u32 %batch,      [batch];
    ld.param.u32 %outC,       [out_c];
    ld.param.u32 %outH,       [out_h];
    ld.param.u32 %outW,       [out_w];
    ld.param.u32 %inC,        [in_c];
    ld.param.u32 %inH,        [in_h];
    ld.param.u32 %inW,        [in_w];
    ld.param.u32 %kH,         [k_h];
    ld.param.u32 %kW,         [k_w];
    ld.param.u32 %sH,         [stride_h];
    ld.param.u32 %sW,         [stride_w];
    ld.param.u32 %pH,         [pad_h];
    ld.param.u32 %pW,         [pad_w];

    // --------------------------------------------------------------
    // Load special regs into normal regs (cannot be dest of mul.wide)
    mov.u32 %tid_x,    %tid.x;
    mov.u32 %ctaid_x,  %ctaid.x;
    mov.u32 %ntid_x,   %ntid.x;

    // Compute global thread id (64‑bit)
    cvt.u64.u32 %tid64,    %tid_x;
    cvt.u64.u32 %blockIdx64,%ctaid_x;
    cvt.u64.u32 %blockDim64,%ntid_x;
    mul.lo.u64 %tmp64, %blockIdx64, %blockDim64;
    add.u64 %gid, %tmp64, %tid64;

    // Compute total number of output elements = batch * outC * outH * outW
    mul.wide.u32 %tmp64, %batch, %outC;      // batch*outC
    mul.wide.u32 %total, %tmp64, %outH;      // *outH
    mul.wide.u32 %tmp64, %total, %outW;      // *outW
    mov.u64 %total, %tmp64;

    // if gid >= total -> exit
    setp.ge.u64 %p_exit, %gid, %total;
    @%p_exit ret;

    // --------------------------------------------------------------
    // Convert gid to 32‑bit (fits) for division/remainder
    cvt.u32.u64 %gid32, %gid;

    // Decompose gid -> (b, oc, oh, ow)
    rem.u32 %ow, %gid32, %outW;                     // ow = gid % outW
    div.u32 %tmp32, %gid32, %outW;                  // tmp = gid / outW
    rem.u32 %oh, %tmp32, %outH;                     // oh = tmp % outH
    div.u32 %tmp32, %tmp32, %outH;                  // tmp = tmp / outH
    rem.u32 %oc, %tmp32, %outC;                     // oc = tmp % outC
    div.u32 %b, %tmp32, %outC;                      // b = tmp / outC

    // --------------------------------------------------------------
    // Compute linear output offset (in elements) = ((b*outC + oc)*outH + oh)*outW + ow
    mul.wide.u32 %out_off, %b, %outC;               // b*outC
    cvt.u64.u32 %tmp64, %oc;
    add.u64 %out_off, %out_off, %tmp64;             // + oc
    mul.wide.u32 %out_off, %out_off, %outH;         // * outH
    cvt.u64.u32 %tmp64, %oh;
    add.u64 %out_off, %out_off, %tmp64;             // + oh
    mul.wide.u32 %out_off, %out_off, %outW;         // * outW
    cvt.u64.u32 %tmp64, %ow;
    add.u64 %out_off, %out_off, %tmp64;             // + ow
    // Convert element offset to byte offset (fp16 = 2 bytes) by shifting left 1
    shl.b64 %out_off, %out_off, 1;

    // --------------------------------------------------------------
    // Accumulator (fp32)
    mov.f32 %acc, 0f0;

    // --------------------------------------------------------------
    // Convolution loops
    mov.u32 %ic, 0;
IC_LOOP:
    setp.ge.u32 %p_exit, %ic, %inC;
    @%p_exit bra IC_DONE;

    mov.u32 %kh, 0;
KH_LOOP:
    setp.ge.u32 %p_exit, %kh, %kH;
    @%p_exit bra KH_DONE;

    // in_y = oh*stride_h + kh - pad_h
    mad.lo.u32 %in_y, %oh, %sH, %kh;   // oh*stride_h + kh
    sub.u32 %in_y, %in_y, %pH;

    // bounds check Y
    setp.ge.u32 %p_exit, %in_y, %inH;
    @%p_exit bra SKIP_KW_LOOP;

    mov.u32 %kw, 0;
KW_LOOP:
    setp.ge.u32 %p_exit, %kw, %kW;
    @%p_exit bra KW_DONE;

    // in_x = ow*stride_w + kw - pad_w
    mad.lo.u32 %in_x, %ow, %sW, %kw;   // ow*stride_w + kw
    sub.u32 %in_x, %in_x, %pW;

    // bounds check X
    setp.ge.u32 %p_exit, %in_x, %inW;
    @%p_exit bra SKIP_ACC;

    // --------------------------------------------------------------
    // Load input element: ((b*inC + ic)*inH + in_y)*inW + in_x
    mul.wide.u32 %addr, %b, %inC;          // b*inC
    cvt.u64.u32 %tmp64, %ic;
    add.u64 %addr, %addr, %tmp64;          // + ic
    mul.wide.u32 %addr, %addr, %inH;       // *inH
    cvt.u64.u32 %tmp64, %in_y;
    add.u64 %addr, %addr, %tmp64;          // + in_y
    mul.wide.u32 %addr, %addr, %inW;       // *inW
    cvt.u64.u32 %tmp64, %in_x;
    add.u64 %addr, %addr, %tmp64;          // + in_x
    add.u64 %addr, %inp_ptr, %addr;        // global address
    ld.global.f16 %inp_h, [%addr];
    cvt.f32.f16 %inp_f, %inp_h;

    // Load weight element: ((oc*inC + ic)*kH + kh)*kW + kw
    mul.wide.u32 %addr, %oc, %inC;         // oc*inC
    cvt.u64.u32 %tmp64, %ic;
    add.u64 %addr, %addr, %tmp64;          // + ic
    mul.wide.u32 %addr, %addr, %kH;        // *kH
    cvt.u64.u32 %tmp64, %kh;
    add.u64 %addr, %addr, %tmp64;          // + kh
    mul.wide.u32 %addr, %addr, %kW;        // *kW
    cvt.u64.u32 %tmp64, %kw;
    add.u64 %addr, %addr, %tmp64;          // + kw
    add.u64 %addr, %wgt_ptr, %addr;
    ld.global.f16 %wgt_h, [%addr];
    cvt.f32.f16 %wgt_f, %wgt_h;

    // Accumulate
    fma.rn.f32 %acc, %inp_f, %wgt_f, %acc;

SKIP_ACC:
    add.u32 %kw, %kw, 1;
    bra KW_LOOP;

KW_DONE:
SKIP_KW_LOOP:
    add.u32 %kh, %kh, 1;
    bra KH_LOOP;

KH_DONE:
    add.u32 %ic, %ic, 1;
    bra IC_LOOP;

IC_DONE:
    // --------------------------------------------------------------
    // Add bias (fp16)
    // bias offset = oc * 2 bytes
    cvt.u64.u32 %tmp64, %oc;
    shl.b64 %tmp64, %tmp64, 1;          // *2
    add.u64 %addr, %bias_ptr, %tmp64;
    ld.global.f16 %bias_h, [%addr];
    cvt.f32.f16 %bias_f, %bias_h;
    add.f32 %acc, %acc, %bias_f;

    // --------------------------------------------------------------
    // Store output (fp16)
    cvt.rn.f16.f32 %out_h, %acc;
    add.u64 %addr, %out_ptr, %out_off;
    st.global.f16 [%addr], %out_h;

    ret;
}
'''

import torch
import torch.nn as nn
from torch import Tensor

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Initialise a Conv2d to obtain weights/bias in the same layout as PyTorch
        conv = nn.Conv2d(in_channels=3,
                         out_channels=96,
                         kernel_size=11,
                         stride=4,
                         padding=2,
                         bias=True)
        # Move parameters to fp16 CUDA tensors
        self.weight = conv.weight.detach().clone().to(dtype=torch.float16, device='cuda')
        self.bias   = conv.bias.detach().clone().to(dtype=torch.float16, device='cuda')

        # Load PTX module (ptx_load is supplied by the harness)
        self.ptx_mod = ptx_load(PTX_SOURCE)

        # Convolution hyper‑parameters
        self.stride = 4
        self.padding = 2
        self.kernel_size = 11

    def forward(self, x: Tensor) -> Tensor:
        x = x.to(dtype=torch.float16, device='cuda')
        batch, in_c, in_h, in_w = x.shape
        out_c = self.weight.shape[0]

        # Compute output spatial dimensions (same formula as nn.Conv2d)
        out_h = (in_h + 2 * self.padding - self.kernel_size) // self.stride + 1
        out_w = (in_w + 2 * self.padding - self.kernel_size) // self.stride + 1

        out = torch.empty((batch, out_c, out_h, out_w),
                          dtype=torch.float16,
                          device='cuda')

        total = batch * out_c * out_h * out_w
        block = 256
        grid = (total + block - 1) // block

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            out.data_ptr(),
            batch,
            out_c,
            out_h,
            out_w,
            in_c,
            in_h,
            in_w,
            self.kernel_size,
            self.kernel_size,
            self.stride,
            self.stride,
            self.padding,
            self.padding
        ]

        # Launch the kernel (ptx_launch is supplied by the harness)
        ptx_launch(self.ptx_mod,
                   "conv_fp16_kernel",
                   (grid,),
                   (block,),
                   args)

        return out

