    .param .u64 bias_ptr,
    .param .u32 batch,
    .param .u32 inC,
    .param .u32 inH,
    .param .u32 inW,
    .param .u32 outC,
    .param .u32 outH,
    .param .u32 outW,
    .param .u32 stride,
    .param .u32 pad
)
{
    // -------------------------------------------------
    // registers
    // -------------------------------------------------
    .reg .pred   %p<12>;
    .reg .b32    %r<50>;
    .reg .b64    %rd<30>;

    .reg .f16    %fh0, %fh1, %fh2, %fh3;   // temporary fp16 values
    .reg .f32    %f0, %f1, %f2, %f3;       // accumulators / temporaries
    .reg .u16    %ru16;                    // temporary u16 for loads/stores

    // -------------------------------------------------
    // load kernel parameters
    // -------------------------------------------------
    ld.param.u64    %rd1, [out_ptr];
    ld.param.u64    %rd2, [in_ptr];
    ld.param.u64    %rd3, [weight_ptr];
    ld.param.u64    %rd4, [bias_ptr];
    ld.param.u32    %r1,  [batch];
    ld.param.u32    %r2,  [inC];
    ld.param.u32    %r3,  [inH];
    ld.param.u32    %r4,  [inW];
    ld.param.u32    %r5,  [outC];
    ld.param.u32    %r6,  [outH];
    ld.param.u32    %r7,  [outW];
    ld.param.u32    %r8,  [stride];
    ld.param.u32    %r9,  [pad];

