    // thread/block indices
    // -------------------------------------------------
    mov.u32 %r10, %ctaid.x;        // batch (b)
    mov.u32 %r11, %ctaid.y;        // output channel (oc)
    mov.u32 %r12, %tid.x;          // out x within block
    mov.u32 %r13, %tid.y;          // out y within block

