    // bounds check
    // -------------------------------------------------
    setp.ge.u32 %p0, %r10, %r1;
    @%p0 bra DONE;
    setp.ge.u32 %p0, %r11, %r5;
    @%p0 bra DONE;
    setp.ge.u32 %p0, %r12, %r7;
    @%p0 bra DONE;
    setp.ge.u32 %p0, %r13, %r6;
    @%p0 bra DONE;

