    // compute linear output index
    // out_idx = ((b*outC + oc)*outH + y)*outW + x
    // -------------------------------------------------
    mul.lo.u32 %r14, %r10, %r5;          // b*outC
    add.u32    %r14, %r14, %r11;         // + oc
    mul.lo.u32 %r14, %r14, %r6;          // * outH
    add.u32    %r14, %r14, %r13;         // + y
    mul.lo.u32 %r14, %r14, %r7;          // * outW
    add.u32    %r14, %r14, %r12;         // + x
    cvt.u64.u32 %rd5, %r14;
    mul.lo.u64 %rd5, %rd5, 2;            // fp16 size = 2 bytes
    add.u64    %rd6, %rd1, %rd5;         // address of output element

