    // load bias (fp16) -> fp32 accumulator
    // -------------------------------------------------
    mul.lo.u32 %r15, %r11, 2;            // bias offset in bytes
    cvt.u64.u32 %rd7, %r15;
    add.u64 %rd8, %rd4, %rd7;
    ld.global.u16 %ru16, [%rd8];
    cvt.f16.u16.rn %fh0, %ru16;
    cvt.f32.f16.rn %f0, %fh0;            // bias as fp32
    mov.f32 %f1, %f0;                    // accumulator starts with bias

