    // compute base input coordinates (top‑left of receptive field)
    // -------------------------------------------------
    // base_y = y*stride - pad
    mul.lo.u32 %r16, %r13, %r8;
    sub.u32    %r16, %r16, %r9;           // base_y
    // base_x = x*stride - pad
    mul.lo.u32 %r17, %r12, %r8;
    sub.u32    %r17, %r17, %r9;           // base_x

    // -------------------------------------------------
    // loops over input channels and kernel spatial dimensions
    // -------------------------------------------------
    mov.u32 %r18, 0;          // ic = 0

IC_LOOP:
    setp.ge.u32 %p0, %r18, %r2;
    @%p0 bra IC_END;

    mov.u32 %r19, 0;          // ky = 0

KY_LOOP:
    setp.ge.u32 %p0, %r19, 11;
    @%p0 bra KY_END;

    mov.u32 %r20, 0;          // kx = 0

KX_LOOP:
    setp.ge.u32 %p0, %r20, 11;
    @%p0 bra KX_END;

    // absolute input coordinates
    add.u32 %r21, %r16, %r19; // in_y
    add.u32 %r22, %r17, %r20; // in_x

    // bounds check for input pixel
    setp.ge.u32 %p1, %r21, %r3;   // in_y >= inH ?
    setp.lt.u32 %p2, %r21, 0;    // in_y < 0 ?
    or.pred %p1, %p1, %p2;       // out of y bounds?
    setp.ge.u32 %p2, %r22, %r4;   // in_x >= inW ?
    setp.lt.u32 %p3, %r22, 0;    // in_x < 0 ?
    or.pred %p2, %p2, %p3;
    or.pred %p0, %p1, %p2;
    @%p0 bra SKIP;               // skip if out of bounds

    // ---- load input value (fp16) -> fp32 ----
    // idx = ((b*inC + ic)*inH + in_y)*inW + in_x
    mul.lo.u32 %r23, %r10, %r2;
    add.u32    %r23, %r23, %r18;
    mul.lo.u32 %r23, %r23, %r3;
    add.u32    %r23, %r23, %r21;
    mul.lo.u32 %r23, %r23, %r4;
    add.u32    %r23, %r23, %r22;
    cvt.u64.u32 %rd9, %r23;
    mul.lo.u64 %rd9, %rd9, 2;
    add.u64    %rd10, %rd2, %rd9;
    ld.global.u16 %ru16, [%rd10];
    cvt.f16.u16.rn %fh1, %ru16;
    cvt.f32.f16.rn %f2, %fh1;

    // ---- load weight value (fp16) -> fp32 ----
    // idx = ((oc*inC + ic)*K + ky)*K + kx   (K=11)
    mul.lo.u32 %r24, %r11, %r2;
    add.u32    %r24, %r24, %r18;
    mul.lo.u32 %r24, %r24, 11;
    add.u32    %r24, %r24, %r19;
    mul.lo.u32 %r24, %r24, 11;
    add.u32    %r24, %r24, %r20;
    cvt.u64.u32 %rd11, %r24;
    mul.lo.u64 %rd11, %rd11, 2;
    add.u64    %rd12, %rd3, %rd11;
    ld.global.u16 %ru16, [%rd12];
    cvt.f16.u16.rn %fh2, %ru16;
    cvt.f32.f16.rn %f3, %fh2;

    // ---- multiply‑accumulate ----
    fma.rn.f32 %f1, %f2, %f3, %f1;

SKIP:
    add.u32 %r20, %r20, 1;
    bra KX_LOOP;
KX_END:
    add.u32 %r19, %r19, 1;
    bra KY_LOOP;
KY_END:
    add.u32 %r18, %r18, 1;
    bra IC_LOOP;
IC_END:

    // -------------------------------------------------
    // store output (fp32 -> fp16)
    // -------------------------------------------------
    cvt.f16.f32.rn %fh3, %f1;
    cvt.u16.f16.rn %ru16, %fh3;
    st.global.u16 [%rd6], %ru16;

DONE:
    ret;
}
