                    add.u64 addr_tmp, addr_tmp, tmp64;
                    // * D
                    cvt.u64.u32 tmp64, D;
                    mul.lo.u64 addr_tmp, addr_tmp, tmp64;
                    // + id
                    cvt.u64.u32 tmp64, id;
                    add.u64 addr_tmp, addr_tmp, tmp64;
                    // * W
                    cvt.u64.u32 tmp64, W;
                    mul.lo.u64 addr_tmp, addr_tmp, tmp64;
                    // + iW
                    cvt.u64.u32 tmp64, iW;
                    add.u64 addr_tmp, addr_tmp, tmp64;
                    // * H
                    cvt.u64.u32 tmp64, H;
                    mul.lo.u64 addr_tmp, addr_tmp, tmp64;
                    // + iH
                    cvt.u64.u32 tmp64, iH;
                    add.u64 addr_tmp, addr_tmp, tmp64;
                    // *2 (bytes per fp16)
                    shl.b64 in_addr, addr_tmp, 1;
                    add.u64 in_addr, input, in_addr;

                    // --------------------------------------------------
                    // Compute weight address offset (in elements)
                    // offset = ((((oc*IC)+ic)*K + kd)*K + kw)*K + kh
                    // --------------------------------------------------
                    mul.wide.u32 addr_tmp, oc32, IC;   // oc*IC
                    cvt.u64.u32 tmp64, ic;
                    add.u64 addr_tmp, addr_tmp, tmp64; // +ic
                    // *K
                    cvt.u64.u32 tmp64, K;
                    mul.lo.u64 addr_tmp, addr_tmp, tmp64;
                    // +kd
                    cvt.u64.u32 tmp64, kd;
                    add.u64 addr_tmp, addr_tmp, tmp64;
                    // *K
                    cvt.u64.u32 tmp64, K;
                    mul.lo.u64 addr_tmp, addr_tmp, tmp64;
                    // +kw
                    cvt.u64.u32 tmp64, kw;
                    add.u64 addr_tmp, addr_tmp, tmp64;
                    // *K
                    cvt.u64.u32 tmp64, K;
                    mul.lo.u64 addr_tmp, addr_tmp, tmp64;
                    // +kh
                    cvt.u64.u32 tmp64, kh;
                    add.u64 addr_tmp, addr_tmp, tmp64;
                    // *2 (bytes)
                    shl.b64 w_addr, addr_tmp, 1;
                    add.u64 w_addr, weight, w_addr;

                    // Load fp16 values and convert to fp32
                    ld.global.f16 in_f16, [in_addr];
                    cvt.f32.f16 in_f32, in_f16;
                    ld.global.f16 w_f16, [w_addr];
                    cvt.f32.f16 w_f32, w_f16;

                    // Accumulate
                    fma.rn.f32 acc, in_f32, w_f32, acc;

                // kh++
                add.u32 kh, kh, 1;
                bra kh_loop;
kh_done:

                // kw++
                add.u32 kw, kw, 1;
                bra kw_loop;
kw_done:

            // kd++
            add.u32 kd, kd, 1;
            bra kd_loop;
kd_done:

        // ic++
        add.u32 ic, ic, 1;
        bra ic_loop;
ic_done:

    // --------------------------------------------------------------
    // Write output (convert float32 -> fp16)
    // --------------------------------------------------------------
    .reg .f16 out_f16;
    cvt.f16.f32 out_f16, acc;

    // output offset = ((((n*OC)+oc)*outD + od)*outW + ow)*outH + oh
    mul.wide.u32 addr_tmp, n32, OC;          // n*OC
    cvt.u64.u32 tmp64, oc32;
    add.u64 addr_tmp, addr_tmp, tmp64;       // +oc
    cvt.u64.u32 tmp64, outD;
    mul.lo.u64 addr_tmp, addr_tmp, tmp64;    // *outD
    cvt.u64.u32 tmp64, od32;
    add.u64 addr_tmp, addr_tmp, tmp64;       // +od
    cvt.u64.u32 tmp64, outW;
    mul.lo.u64 addr_tmp, addr_tmp, tmp64;    // *outW
    cvt.u64.u32 tmp64, ow32;
    add.u64 addr_tmp, addr_tmp, tmp64;       // +ow
    cvt.u64.u32 tmp64, outH;
    mul.lo.u64 addr_tmp, addr_tmp, tmp64;    // *outH
    cvt.u64.u32 tmp64, oh32;
    add.u64 addr_tmp, addr_tmp, tmp64;       // +oh
    shl.b64 addr_tmp, addr_tmp, 1;           // *2 bytes
    add.u64 addr_tmp, output, addr_tmp;
    st.global.f16 [addr_tmp], out_f16;

    ret;
