class ModelNew:
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        # Load the PTX module (ptx_load provided by the harness)
        self.module = ptx_load(PTX_SOURCE)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.weight = None   # allocated on first forward

    def __call__(self, x):
        import torch, math
        device = x.device

        # Allocate weight on first call
        if self.weight is None:
            self.weight = torch.empty(
                (self.out_channels,
                 self.in_channels,
                 self.kernel_size,
                 self.kernel_size,
                 self.kernel_size),
                dtype=torch.float16,
                device=device)
            torch.nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        # Input dimensions
        N, C_in, D, W, H = x.shape
        stride = 1
        padding = 0
        dilation = 1

        # Output dimensions (same formula as in PTX)
        out_D = (D + 2 * padding - dilation * (self.kernel_size - 1) - 1) // stride + 1
        out_W = (W + 2 * padding - dilation * (self.kernel_size - 1) - 1) // stride + 1
        out_H = (H + 2 * padding - dilation * (self.kernel_size - 1) - 1) // stride + 1

        out = torch.empty(
            (N, self.out_channels, out_D, out_W, out_H),
            dtype=torch.float16,
            device=device)

        total = N * self.out_channels * out_D * out_W * out_H
        threads_per_block = 256
        blocks = (total + threads_per_block - 1) // threads_per_block

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            0,                         # bias pointer (unused)
            out.data_ptr(),
            N,
            self.in_channels,
            self.out_channels,
            D,
            W,
            H,
            self.kernel_size,
            stride,
            padding,
            dilation
        ]

        # Launch the kernel (ptx_launch provided by the harness)
        ptx_launch(self.module, "conv3d_kernel", (blocks,), (threads_per_block,), args)

        return out

