PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry conv3d_fp16 (
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 in_channels,
    .param .u32 out_channels,
    .param .u32 D,
    .param .u32 W,
    .param .u32 H,
    .param .u32 K
)
{
    // -------------------------------------------------
    // Thread identifier (global linear index)
    // -------------------------------------------------
    .reg .u32 %tid_x, %ctaid_x, %ntid_x, %gid32;
    .reg .u64 %gid;
    mov.u32 %tid_x, %tid.x;
    mov.u32 %ctaid_x, %ctaid.x;
    mov.u32 %ntid_x, %ntid.x;
    mad.lo.u32 %gid32, %ctaid_x, %ntid_x, %tid_x;
    cvt.u64.u32 %gid, %gid32;

    // -------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------
    .reg .u64 %inp_ptr, %wgt_ptr, %out_ptr;
    .reg .u32 %B, %IC, %OC, %D_in, %W_in, %H_in, %Ksize;
    ld.param.u64 %inp_ptr, [input_ptr];
    ld.param.u64 %wgt_ptr, [weight_ptr];
    ld.param.u64 %out_ptr, [output_ptr];
    ld.param.u32 %B,       [batch];
    ld.param.u32 %IC,      [in_channels];
    ld.param.u32 %OC,      [out_channels];
    ld.param.u32 %D_in,    [D];
    ld.param.u32 %W_in,    [W];
    ld.param.u32 %H_in,    [H];
    ld.param.u32 %Ksize,   [K];

    // -------------------------------------------------
    // Output dimensions (stride=1, padding=0)
    // -------------------------------------------------
    .reg .u32 %D_out, %W_out, %H_out;
    sub.u32 %D_out, %D_in, %Ksize;   add.u32 %D_out, %D_out, 1;
    sub.u32 %W_out, %W_in, %Ksize;   add.u32 %W_out, %W_out, 1;
    sub.u32 %H_out, %H_in, %Ksize;   add.u32 %H_out, %H_out, 1;

    // -------------------------------------------------
    // Compute total number of output elements
    // -------------------------------------------------
    .reg .u32 %out_spatial32, %per_batch32;
    .reg .u64 %out_spatial64, %per_batch64, %total64;
    mul.lo.u32 %out_spatial32, %D_out, %W_out;
    mul.lo.u32 %out_spatial32, %out_spatial32, %H_out;          // D_out*W_out*H_out
    mul.lo.u32 %per_batch32, %OC, %out_spatial32;               // outC * out_spatial
    mul.wide.u32 %total64, %B, %per_batch32;                    // total = B * per_batch

    // -------------------------------------------------
    // Early exit if thread id >= total
    // -------------------------------------------------
    .reg .pred %p_exit;
    setp.ge.u64 %p_exit, %gid, %total64;
    @%p_exit ret;

    // -------------------------------------------------
    // Decompose linear index %gid -> (n, oc, d, w, h)
    // -------------------------------------------------
    .reg .u64 %tmp64, %rem, %per_batch64_tmp;
    .reg .u32 %n, %oc, %d, %w, %h;
    .reg .u32 %spatial2;
    .reg .u64 %spatial2_64, %out_spatial64_tmp;
    .reg .u32 %tmp32;
    .reg .u64 %tmp64b;

    cvt.u64.u32 %per_batch64_tmp, %per_batch32;
    div.u64 %tmp64, %gid, %per_batch64_tmp;
    cvt.u32.u64 %n, %tmp64;                         // batch index

    mul.wide.u32 %tmp64, %n, %per_batch32;
    sub.u64 %rem, %gid, %tmp64;                     // remainder after batch

    cvt.u64.u32 %out_spatial64_tmp, %out_spatial32;
    div.u64 %tmp64, %rem, %out_spatial64_tmp;
    cvt.u32.u64 %oc, %tmp64;                        // out channel

    mul.wide.u32 %tmp64, %oc, %out_spatial32;
    sub.u64 %rem, %rem, %tmp64;                     // remainder after channel

    mul.lo.u32 %spatial2, %W_out, %H_out;
    cvt.u64.u32 %spatial2_64, %spatial2;

    div.u64 %tmp64, %rem, %spatial2_64;
    cvt.u32.u64 %d, %tmp64;                         // depth

    mul.wide.u32 %tmp64, %d, %spatial2;
    sub.u64 %rem, %rem, %tmp64;                     // remainder after depth

    div.u64 %tmp64, %rem, %H_out;
    cvt.u32.u64 %w, %tmp64;                         // width

    mul.wide.u32 %tmp64, %w, %H_out;
    sub.u64 %rem, %rem, %tmp64;                     // remainder after width

    cvt.u32.u64 %h, %rem;                           // height

    // -------------------------------------------------
    // Convolution accumulation (FP32 accumulator)
    // -------------------------------------------------
    .reg .f32 %acc;
    mov.f32 %acc, 0f0;

    .reg .u32 %ic, %kd, %kh, %kw;
    .reg .pred %p_done;

    mov.u32 %ic, 0;
ic_loop:
    setp.ge.u32 %p_done, %ic, %IC;
    @%p_done bra ic_done;

    mov.u32 %kd, 0;
kd_loop:
    setp.ge.u32 %p_done, %kd, %Ksize;
    @%p_done bra kd_done;

    mov.u32 %kh, 0;
kh_loop:
    setp.ge.u32 %p_done, %kh, %Ksize;
    @%p_done bra kh_done;

    mov.u32 %kw, 0;
kw_loop:
    setp.ge.u32 %p_done, %kw, %Ksize;
    @%p_done bra kw_done;

    // ------------------- Load input element (fp16) -------------------
    .reg .u64 %in_idx;
    // (( ( (n*IC) + ic) * D_in + (d+kd) ) * W_in + (w+kh) ) * H_in + (h+kw)
    mul.wide.u32 %tmp64, %n, %IC;
    add.u64 %in_idx, %tmp64, %ic;                     // n*IC + ic

    mul.wide.u32 %tmp64, %in_idx, %D_in;
    add.u32 %tmp32, %d, %kd;
    cvt.u64.u32 %tmp64b, %tmp32;
    add.u64 %in_idx, %tmp64, %tmp64b;                 // + (d+kd)

    mul.wide.u32 %tmp64, %in_idx, %W_in;
    add.u32 %tmp32, %w, %kh;
    cvt.u64.u32 %tmp64b, %tmp32;
    add.u64 %in_idx, %tmp64, %tmp64b;                 // + (w+kh)

    mul.wide.u32 %tmp64, %in_idx, %H_in;
    add.u32 %tmp32, %h, %kw;
    cvt.u64.u32 %tmp64b, %tmp32;
    add.u64 %in_idx, %tmp64, %tmp64b;                 // + (h+kw)

    shl.b64 %in_idx, %in_idx, 1;                     // fp16 -> 2 bytes
    .reg .f16 %inp_f16;
    ld.global.f16 %inp_f16, [%inp_ptr + %in_idx];
    .reg .f32 %inp_f32;
    cvt.f32.f16 %inp_f32, %inp_f16;

    // ------------------- Load weight element (fp16) -------------------
    .reg .u64 %w_idx;
    // (( ( (oc*IC) + ic) * Ksize + kd) * Ksize + kh) * Ksize + kw
    mul.wide.u32 %tmp64, %OC, %IC;
    add.u64 %w_idx, %tmp64, %ic;                     // oc*IC + ic

    mul.wide.u32 %tmp64, %w_idx, %Ksize;
    add.u64 %w_idx, %tmp64, %kd;                     // *K + kd

    mul.wide.u32 %tmp64, %w_idx, %Ksize;
    add.u64 %w_idx, %tmp64, %kh;                     // *K + kh

    mul.wide.u32 %tmp64, %w_idx, %Ksize;
    add.u64 %w_idx, %tmp64, %kw;                     // *K + kw

    shl.b64 %w_idx, %w_idx, 1;                       // fp16 -> 2 bytes
    .reg .f16 %w_f16;
    ld.global.f16 %w_f16, [%wgt_ptr + %w_idx];
    .reg .f32 %w_f32;
    cvt.f32.f16 %w_f32, %w_f16;

    // ------------------- Accumulate -------------------
    fma.rn.f32 %acc, %w_f32, %inp_f32, %acc;

    // ------------------- Loop increments -------------------
    add.u32 %kw, %kw, 1;
    bra kw_loop;
kw_done:
    add.u32 %kh, %kh, 1;
    bra kh_loop;
kh_done:
    add.u32 %kd, %kd, 1;
    bra kd_loop;
kd_done:
    add.u32 %ic, %ic, 1;
    bra ic_loop;
ic_done:

    // -------------------------------------------------
    // Store output (fp16)
    // -------------------------------------------------
    .reg .f16 %out_f16;
    cvt.rn.f16.f32 %out_f16, %acc;

    .reg .u64 %out_idx;
    // (( ( (n*OC) + oc) * D_out + d) * W_out + w) * H_out + h
    mul.wide.u32 %tmp64, %n, %OC;
    add.u64 %out_idx, %tmp64, %oc;                 // n*OC + oc

    mul.wide.u32 %tmp64, %out_idx, %D_out;
    add.u64 %out_idx, %tmp64, %d;                  // *D_out + d

    mul.wide.u32 %tmp64, %out_idx, %W_out;
    add.u64 %out_idx, %tmp64, %w;                  // *W_out + w

    mul.wide.u32 %tmp64, %out_idx, %H_out;
    add.u64 %out_idx, %tmp64, %h;                  // *H_out + h

    shl.b64 %out_idx, %out_idx, 1;                 // fp16 -> 2 bytes
    st.global.f16 [%out_ptr + %out_idx], %out_f16;

    ret;
}
