import math, torch

class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size

        # weight tensor in PyTorch layout: (out_channels, in_channels, K, K, K)
        self.weight = torch.empty(
            out_channels, in_channels, kernel_size, kernel_size, kernel_size,
            dtype=torch.float16, device='cuda')
        torch.nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        # Load PTX module once
        self._module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch, in_c, D, W, H = x.shape
        K = self.kernel_size
        D_out = D - K + 1
        W_out = W - K + 1
        H_out = H - K + 1

        out = torch.empty(
            batch, self.out_channels, D_out, W_out, H_out,
            dtype=torch.float16, device='cuda')

        total = batch * self.out_channels * D_out * W_out * H_out
        threads_per_block = 256
        blocks = (total + threads_per_block - 1) // threads_per_block

        ptx_launch(
            self._module,
            "conv3d_fp16",
            (blocks, 1, 1),
            (threads_per_block, 1, 1),
            (
                x.data_ptr(),
                self.weight.data_ptr(),
                out.data_ptr(),
                batch,
                self.in_channels,
                self.out_channels,
                D,
                W,
                H,
                K
            )
        )
        return out

