    ld.global.u16 %w_u16, [%addr];
    cvt.f16.u16 %w_f16, %w_u16;

    // multiply‑accumulate (fp16 → fp32)
    cvt.f32.f16 %v1, %in_f16;
    cvt.f32.f16 %v2, %w_f16;
    mad.rn.f32 %acc, %v1, %v2, %acc;

    // next kw
    add.u32 %kw, %kw, 1;
    bra kw_loop;
kw_done:

    // next kh
    add.u32 %kh, %kh, 1;
    bra kh_loop;
kw_loop_end:

    // next kd
    add.u32 %kd, %kd, 1;
    bra kd_loop;
kh_loop_end:

    // next cin
    add.u32 %cin, %cin, 1;
    bra cin_loop;
kd_loop_end:

    // ---------- write output ----------
    // ((((n*Cout + cout)*D_out + d_out)*H_out + h_out)*W_out + w_out)
    mul.lo.u32 %tmp, %n, %Cout;
    add.u32 %tmp, %tmp, %cout;         // n*Cout + cout
    mul.lo.u32 %tmp, %tmp, %D_out;
    add.u32 %tmp, %tmp, %d_out;
    mul.lo.u32 %tmp, %tmp, %H_out;
    add.u32 %tmp, %tmp, %h_out;
    mul.lo.u32 %tmp, %tmp, %W_out;
    add.u32 %tmp, %tmp, %w_out;

    mul.wide.u32 %addr, %tmp, 2;
    add.u64 %addr, %addr, %out_ptr;

    cvt.f16.f32 %out_f16, %acc;
    cvt.u16.f16 %out_u16, %out_f16;
    st.global.u16 [%addr], %out_u16;

    ret;
}
