import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        super().__init__()
        self.in_c = in_channels
        self.out_c = out_channels
        self.k = kernel_size

        # fp16 weight tensor on GPU (shape: out_c, in_c, K, K, K)
        self.weight = torch.randn(
            out_channels, in_channels, kernel_size, kernel_size, kernel_size,
            dtype=torch.float16, device='cuda'
        )

        # load PTX module via harness API
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C, D, H, W = x.shape
        K = self.k
        D_out = D - K + 1
        H_out = H - K + 1
        W_out = W - K + 1

        out = torch.empty(
            N, self.out_c, D_out, H_out, W_out,
            dtype=torch.float16, device='cuda'
        )

        total = N * self.out_c * D_out * H_out * W_out
        threads_per_block = 256
        blocks = (total + threads_per_block - 1) // threads_per_block

        grid = (blocks,)
        block = (threads_per_block,)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            out.data_ptr(),
            N, self.in_c, self.out_c,
            D, H, W, K
        ]

        ptx_launch(self.module, "conv3d_fp16", grid, block, args)

        return out

