PTX_SOURCE = r'''
.version 8.0
.target sm_80
.address_size 64

.visible .entry conv3d_fp16 (
    .param .u64   input_ptr,
    .param .u64   weight_ptr,
    .param .u64   bias_ptr,
    .param .u64   output_ptr,
    .param .u32   N,
    .param .u32   C_in,
    .param .u32   C_out,
    .param .u32   D_in,
    .param .u32   H_in,
    .param .u32   W_in,
    .param .u32   K,
    .param .u32   stride,
    .param .u32   padding,
    .param .u32   dilation,
    .param .u32   D_out,
    .param .u32   H_out,
    .param .u32   W_out,
    .param .u32   total_out
)
{
    // -------------------------------------------------------------
    // Thread index (linear)
    // -------------------------------------------------------------
    .reg .u32 %tid_x, %block_id, %block_dim, %lin_idx;
    mov.u32 %tid_x,    %tid.x;
    mov.u32 %block_id, %ctaid.x;
    mov.u32 %block_dim,%ntid.x;
    mad.lo.u32 %lin_idx, %block_id, %block_dim, %tid_x;

    // -------------------------------------------------------------
    // Bounds check
    // -------------------------------------------------------------
    .reg .pred %p_oob;
    .reg .u32  %total;
    ld.param.u32 %total, [total_out];
    setp.ge.u32 %p_oob, %lin_idx, %total;
    @%p_oob ret;

    // -------------------------------------------------------------
    // Load kernel parameters
    // -------------------------------------------------------------
    .reg .u64 %inp, %wgt, %bias, %out;
    .reg .u32 %n, %c_in, %c_out, %d_in, %h_in, %w_in;
    .reg .u32 %k, %s, %p, %dil, %d_out, %h_out, %w_out;

    ld.param.u64 %inp,   [input_ptr];
    ld.param.u64 %wgt,   [weight_ptr];
    ld.param.u64 %bias,  [bias_ptr];
    ld.param.u64 %out,   [output_ptr];
    ld.param.u32 %n,     [N];
    ld.param.u32 %c_in,  [C_in];
    ld.param.u32 %c_out, [C_out];
    ld.param.u32 %d_in,  [D_in];
    ld.param.u32 %h_in,  [H_in];
    ld.param.u32 %w_in,  [W_in];
    ld.param.u32 %k,     [K];
    ld.param.u32 %s,     [stride];
    ld.param.u32 %p,     [padding];
    ld.param.u32 %dil,   [dilation];
    ld.param.u32 %d_out, [D_out];
    ld.param.u32 %h_out, [H_out];
    ld.param.u32 %w_out, [W_out];

    // -------------------------------------------------------------
    // Decompose linear index -> (n, c_out, d_out, h_out, w_out)
    // -------------------------------------------------------------
    .reg .u32 %out_n, %out_c, %out_z, %out_y, %out_x, %tmp;
    mov.u32 %tmp, %lin_idx;
    rem.u32 %out_x, %tmp, %w_out;
    div.u32 %tmp, %tmp, %w_out;
    rem.u32 %out_y, %tmp, %h_out;
    div.u32 %tmp, %tmp, %h_out;
    rem.u32 %out_z, %tmp, %d_out;
    div.u32 %tmp, %tmp, %d_out;
    rem.u32 %out_c, %tmp, %c_out;
    div.u32 %out_n, %tmp, %c_out;

    // -------------------------------------------------------------
    // Accumulator (fp32)
    // -------------------------------------------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f00000000;

    // -------------------------------------------------------------
    // Convolution loops
    // -------------------------------------------------------------
    .reg .u32 %ic, %kz, %ky, %kx;
    .reg .pred %p_end;

    mov.u32 %ic, 0;
IC_LOOP:
    setp.ge.u32 %p_end, %ic, %c_in;
    @%p_end bra IC_END;

    mov.u32 %kz, 0;
KZ_LOOP:
    setp.ge.u32 %p_end, %kz, %k;
    @%p_end bra KZ_END;

    mov.u32 %ky, 0;
KY_LOOP:
    setp.ge.u32 %p_end, %ky, %k;
    @%p_end bra KY_END;

    mov.u32 %kx, 0;
KX_LOOP:
    setp.ge.u32 %p_end, %kx, %k;
    @%p_end bra KX_END;

    // -------------------------------------------------------------
    // Compute input coordinates
    // -------------------------------------------------------------
    .reg .s32 %in_z, %in_y, %in_x;
    mul.lo.s32 %in_z, %out_z, %s;
    sub.s32    %in_z, %in_z, %p;
    mad.lo.s32 %in_z, %kz, %dil, %in_z;

    mul.lo.s32 %in_y, %out_y, %s;
    sub.s32    %in_y, %in_y, %p;
    mad.lo.s32 %in_y, %ky, %dil, %in_y;

    mul.lo.s32 %in_x, %out_x, %s;
    sub.s32    %in_x, %in_x, %p;
    mad.lo.s32 %in_x, %kx, %dil, %in_x;

    // -------------------------------------------------------------
    // Bounds check on input
    // -------------------------------------------------------------
    .reg .pred %p_skip;
    setp.lt.s32 %p_skip, %in_z, 0;
    @%p_skip bra SKIP;
    setp.ge.s32 %p_skip, %in_z, %d_in;
    @%p_skip bra SKIP;
    setp.lt.s32 %p_skip, %in_y, 0;
    @%p_skip bra SKIP;
    setp.ge.s32 %p_skip, %in_y, %h_in;
    @%p_skip bra SKIP;
    setp.lt.s32 %p_skip, %in_x, 0;
    @%p_skip bra SKIP;
    setp.ge.s32 %p_skip, %in_x, %w_in;
    @%p_skip bra SKIP;

    // -------------------------------------------------------------
    // Compute linear offsets (in elements)
    // -------------------------------------------------------------
    .reg .u32 %in_off32, %w_off32, %t32;

    // input offset = (( ( (n*C_in + ic)*D_in + in_z)*H_in + in_y)*W_in + in_x)
    mul.lo.u32 %t32, %out_n, %c_in;
    add.u32 %t32, %t32, %ic;
    mul.lo.u32 %in_off32, %t32, %d_in;
    add.u32 %in_off32, %in_off32, %in_z;
    mul.lo.u32 %in_off32, %in_off32, %h_in;
    add.u32 %in_off32, %in_off32, %in_y;
    mul.lo.u32 %in_off32, %in_off32, %w_in;
    add.u32 %in_off32, %in_off32, %in_x;
    shl.b32 %in_off32, %in_off32, 1;          // *2 for fp16

    // weight offset = (( ( (c_out*C_in + ic)*K + kz)*K + ky)*K + kx)
    mul.lo.u32 %t32, %out_c, %c_in;
    add.u32 %t32, %t32, %ic;
    mul.lo.u32 %w_off32, %t32, %k;
    add.u32 %w_off32, %w_off32, %kz;
    mul.lo.u32 %w_off32, %w_off32, %k;
    add.u32 %w_off32, %w_off32, %ky;
    mul.lo.u32 %w_off32, %w_off32, %k;
    add.u32 %w_off32, %w_off32, %kx;
    shl.b32 %w_off32, %w_off32, 1;           // *2 for fp16

    // -------------------------------------------------------------
    // Convert offsets to byte addresses and load values
    // -------------------------------------------------------------
    .reg .u64 %addr_in, %addr_wgt, %addr_tmp;
    cvt.u64.u32 %addr_tmp, %in_off32;
    add.u64 %addr_in, %inp, %addr_tmp;

    cvt.u64.u32 %addr_tmp, %w_off32;
    add.u64 %addr_wgt, %wgt, %addr_tmp;

    .reg .f16 %in_h, %w_h;
    ld.global.f16 %in_h, [%addr_in];
    ld.global.f16 %w_h,  [%addr_wgt];

    .reg .f32 %in_f, %w_f;
    cvt.f32.f16 %in_f, %in_h;
    cvt.f32.f16 %w_f,  %w_h;
    fma.rn.f32 %sum, %in_f, %w_f, %sum;

SKIP:
    add.u32 %kx, %kx, 1;
    bra KX_LOOP;
KX_END:
    add.u32 %ky, %ky, 1;
    bra KY_LOOP;
KY_END:
    add.u32 %kz, %kz, 1;
    bra KZ_LOOP;
KZ_END:
    add.u32 %ic, %ic, 1;
    bra IC_LOOP;
IC_END:

    // -------------------------------------------------------------
    // Add bias if present
    // -------------------------------------------------------------
    .reg .pred %p_has_bias;
    setp.ne.u64 %p_has_bias, %bias, 0;
    @%p_has_bias {
        .reg .u64 %bias_addr;
        mul.wide.u32 %bias_addr, %out_c, 2;          // bias offset in bytes
        .reg .u64 %bias_full;
        add.u64 %bias_full, %bias, %bias_addr;
        .reg .f16 %b_h;
        ld.global.f16 %b_h, [%bias_full];
        .reg .f32 %b_f;
        cvt.f32.f16 %b_f, %b_h;
        add.f32 %sum, %sum, %b_f;
    }

    // -------------------------------------------------------------
    // Write output (fp16)
    // -------------------------------------------------------------
    .reg .f16 %out_h;
    cvt.rn.f16.f32 %out_h, %sum;

    // output offset = (( ( (n*C_out + c_out)*D_out + out_z)*H_out + out_y)*W_out + out_x)
    .reg .u32 %out_off32;
    mul.lo.u32 %t32, %out_n, %c_out;
    add.u32 %t32, %t32, %out_c;
    mul.lo.u32 %out_off32, %t32, %d_out;
    add.u32 %out_off32, %out_off32, %out_z;
    mul.lo.u32 %out_off32, %out_off32, %h_out;
    add.u32 %out_off32, %out_off32, %out_y;
    mul.lo.u32 %out_off32, %out_off32, %w_out;
    add.u32 %out_off32, %out_off32, %out_x;
    shl.b32 %out_off32, %out_off32, 1;          // *2 for fp16

    .reg .u64 %addr_out;
    cvt.u64.u32 %addr_out, %out_off32;
    .reg .u64 %addr_out_full;
    add.u64 %addr_out_full, %out, %addr_out;
    st.global.f16 [%addr_out_full], %out_h;

    ret;
}
