class ModelNew:
    """
    Drop‑in replacement for the reference Model using a PTX 3D convolution kernel.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False):
        assert groups == 1, "Only groups=1 is supported in this PTX implementation."
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.bias = bias

        # Load PTX module
        self.module = ptx_load(PTX_SOURCE)

        # Allocate weight (and optional bias) on GPU, fp16
        weight_shape = (out_channels,
                        in_channels,
                        kernel_size, kernel_size, kernel_size)
        self.weight = torch.randn(weight_shape,
                                 dtype=torch.float16,
                                 device='cuda')
        self.bias_tensor = None
        if bias:
            self.bias_tensor = torch.randn(out_channels,
                                           dtype=torch.float16,
                                           device='cuda')

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C_in, D_in, H_in, W_in = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        DIL = self.dilation

        D_out = (D_in + 2 * P - DIL * (K - 1) - 1) // S + 1
        H_out = (H_in + 2 * P - DIL * (K - 1) - 1) // S + 1
        W_out = (W_in + 2 * P - DIL * (K - 1) - 1) // S + 1

        out = torch.empty((N, self.out_channels, D_out, H_out, W_out),
                         dtype=torch.float16,
                         device='cuda')

        total_out_elements = out.numel()
        threads_per_block = 256
        blocks = (total_out_elements + threads_per_block - 1) // threads_per_block

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            0 if self.bias_tensor is None else self.bias_tensor.data_ptr(),
            out.data_ptr(),
            N,
            C_in,
            self.out_channels,
            D_in,
            H_in,
            W_in,
            K,
            S,
            P,
            DIL,
            D_out,
            H_out,
            W_out,
            total_out_elements
        ]

        ptx_launch(self.module,
                   "conv3d_fp16",
                   (blocks,),
                   (threads_per_block,),
                   args)

        return out

