    cvt.rn.f16.f32 %out_f16, %acc;

    .reg .u64 %out_tmp, %out_offset, %out_addr;
    cvt.u64.u32 %out_tmp, %n;
    mul.lo.u64 %out_tmp, %out_tmp, %out_c64;
    add.u64 %out_tmp, %out_tmp, %oc;
    mul.lo.u64 %out_tmp, %out_tmp, %out_h64;
    add.u64 %out_tmp, %out_tmp, %oh;
    mul.lo.u64 %out_tmp, %out_tmp, %out_w64;
    add.u64 %out_tmp, %out_tmp, %ow;
    shl.b64 %out_offset, %out_tmp, 1;          // *2 bytes per fp16
    add.u64 %out_addr, %output_ptr, %out_offset;

    st.global.f16 [%out_addr], %out_f16;

    // -------------------------------------------------
    // Advance to next element (grid‑stride)
    // -------------------------------------------------
    add.u32 %global_idx, %global_idx, %stride;
    bra LOOP_BEGIN;

