.visible .entry conv_transpose_fp16(
    .param .u64   input_ptr,
    .param .u64   weight_ptr,
    .param .u64   output_ptr,
    .param .u32   N,
    .param .u32   C_in,
    .param .u32   C_out,
    .param .u32   H_in,
    .param .u32   W_in,
    .param .u32   K,
    .param .u32   stride,
    .param .u32   padding,
    .param .u32   out_pad,
    .param .u32   H_out,
    .param .u32   W_out
