    // -------------------------------------------------------------
    .reg .u64   in_ptr, w_ptr, out_ptr;
    .reg .u32   N_reg, C_in_reg, C_out_reg, H_in_reg, W_in_reg;
    .reg .u32   K_reg, stride_reg, pad_reg, out_pad_reg, H_out_reg, W_out_reg;

