    ld.param.u64   w_ptr,       [weight_ptr];
    ld.param.u64   out_ptr,     [output_ptr];
    ld.param.u32   N_reg,       [N];
    ld.param.u32   C_in_reg,    [C_in];
    ld.param.u32   C_out_reg,   [C_out];
    ld.param.u32   H_in_reg,    [H_in];
    ld.param.u32   W_in_reg,    [W_in];
    ld.param.u32   K_reg,       [K];
    ld.param.u32   stride_reg,  [stride];
    ld.param.u32   pad_reg,     [padding];
    ld.param.u32   out_pad_reg, [out_pad];
    ld.param.u32   H_out_reg,   [H_out];
    ld.param.u32   W_out_reg,   [W_out];

