    // Thread identification (global linear index)
    // -------------------------------------------------------------
    .reg .u32   tid_x, blk_x, blk_dim_x, gid;
    mov.u32     tid_x, %tid.x;
    mov.u32     blk_x, %ctaid.x;
    mov.u32     blk_dim_x, %ntid.x;
    mad.lo.u32  gid, blk_x, blk_dim_x, tid_x;

