    mul.lo.u32  total, N_reg, C_out_reg;
    mul.lo.u32  total, total, H_out_reg;
    mul.lo.u32  total, total, W_out_reg;

    .reg .pred p_exit;
    setp.ge.u32 p_exit, gid, total;
    @p_exit ret;

