    mul.lo.u32  div1, div1, W_out_reg;

    // n = gid / div1
    div.u32     n, gid, div1;
    // rem = gid % div1
    rem.u32     rem, gid, div1;

    // div2 = H_out * W_out
    mul.lo.u32  div2, H_out_reg, W_out_reg;

    // c_out = rem / div2
    div.u32     c_out, rem, div2;
    // rem = rem % div2
    rem.u32     rem, rem, div2;

    // w_out = rem % W_out
    rem.u32     w_out, rem, W_out_reg;
    // h_out = (rem - w_out) / W_out
    sub.u32     tmp, rem, w_out;
    div.u32     h_out, tmp, W_out_reg;

