c_in_loop:
    setp.ge.u32 p_skip, c_in, C_in_reg;
    @p_skip bra c_in_end;

    // Loop over kernel height
    mov.u32 kh, 0;
kh_loop:
    setp.ge.u32 p_skip, kh, K_reg;
    @p_skip bra kh_end;

    // Loop over kernel width
    mov.u32 kw, 0;
kw_loop:
    setp.ge.u32 p_skip, kw, K_reg;
    @p_skip bra kw_end;

