    cvt.s32.u32 src_h, h_out;
    add.s32     src_h, src_h, pad_reg;
    sub.s32     src_h, src_h, kh;
    cvt.s32.u32 src_w, w_out;
    add.s32     src_w, src_w, pad_reg;
    sub.s32     src_w, src_w, kw;

