    @p_skip bra kw_next;
    setp.ge.s32 p_skip, src_h, H_in_reg;
    @p_skip bra kw_next;
    setp.lt.s32 p_skip, src_w, 0;
    @p_skip bra kw_next;
    setp.ge.s32 p_skip, src_w, W_in_reg;
    @p_skip bra kw_next;

