    mul.lo.u32  tmp, n, C_in_reg;
    add.u32     tmp, tmp, c_in;
    mul.lo.u32  tmp, tmp, H_in_reg;
    cvt.u32.s32 src_h_u, src_h;
    add.u32     tmp, tmp, src_h_u;
    mul.lo.u32  tmp, tmp, W_in_reg;
    cvt.u32.s32 src_w_u, src_w;
    add.u32     in_idx, tmp, src_w_u;

    .reg .u64 in_off;
    mul.wide.u32 in_off, in_idx, 2;   // fp16 = 2 bytes

    // -------------------------------------------------------------
    // Linear index for weight tensor
    // ((c_in * C_out + c_out) * K + kh) * K + kw
    // -------------------------------------------------------------
    .reg .u32 w_idx;
    mul.lo.u32  tmp, c_in, C_out_reg;
    add.u32     tmp, tmp, c_out;
    mul.lo.u32  tmp, tmp, K_reg;
    add.u32     tmp, tmp, kh;
    mul.lo.u32  tmp, tmp, K_reg;
    add.u32     w_idx, tmp, kw;

    .reg .u64 w_off;
    mul.wide.u32 w_off, w_idx, 2;

