    // Load input and weight (reinterpret bits), convert to fp32, MAC
    // -------------------------------------------------------------
    .reg .u16   in_bits, w_bits;
    .reg .f16   in_f16, w_f16;
    .reg .f32   in_f32, w_f32, prod_f32;
    .reg .u64   addr;

