    add.u64 addr, in_ptr, in_off;
    ld.global.b16 in_bits, [addr];
    mov.b16 in_f16, in_bits;               // reinterpret bits as fp16
    cvt.f32.f16 in_f32, in_f16;            // fp16 -> fp32 (no rounding needed)

    // weight
    add.u64 addr, w_ptr, w_off;
    ld.global.b16 w_bits, [addr];
    mov.b16 w_f16, w_bits;                  // reinterpret bits as fp16
    cvt.f32.f16 w_f32, w_f16;               // fp16 -> fp32

    mul.f32 prod_f32, in_f32, w_f32;
    add.f32 acc, acc, prod_f32;

kw_next:
    add.u32 kw, kw, 1;
    bra kw_loop;
kw_end:

kh_next:
    add.u32 kh, kh, 1;
    bra kh_loop;
kh_end:

c_in_next:
    add.u32 c_in, c_in, 1;
    bra c_in_loop;
c_in_end:

