    mul.lo.u32  tmp, tmp, H_out_reg;
    add.u32     tmp, tmp, h_out;
    mul.lo.u32  tmp, tmp, W_out_reg;
    add.u32     out_idx, tmp, w_out;

    .reg .u64 out_off;
    mul.wide.u32 out_off, out_idx, 2;

    add.u64 addr, out_ptr, out_off;
    st.global.b16 [addr], acc_bits;

    ret;
