import torch
import torch.nn as nn
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        assert groups == 1, "Only groups=1 is supported"
        assert not bias, "Bias not supported"
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding

        # weight layout: (in_channels, out_channels, K, K) – matches nn.ConvTranspose2d
        self.weight = torch.randn(in_channels,
                                  out_channels,
                                  kernel_size,
                                  kernel_size,
                                  dtype=torch.float16,
                                  device='cuda')
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C_in, H_in, W_in = x.shape
        K = self.kernel_size
        stride = self.stride
        padding = self.padding
        out_pad = self.output_padding

        H_out = (H_in - 1) * stride - 2 * padding + K + out_pad
        W_out = (W_in - 1) * stride - 2 * padding + K + out_pad

        out = torch.empty((N, self.out_channels, H_out, W_out),
                          dtype=torch.float16,
                          device=x.device)

        total = N * self.out_channels * H_out * W_out
        threads_per_block = 256
        blocks = (total + threads_per_block - 1) // threads_per_block

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            out.data_ptr(),
            N,
            self.in_channels,
            self.out_channels,
            H_in,
            W_in,
            K,
            stride,
            padding,
            out_pad,
            H_out,
            W_out
        ]

        ptx_launch(self.module,
                    "conv_transpose_fp16",
                    (blocks, 1, 1),
                    (threads_per_block, 1, 1),
                    args)

        return out

