    ld.param.u64 %out_ptr,  [output];

    .reg .u32 %batch, %in_ch, %out_ch, %len_in, %len_out;
    .reg .u32 %ksize, %stride, %dilation;
    ld.param.u32 %batch,   [batch];
    ld.param.u32 %in_ch,   [in_ch];
    ld.param.u32 %out_ch,  [out_ch];
    ld.param.u32 %len_in,  [len_in];
    ld.param.u32 %len_out, [len_out];
    ld.param.u32 %ksize,   [ksize];
    ld.param.u32 %stride,  [stride];
    ld.param.u32 %dilation,[dilation];

    // ----------------------------------------------------------
    // Guard: if output channel >= out_ch, exit
    // ----------------------------------------------------------
    .reg .pred %p_exit;
    setp.ge.u32 %p_exit, %oc, %out_ch;
    @%p_exit ret;

    // ----------------------------------------------------------
    // Accumulator (FP32)
    // ----------------------------------------------------------
    .reg .f32 %acc;
    mov.f32 %acc, 0f00000000;        // 0.0f

    // ----------------------------------------------------------
    // Loops over input channels (ic) and kernel positions (k)
    // ----------------------------------------------------------
    .reg .u32 %ic, %k;
    mov.u32 %ic, 0;

IC_LOOP:
    setp.ge.u32 %p_exit, %ic, %in_ch;
    @%p_exit bra END_KERNEL;

    mov.u32 %k, 0;

K_LOOP:
    setp.ge.u32 %p_exit, %k, %ksize;
    @%p_exit bra IC_INC;

    // ---- compute input element index (in elements) -----------------
    .reg .u32 %tmp1, %tmp2, %in_idx32;
    mul.lo.u32 %tmp1, %b, %in_ch;
    add.u32 %tmp1, %tmp1, %ic;
    mul.lo.u32 %in_idx32, %tmp1, %len_in;
    mul.lo.u32 %tmp2, %ox, %stride;
    add.u32 %in_idx32, %in_idx32, %tmp2;
    mul.lo.u32 %tmp2, %k, %dilation;
    add.u32 %in_idx32, %in_idx32, %tmp2;

    .reg .u64 %in_idx64, %in_off, %in_addr;
    cvt.u64.u32 %in_idx64, %in_idx32;
    shl.b64 %in_off, %in_idx64, 1;          // *2 (bytes)
    add.u64 %in_addr, %in_ptr, %in_off;

    // ---- compute weight element index (in elements) ---------------
    .reg .u32 %w_idx32;
    mul.lo.u32 %tmp1, %oc, %in_ch;
    add.u32 %tmp1, %tmp1, %ic;
    mul.lo.u32 %w_idx32, %tmp1, %ksize;
    add.u32 %w_idx32, %w_idx32, %k;

    .reg .u64 %w_idx64, %w_off, %w_addr;
    cvt.u64.u32 %w_idx64, %w_idx32;
    shl.b64 %w_off, %w_idx64, 1;            // *2 (bytes)
    add.u64 %w_addr, %w_ptr, %w_off;

    // ---- load fp16 values, convert to fp32, MAC ------------------
    .reg .f16 %in_f16, %w_f16;
    .reg .f32 %in_f32, %w_f32, %prod;
    ld.global.f16 %in_f16, [%in_addr];
    ld.global.f16 %w_f16,  [%w_addr];
    cvt.rn.f32.f16 %in_f32, %in_f16;
    cvt.rn.f32.f16 %w_f32,  %w_f16;
    mul.f32 %prod, %in_f32, %w_f32;
    add.f32 %acc, %acc, %prod;

    // k++
    add.u32 %k, %k, 1;
    bra K_LOOP;

IC_INC:
    // ic++
    add.u32 %ic, %ic, 1;
    bra IC_LOOP;

END_KERNEL:
    // ------------------------------------------------------
    // Add bias if provided (bias pointer non‑zero)
    // ------------------------------------------------------
    .reg .pred %p_bias_null;
    setp.eq.u64 %p_bias_null, %bias_ptr, 0;
    @%p_bias_null bra STORE;

    .reg .f16 %bias_f16;
    .reg .u64 %bias_off, %bias_addr;
    mul.wide.u32 %bias_off, %oc, 2;          // bytes offset
    add.u64 %bias_addr, %bias_ptr, %bias_off;
    ld.global.f16 %bias_f16, [%bias_addr];
    .reg .f32 %bias_f32;
    cvt.rn.f32.f16 %bias_f32, %bias_f16;
    add.f32 %acc, %acc, %bias_f32;

STORE:
    // ------------------------------------------------------
    // Convert accumulator to fp16 and store
    // ------------------------------------------------------
    .reg .f16 %out_f16;
    cvt.rn.f16.f32 %out_f16, %acc;

    // output element index: ((b * out_ch) + oc) * len_out + ox
    .reg .u32 %out_idx32;
    mul.lo.u32 %tmp1, %b, %out_ch;
    add.u32 %tmp1, %tmp1, %oc;
    mul.lo.u32 %out_idx32, %tmp1, %len_out;
    add.u32 %out_idx32, %out_idx32, %ox;

    .reg .u64 %out_idx64, %out_off, %out_addr;
    cvt.u64.u32 %out_idx64, %out_idx32;
    shl.b64 %out_off, %out_idx64, 1;         // *2 (bytes)
    add.u64 %out_addr, %out_ptr, %out_off;

    st.global.f16 [%out_addr], %out_f16;

    ret;
}
'''

# --------------------------------------------------------------
# Model wrapper that uses the PTX kernel
# --------------------------------------------------------------
class ModelNew:
    """
    Drop‑in replacement for torch.nn.Conv1d using a custom PTX kernel.
    Supports fp16 inputs/outputs, optional bias.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 dilation: int = 1,
                 bias: bool = False):
        self.in_channels  = in_channels
        self.out_channels = out_channels
        self.kernel_size  = kernel_size
        self.stride       = stride
        self.dilation     = dilation

        # Random fp16 weights (out_ch, in_ch, ksize)
        self.weight = torch.randn(out_channels,
                                  in_channels,
                                  kernel_size,
                                  dtype=torch.float16,
                                  device='cuda')
        self.bias = None
        if bias:
            self.bias = torch.randn(out_channels,
                                    dtype=torch.float16,
                                    device='cuda')

        # Load PTX module via harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        """
        Forward pass using the custom PTX kernel.
        x: (batch, in_channels, length), dtype float16, device cuda
        Returns: (batch, out_channels, length_out), dtype float16
        """
        batch, in_ch, len_in = x.shape
        assert in_ch == self.in_channels, "Input channel mismatch"

        # Compute output length exactly as torch.nn.Conv1d does
        len_out = (len_in -
                   (self.kernel_size - 1) * self.dilation -
                   1) // self.stride + 1

        out = torch.empty(batch,
                          self.out_channels,
                          len_out,
                          dtype=torch.float16,
                          device='cuda')

        # Launch configuration: grid (batch, len_out, 1), block (out_channels,1,1)
        grid  = (batch, len_out, 1)
        block = (self.out_channels, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr() if self.bias is not None else 0,
            out.data_ptr(),
            batch,
            in_ch,
            self.out_channels,
            len_in,
            len_out,
            self.kernel_size,
            self.stride,
            self.dilation
        ]

        ptx_launch(self.module, "conv1d_fp16", grid, block, args)

        return out

