PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry conv1d_fp16(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 bias_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 in_channels,
    .param .u32 out_channels,
    .param .u32 length,
    .param .u32 kernel_size,
    .param .u32 stride,
    .param .u32 dilation,
    .param .u32 bias_flag
)
{
    // ----------------------------------------------------------
    // Registers
    // ----------------------------------------------------------
    .reg .b64 %in_ptr, %wt_ptr, %bias_ptr, %out_ptr;
    .reg .u32 %B, %IC, %OC, %L, %K, %S, %D, %bias_f;
    .reg .u32 %tid_x, %ctaid_x, %ntid_x, %gid;
    .reg .u32 %tmp, %tmp1, %tmp2, %tmp3;
    .reg .u32 %Lout, %eff_k, %total;
    .reg .u32 %b, %oc, %ox;
    .reg .u32 %in_x_base;
    .reg .f32 %sum;
    .reg .u32 %ic, %k;
    .reg .b64 %addr_in, %addr_wt, %addr_out;
    .reg .f16 %in_f16, %wt_f16, %bias_f16, %out_f16;
    .reg .f32 %in_f32, %wt_f32, %bias_f32;
    .reg .u32 %out_offset;
    .reg .pred %p_exit, %p_ic_done, %p_k_done, %p_bias;

    // ----------------------------------------------------------
    // Load parameters
    // ----------------------------------------------------------
    ld.param.u64 %in_ptr,    [input_ptr];
    ld.param.u64 %wt_ptr,    [weight_ptr];
    ld.param.u64 %bias_ptr,  [bias_ptr];
    ld.param.u64 %out_ptr,   [output_ptr];
    ld.param.u32 %B,         [batch];
    ld.param.u32 %IC,        [in_channels];
    ld.param.u32 %OC,        [out_channels];
    ld.param.u32 %L,         [length];
    ld.param.u32 %K,         [kernel_size];
    ld.param.u32 %S,         [stride];
    ld.param.u32 %D,         [dilation];
    ld.param.u32 %bias_f,    [bias_flag];

    // ----------------------------------------------------------
    // Compute effective kernel size and output length
    // ----------------------------------------------------------
    mad.lo.u32 %tmp, %D, %K, 0;          // D * K
    sub.u32    %tmp, %tmp, %D;          // D*(K-1)
    add.u32    %eff_k, %tmp, 1;         // D*(K-1)+1

    sub.u32    %tmp, %L, %eff_k;        // L - eff_k
    div.u32    %tmp, %tmp, %S;          // (L - eff_k) / stride
    add.u32    %Lout, %tmp, 1;          // output length

    // total output elements = B * OC * Lout
    mul.lo.u32 %tmp, %B, %OC;
    mul.lo.u32 %total, %tmp, %Lout;

    // ----------------------------------------------------------
    // Thread indices
    // ----------------------------------------------------------
    mov.u32 %tid_x,   %tid.x;
    mov.u32 %ctaid_x, %ctaid.x;
    mov.u32 %ntid_x,  %ntid.x;

    mad.lo.u32 %gid, %ctaid_x, %ntid_x, %tid_x;   // global thread id

    // ----------------------------------------------------------
    // Bounds check
    // ----------------------------------------------------------
    setp.ge.u32 %p_exit, %gid, %total;
    @%p_exit ret;

    // ----------------------------------------------------------
    // Decompose gid -> (b, oc, ox)
    // ----------------------------------------------------------
    rem.u32 %ox, %gid, %Lout;
    div.u32 %tmp, %gid, %Lout;
    rem.u32 %oc, %tmp, %OC;
    div.u32 %b, %tmp, %OC;

    // ----------------------------------------------------------
    // Input base index for this output position
    // ----------------------------------------------------------
    mul.lo.u32 %in_x_base, %ox, %S;   // ox * stride

    // ----------------------------------------------------------
    // Accumulator (float32)
    // ----------------------------------------------------------
    mov.f32 %sum, 0.0;

    // ----------------------------------------------------------
    // Loops over input channels and kernel positions
    // ----------------------------------------------------------
    mov.u32 %ic, 0;
IC_LOOP:
    setp.ge.u32 %p_ic_done, %ic, %IC;
    @%p_ic_done bra IC_END;

    mov.u32 %k, 0;
K_LOOP:
    setp.ge.u32 %p_k_done, %k, %K;
    @%p_k_done bra K_END;

    // ---- input offset ----
    // idx = ((b * IC + ic) * L) + (k * D + in_x_base)
    mul.lo.u32 %tmp1, %b, %IC;
    add.u32    %tmp1, %tmp1, %ic;          // b*IC + ic
    mul.lo.u32 %tmp2, %tmp1, %L;          // *L
    mad.lo.u32 %tmp3, %k, %D, %in_x_base; // k*D + in_x_base
    add.u32 %tmp, %tmp2, %tmp3;           // final linear index

    cvt.u64.u32 %addr_in, %tmp;
    shl.b64 %addr_in, %addr_in, 1;        // fp16 -> 2 bytes
    add.u64 %addr_in, %in_ptr, %addr_in;

    // ---- weight offset ----
    // widx = ((oc * IC + ic) * K) + k
    mul.lo.u32 %tmp1, %oc, %IC;
    add.u32    %tmp1, %tmp1, %ic;
    mul.lo.u32 %tmp2, %tmp1, %K;
    add.u32 %tmp, %tmp2, %k;

    cvt.u64.u32 %addr_wt, %tmp;
    shl.b64 %addr_wt, %addr_wt, 1;
    add.u64 %addr_wt, %wt_ptr, %addr_wt;

    // ---- load, convert, accumulate ----
    ld.global.f16 %in_f16, [%addr_in];
    ld.global.f16 %wt_f16, [%addr_wt];

    cvt.f32.f16 %in_f32, %in_f16;
    cvt.f32.f16 %wt_f32, %wt_f16;

    fma.rn.f32 %sum, %wt_f32, %in_f32, %sum;

    // next k
    add.u32 %k, %k, 1;
    bra K_LOOP;
K_END:
    // next ic
    add.u32 %ic, %ic, 1;
    bra IC_LOOP;
IC_END:

    // ----------------------------------------------------------
    // Add bias if present
    // ----------------------------------------------------------
    setp.ne.u32 %p_bias, %bias_f, 0;
    @%p_bias {
        // bias offset = oc
        cvt.u64.u32 %addr_out, %oc;
        shl.b64 %addr_out, %addr_out, 1;
        add.u64 %addr_out, %bias_ptr, %addr_out;

        ld.global.f16 %bias_f16, [%addr_out];
        cvt.f32.f16 %bias_f32, %bias_f16;
        add.f32 %sum, %sum, %bias_f32;
    }

    // ----------------------------------------------------------
    // Store output (convert back to fp16)
    // ----------------------------------------------------------
    cvt.f16.f32 %out_f16, %sum;

    // output linear index = ((b * OC + oc) * Lout) + ox
    mul.lo.u32 %tmp1, %b, %OC;
    add.u32    %tmp1, %tmp1, %oc;
    mul.lo.u32 %tmp2, %tmp1, %Lout;
    add.u32 %out_offset, %tmp2, %ox;

    cvt.u64.u32 %addr_out, %out_offset;
    shl.b64 %addr_out, %addr_out, 1;
    add.u64 %addr_out, %out_ptr, %addr_out;

    st.global.f16 [%addr_out], %out_f16;

    ret;
}
'''

import torch

class ModelNew:
    """
    Drop‑in replacement for torch.nn.Conv1d using a custom PTX kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride=1,
                 dilation=1, bias=False):
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.dilation = dilation
        self.use_bias = bias

        # Allocate weight tensor (out_channels, in_channels, kernel_size) fp16
        self.weight = torch.empty(out_channels, in_channels, kernel_size,
                                  dtype=torch.float16, device='cuda')
        torch.nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if self.use_bias:
            self.bias = torch.empty(out_channels, dtype=torch.float16,
                                    device='cuda')
            torch.nn.init.zeros_(self.bias)

    def to(self, *args, **kwargs):
        device = kwargs.get('device', None)
        dtype = kwargs.get('dtype', None)

        if args:
            if len(args) >= 1:
                device = args[0]
            if len(args) >= 2:
                dtype = args[1]

        if device is None:
            device = self.weight.device
        if dtype is None:
            dtype = self.weight.dtype

        self.weight = self.weight.to(device=device, dtype=dtype)
        if self.use_bias:
            self.bias = self.bias.to(device=device, dtype=dtype)
        return self

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16, \
            "Input must be CUDA fp16 tensor"
        B, IC, L = x.shape
        assert IC == self.in_channels, \
            f"Expected {self.in_channels} input channels, got {IC}"

        # compute output length
        eff_k = self.dilation * (self.kernel_size - 1) + 1
        Lout = (L - eff_k) // self.stride + 1

        out = torch.empty(B, self.out_channels, Lout,
                          dtype=torch.float16, device='cuda')

        # launch configuration
        threads_per_block = 256
        total_threads = B * self.out_channels * Lout
        blocks = (total_threads + threads_per_block - 1) // threads_per_block

        grid = (blocks, 1, 1)
        block = (threads_per_block, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr() if self.use_bias else 0,
            out.data_ptr(),
            B,
            self.in_channels,
            self.out_channels,
            L,
            self.kernel_size,
            self.stride,
            self.dilation,
            1 if self.use_bias else 0
        ]

        module = ptx_load(PTX_SOURCE)
        ptx_launch(module, "conv1d_fp16", grid, block, args)

        return out

