    fma.rn.f32 %acc, %in_f32, %w_f32, %acc;

    // k++
    add.u32 %k, %k, 1;
    bra.uni K_LOOP;
K_DONE:

    // ic++
    add.u32 %ic, %ic, 1;
    bra.uni IC_LOOP;
IC_DONE:

    // -------------------------------------------------------------
    // write output (FP16)
    // -------------------------------------------------------------
