    .reg .pred p_exit, p_done_kh, p_done_kw, p_oob_y, p_oob_x, p_oob, p_has_bias;

    // ------------------------------------------------------------
    // Load kernel arguments
    // ------------------------------------------------------------
    ld.param.u64 in_ptr,     [input_ptr];
    ld.param.u64 w_ptr,      [weight_ptr];
    ld.param.u64 b_ptr,      [bias_ptr];
    ld.param.u64 out_ptr,    [output_ptr];
    ld.param.u32 B,          [batch];
    ld.param.u32 C,          [channels];
    ld.param.u32 H,          [height];
    ld.param.u32 W,          [width];
    ld.param.u32 K,          [kernel];
    ld.param.u32 S,          [stride];
    ld.param.u32 P,          [padding];
    ld.param.u32 OH,         [out_height];
    ld.param.u32 OW,         [out_width];
    ld.param.u32 has_bias,   [bias_flag];

    // ------------------------------------------------------------
    // Compute global thread id (1‑D grid)
    // ------------------------------------------------------------
    .reg .u32 blockIdxX, threadIdxX, blockDimX;
    mov.u32 blockIdxX, %ctaid.x;
    mov.u32 threadIdxX, %tid.x;
    mov.u32 blockDimX, %ntid.x;
    mul.lo.u32 tmp32, blockIdxX, blockDimX;
    add.u32 tid, tmp32, threadIdxX;

    // total = B*C*OH*OW
    mul.lo.u32 total, B, C;
    mul.lo.u32 total, total, OH;
    mul.lo.u32 total, total, OW;

    setp.ge.u32 p_exit, tid, total;
    @p_exit ret;

