    // Decode linear index -> (n, c, y, x)
    // ------------------------------------------------------------
    mul.lo.u32 CHW, C, OH;
    mul.lo.u32 CHW, CHW, OW;      // C*OH*OW
    mul.lo.u32 OHW, OH, OW;       // OH*OW

    // n = tid / CHW
    div.u32 n, tid, CHW;
    mul.lo.u32 tmp32, n, CHW;
    sub.u32 rem, tid, tmp32;

    // c = rem / OHW
    div.u32 c, rem, OHW;
    mul.lo.u32 tmp32, c, OHW;
    sub.u32 rem2, rem, tmp32;

    // y = rem2 / OW
    div.u32 y, rem2, OW;
    // x = rem2 - y*OW
    mul.lo.u32 tmp32, y, OW;
    sub.u32 x, rem2, tmp32;

    // ------------------------------------------------------------
    // Convolution accumulation (fp32)
    // ------------------------------------------------------------
    mov.f32 acc, 0.0;

    // loop over kernel height
    mov.u32 kh, 0;
KH_LOOP:
    setp.ge.u32 p_done_kh, kh, K;
    @p_done_kh bra KW_DONE;

    // loop over kernel width
    mov.u32 kw, 0;
KW_LOOP:
    setp.ge.u32 p_done_kw, kw, K;
    @p_done_kw bra END_KW;

    // compute input coordinates
    cvt.s32.u32 in_y, y;
    mul.lo.s32 in_y, in_y, S;
    sub.s32 in_y, in_y, P;
    add.s32 in_y, in_y, kh;

    cvt.s32.u32 in_x, x;
    mul.lo.s32 in_x, in_x, S;
    sub.s32 in_x, in_x, P;
    add.s32 in_x, in_x, kw;

