    setp.lt.s32 p_oob_y, in_y, 0;
    setp.ge.s32 p_oob_y, in_y, H;
    setp.lt.s32 p_oob_x, in_x, 0;
    setp.ge.s32 p_oob_x, in_x, W;
    or.pred p_oob, p_oob_y, p_oob_x;
    @p_oob bra NEXT_KW;

    // ------------------------------------------------------------
    // Load input element (fp16 -> fp32)
    // ------------------------------------------------------------
    // idx = (( ( (n*C + c)*H + in_y)*W + in_x) * 2)
    mul.lo.u32 idx, n, C;
    add.u32 idx, idx, c;
    mul.lo.u32 idx, idx, H;
    cvt.u32.s32 tmp32, in_y;
    add.u32 idx, idx, tmp32;
    mul.lo.u32 idx, idx, W;
    cvt.u32.s32 tmp32, in_x;
    add.u32 idx, idx, tmp32;
    mul.lo.u32 idx, idx, 2;

    cvt.u64.u32 addr, idx;
    add.u64 addr, in_ptr, addr;
    ld.global.u16 in_u16, [addr];
    cvt.rn.f16.u16 in_f16, in_u16;          // rounding required for int‑>half
    cvt.rn.f32.f16 in_f32, in_f16;          // half‑>float

    // ------------------------------------------------------------
    // Load weight element (fp16 -> fp32)
    // ------------------------------------------------------------
    // w_idx = ((c*K + kh)*K + kw) * 2
    mul.lo.u32 idx, c, K;
    add.u32 idx, idx, kh;
    mul.lo.u32 idx, idx, K;
    add.u32 idx, idx, kw;
    mul.lo.u32 idx, idx, 2;

    cvt.u64.u32 addr, idx;
    add.u64 addr, w_ptr, addr;
    ld.global.u16 w_u16, [addr];
    cvt.rn.f16.u16 w_f16, w_u16;
    cvt.rn.f32.f16 w_f32, w_f16;

    // accumulate
    fma.rn.f32 acc, in_f32, w_f32, acc;

NEXT_KW:
    add.u32 kw, kw, 1;
    bra KW_LOOP;

END_KW:
    add.u32 kh, kh, 1;
    bra KH_LOOP;

KW_DONE:
    // ------------------------------------------------------------
    // Add bias if present
    // ------------------------------------------------------------
    setp.eq.u32 p_has_bias, has_bias, 0;
    @p_has_bias bra STORE;          // no bias

    // bias offset = c * 2
    mul.lo.u32 idx, c, 2;
    cvt.u64.u32 addr, idx;
    add.u64 addr, b_ptr, addr;
    ld.global.u16 b_u16, [addr];
    cvt.rn.f16.u16 b_f16, b_u16;
    cvt.rn.f32.f16 b_f32, b_f16;
    add.f32 acc, acc, b_f32;

STORE:
    // ------------------------------------------------------------
    // Write output (fp16)
    // ------------------------------------------------------------
    cvt.rn.f16.f32 out_f16, acc;
    cvt.rn.u16.f16 out_u16, out_f16;

    // out_idx = (( ( (n*C + c)*OH + y)*OW + x) * 2)
    mul.lo.u32 idx, n, C;
    add.u32 idx, idx, c;
    mul.lo.u32 idx, idx, OH;
    add.u32 idx, idx, y;
    mul.lo.u32 idx, idx, OW;
    add.u32 idx, idx, x;
    mul.lo.u32 idx, idx, 2;

    cvt.u64.u32 addr, idx;
    add.u64 addr, out_ptr, addr;
    st.global.u16 [addr], out_u16;

    ret;
}
