import torch
import torch.nn as nn
# The harness is expected to provide these at runtime:
# from ptx_harness import ptx_load, ptx_launch
from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    """
    Depthwise 2D convolution (fp16 I/O) using a custom PTX kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.bias_flag = bias

        # weight shape: (C, K, K) stored as contiguous fp16
        self.weight = nn.Parameter(
            torch.randn(in_channels, kernel_size, kernel_size,
                        dtype=torch.float16, device='cuda')
        )
        if bias:
            self.bias = nn.Parameter(
                torch.randn(in_channels, dtype=torch.float16, device='cuda')
            )
        else:
            self.register_parameter('bias', None)

        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not (x.is_cuda and x.dtype == torch.float16):
            raise RuntimeError("Input must be a CUDA fp16 tensor")
        B, C, H, W = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding

        OH = (H + 2 * P - K) // S + 1
        OW = (W + 2 * P - K) // S + 1

        out = torch.empty(B, C, OH, OW, dtype=torch.float16, device=x.device)

        total = B * C * OH * OW
        threads_per_block = 256
        blocks = (total + threads_per_block - 1) // threads_per_block

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr() if self.bias_flag else 0,
            out.data_ptr(),
            B, C, H, W,
            K, S, P,
            OH, OW,
            int(self.bias_flag)
        ]

        ptx_launch(self.module, "depthwise_conv2d_fp16", blocks, threads_per_block, args)

        return out

