    ld.global.u32 %C, [%addr];
    // H
    add.u64 %addr, %p_ptr, 8;
    ld.global.u32 %H, [%addr];
    // W
    add.u64 %addr, %p_ptr, 12;
    ld.global.u32 %W, [%addr];
    // K
    add.u64 %addr, %p_ptr, 16;
    ld.global.u32 %K, [%addr];
    // stride
    add.u64 %addr, %p_ptr, 20;
    ld.global.u32 %stride, [%addr];
    // pad
    add.u64 %addr, %p_ptr, 24;
    ld.global.u32 %pad, [%addr];
    // H_out
    add.u64 %addr, %p_ptr, 28;
    ld.global.u32 %Hout, [%addr];
    // W_out
    add.u64 %addr, %p_ptr, 32;
    ld.global.u32 %Wout, [%addr];

