    // Thread / block indices
    // --------------------------------------------------------
    .reg .u32 %tid_x, %tid_y;
    .reg .u32 %bid_x, %bid_y, %bid_z;
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;
    mov.u32 %bid_z, %ctaid.z;

