    .reg .u32 %out_x, %out_y;
    mad.lo.u32 %out_x, %bid_x, 16, %tid_x;   // out_x = bid_x*16 + tid_x
    mad.lo.u32 %out_y, %bid_y, 16, %tid_y;   // out_y = bid_y*16 + tid_y

