    div.u32 %tmp, %idx, %C;              // tmp = batch
    mov.u32 %batch, %tmp;
    mul.lo.u32 %tmp, %batch, %C;
    sub.u32 %channel, %idx, %tmp;        // channel = idx - batch*C

