    .reg .u64 %addr_in, %addr_w, %addr_out;
    .reg .u16 %val_in_u16, %val_w_u16, %val_out_u16;
    .reg .f16 %val_in, %val_w, %val_out_f16;
    .reg .f32 %val_in_f32, %val_w_f32;

