KY_LOOP:
    setp.ge.u32 %p_outx, %ky, %K;       // reuse %p_outx as temp
    @%p_outx bra KX_DONE;               // exit if ky >= K

    mov.u32 %kx, 0;
KX_LOOP:
    setp.ge.u32 %p_outy, %kx, %K;       // reuse %p_outy as temp
    @%p_outy bra KY_INC;                // next ky if kx >= K

