    setp.ge.s32 %p_ge0x, %in_x, 0;
    setp.lt.s32 %p_ltWx, %in_x, %W;
    setp.ge.s32 %p_ge0y, %in_y, 0;
    setp.lt.s32 %p_ltHy, %in_y, %H;
    and.pred %p_valid, %p_ge0x, %p_ltWx;
    and.pred %p_valid, %p_valid, %p_ge0y;
    and.pred %p_valid, %p_valid, %p_ltHy;
    @!%p_valid bra KX_INC;              // skip if out of bounds

