    mul.lo.u32 %tmp, %batch, %C;
    add.u32 %tmp, %tmp, %channel;          // tmp = batch*C + channel
    mul.lo.u32 %tmp, %tmp, %H;
    cvt.u32.s32 %tmp_s, %in_y;
    add.u32 %tmp, %tmp, %tmp_s;
    mul.lo.u32 %tmp, %tmp, %W;
    cvt.u32.s32 %tmp_s, %in_x;
    add.u32 %tmp, %tmp, %tmp_s;
    mul.wide.u32 %addr_in, %tmp, 2;        // *2 for fp16
    add.u64 %addr_in, %addr_in, %x_ptr;
    ld.global.u16 %val_in_u16, [%addr_in];
    mov.b16 %val_in, %val_in_u16;          // reinterpret bits as fp16

    // --------------------------------------------------------
    // Load weight element (fp16)
    // layout: (C, K, K) -> offset = (channel*K + ky)*K + kx
    // --------------------------------------------------------
    mul.lo.u32 %tmp, %channel, %K;
    add.u32 %tmp, %tmp, %ky;
    mul.lo.u32 %tmp, %tmp, %K;
    add.u32 %tmp, %tmp, %kx;
    mul.wide.u32 %addr_w, %tmp, 2;
    add.u64 %addr_w, %addr_w, %w_ptr;
    ld.global.u16 %val_w_u16, [%addr_w];
    mov.b16 %val_w, %val_w_u16;            // reinterpret bits as fp16

