    // --------------------------------------------------------
    cvt.f32.f16 %val_in_f32, %val_in;          // half -> float
    cvt.f32.f16 %val_w_f32,  %val_w;           // half -> float
    fma.rn.f32 %acc, %val_in_f32, %val_w_f32, %acc;

