        stride = self.stride
        pad = self.padding

        H_out = (H + 2 * pad - K) // stride + 1
        W_out = (W + 2 * pad - K) // stride + 1

        y = torch.empty(N, C, H_out, W_out,
                        dtype=torch.float16,
                        device='cuda')

