                (H_out + 15) // 16,
                N * C)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            y.data_ptr(),
            params.data_ptr()
        ]

        ptx_launch(self.module,
                   "depthwise_conv_fp16",
                   grid,
                   block,
                   args)

        return y

