    add.s32 %x, %x, %kw;
    sub.s32 %x, %x, %P;

    // ---- guard against padding (skip if out of bounds) ----
    .reg .pred %p_valid;
    setp.ge.s32 %p_valid, %y, 0;
    @!%p_valid bra kw_inc;
    setp.lt.s32 %p_valid, %y, %IH;
    @!%p_valid bra kw_inc;
    setp.ge.s32 %p_valid, %x, 0;
    @!%p_valid bra kw_inc;
    setp.lt.s32 %p_valid, %x, %IW;
    @!%p_valid bra kw_inc;

    // ---- load input value (fp16) ----
    .reg .u32 %in_off;
    // offset = ((b*C + c)*IH + y)*IW + x
    mul.lo.u32 %in_off, %b, %C;
    add.u32 %in_off, %in_off, %c;
    mul.lo.u32 %in_off, %in_off, %IH;
    add.u32 %in_off, %in_off, %y;
    mul.lo.u32 %in_off, %in_off, %IW;
    add.u32 %in_off, %in_off, %x;

    .reg .u64 %addr_in;
    cvt.u64.u32 %addr_in, %in_off;
    mul.lo.u64 %addr_in, %addr_in, 2;          // fp16 size
    add.u64 %addr_in, %in_ptr64, %addr_in;

    .reg .f16 %inp;
    ld.global.f16 %inp, [%addr_in];

    // ---- load weight value (fp16) ----
    .reg .u32 %w_off;
    // weight layout: (C, K, K) → offset = ((c*K) + kh)*K + kw
    mul.lo.u32 %w_off, %c, %K;
    mul.lo.u32 %w_off, %w_off, %K;            // c*K*K
    mul.lo.u32 %tmp1, %kh, %K;
    add.u32 %w_off, %w_off, %tmp1;
    add.u32 %w_off, %w_off, %kw;

    .reg .u64 %addr_w;
    cvt.u64.u32 %addr_w, %w_off;
    mul.lo.u64 %addr_w, %addr_w, 2;
    add.u64 %addr_w, %weight_ptr64, %addr_w;

    .reg .f16 %wgt;
    ld.global.f16 %wgt, [%addr_w];

