    // Store output (fp16)
    // --------------------------------------------------------------
    .reg .f16 %out_val;
    cvt.rn.f16.f32 %out_val, %acc;

    // linear offset for output: ((b*C + c)*OH + oh)*OW + ow
    .reg .u32 %out_off;
    mul.lo.u32 %out_off, %b, %C;
    add.u32 %out_off, %out_off, %c;
    mul.lo.u32 %out_off, %out_off, %OH;
    add.u32 %out_off, %out_off, %oh;
    mul.lo.u32 %out_off, %out_off, %OW;
    add.u32 %out_off, %out_off, %ow;

    .reg .u64 %addr_out;
    cvt.u64.u32 %addr_out, %out_off;
    mul.lo.u64 %addr_out, %addr_out, 2;
    add.u64 %addr_out, %out_ptr64, %addr_out;

    st.global.f16 [%addr_out], %out_val;

    ret;
