class ModelNew:
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, bias: bool = False):
        self.in_channels = in_channels
        self.k = kernel_size
        self.stride = stride
        self.padding = padding
        self.bias = bias
        # Load PTX module via harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x, weight, bias=None):
        """
        x      : torch.Tensor (B, C, H, W)  dtype=float16
        weight : torch.Tensor (C, K, K)    dtype=float16
        bias   : torch.Tensor (C,)        dtype=float16 (optional)
        Returns torch.Tensor (B, C, H_out, W_out) dtype=float16
        """
        import torch

        B, C, H, W = x.shape
        K = self.k
        out_h = (H + 2 * self.padding - K) // self.stride + 1
        out_w = (W + 2 * self.padding - K) // self.stride + 1

        out = torch.empty((B, C, out_h, out_w), dtype=torch.float16, device=x.device)

        args = [
            out.data_ptr(),
            x.data_ptr(),
            weight.data_ptr(),
            B, C, H, W, out_h, out_w, K, self.stride, self.padding
        ]

        total = B * C * out_h * out_w
        block = (256, 1, 1)
        grid = ((total + block[0] - 1) // block[0], 1, 1)

        ptx_launch(self.module, "depthwise_conv", grid, block, args)

        if self.bias and bias is not None:
            out += bias.view(1, C, 1, 1)

        return out

