    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 channels,
    .param .u32 height,
    .param .u32 width,
    .param .u32 ksize,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 out_h,
    .param .u32 out_w
)
