    // Thread/block mapping
    //   blockIdx.x  -> batch index (b)
    //   blockIdx.y  -> channel index (c)
    //   blockIdx.z  -> output pixel linear index (p = out_y * out_w + out_x)
    // -----------------------------------------------------------------
    .reg .u32 %b_idx, %c_idx, %pix_idx;
    mov.u32 %b_idx, %ctaid.x;
    mov.u32 %c_idx, %ctaid.y;
    mov.u32 %pix_idx, %ctaid.z;

