    // Load kernel parameters
    // -----------------------------------------------------------------
    .reg .u64 %in_ptr, %w_ptr, %out_ptr;
    .reg .u32 %B, %C, %H, %W, %K, %S, %P, %OH, %OW;
    ld.param.u64 %in_ptr,   [input_ptr];
    ld.param.u64 %w_ptr,    [weight_ptr];
    ld.param.u64 %out_ptr,  [output_ptr];
    ld.param.u32 %B,        [batch];
    ld.param.u32 %C,        [channels];
    ld.param.u32 %H,        [height];
    ld.param.u32 %W,        [width];
    ld.param.u32 %K,        [ksize];
    ld.param.u32 %S,        [stride];
    ld.param.u32 %P,        [padding];
    ld.param.u32 %OH,       [out_h];
    ld.param.u32 %OW,       [out_w];

    // -----------------------------------------------------------------
    // Derive output coordinates (out_y, out_x)
    // -----------------------------------------------------------------
    .reg .u32 %out_y, %out_x, %tmp;
    div.u32 %out_y, %pix_idx, %OW;          // out_y = pix_idx / out_w
    mul.lo.u32 %tmp, %out_y, %OW;
    sub.u32 %out_x, %pix_idx, %tmp;         // out_x = pix_idx - out_y*out_w

    // -----------------------------------------------------------------
    // Compute origin of receptive field in input
    // -----------------------------------------------------------------
    .reg .s32 %in_y0, %in_x0;
    .reg .s32 %S_s, %P_s;
    cvt.s32.u32 %S_s, %S;
    cvt.s32.u32 %P_s, %P;
    mul.lo.s32 %in_y0, %out_y, %S_s;
    mul.lo.s32 %in_x0, %out_x, %S_s;
    sub.s32 %in_y0, %in_y0, %P_s;
    sub.s32 %in_x0, %in_x0, %P_s;

