    // Accumulator (float32)
    // -----------------------------------------------------------------
    .reg .f32 %acc;
    mov.f32 %acc, 0.0f;

    // -----------------------------------------------------------------
    // Loop over kernel rows (ky) and columns (kx)
    // -----------------------------------------------------------------
    .reg .u32 %ky, %kx;
    .reg .s32 %in_y, %in_x;
    .reg .pred %skip;
    .reg .u32 %input_idx, %weight_idx, %tmp32;
    .reg .u64 %addr_off;
    .reg .f16 %i_half, %w_half;
    .reg .f32 %i_f, %w_f;

    mov.u32 %ky, 0;
ky_loop:
    setp.ge.u32 %skip, %ky, %K;
    @%skip bra ky_done;

    mov.u32 %kx, 0;
kx_loop:
    setp.ge.u32 %skip, %kx, %K;
    @%skip bra kx_done;

    // input coordinates for this kernel element
    add.s32 %in_y, %in_y0, %ky;
    add.s32 %in_x, %in_x0, %kx;

    // boundary check – skip if out of bounds
    setp.lt.s32 %skip, %in_y, 0;
    @%skip bra kx_inc;
    setp.ge.s32 %skip, %in_y, %H;
    @%skip bra kx_inc;
    setp.lt.s32 %skip, %in_x, 0;
    @%skip bra kx_inc;
    setp.ge.s32 %skip, %in_x, %W;
    @%skip bra kx_inc;

