    mul.lo.u32 %tmp32, %b_idx, %C;          // b*C
    add.u32 %tmp32, %tmp32, %c_idx;        // b*C + c
    mul.lo.u32 %tmp32, %tmp32, %H;         // *H
    cvt.u32.s32 %tmp, %in_y;
    add.u32 %tmp32, %tmp32, %tmp;          // + in_y
    mul.lo.u32 %tmp32, %tmp32, %W;         // *W
    cvt.u32.s32 %tmp, %in_x;
    add.u32 %input_idx, %tmp32, %tmp;      // + in_x

    // linear weight index = c*K*K + ky*K + kx
    mul.lo.u32 %tmp32, %c_idx, %K;
    mul.lo.u32 %tmp32, %tmp32, %K;         // c*K*K
    mul.lo.u32 %tmp, %ky, %K;
    add.u32 %tmp, %tmp, %kx;               // ky*K + kx
    add.u32 %weight_idx, %tmp32, %tmp;

    // convert to byte offsets (fp16 = 2 bytes) and load
    cvt.u64.u32 %addr_off, %input_idx;
    shl.b64 %addr_off, %addr_off, 1;
    ld.global.f16 %i_half, [%in_ptr + %addr_off];

    cvt.u64.u32 %addr_off, %weight_idx;
    shl.b64 %addr_off, %addr_off, 1;
    ld.global.f16 %w_half, [%w_ptr + %addr_off];

