    // Write output (fp16)
    // -----------------------------------------------------------------
    // linear output index = ((b*C + c)*OH + out_y)*OW + out_x
    mul.lo.u32 %tmp32, %b_idx, %C;
    add.u32 %tmp32, %tmp32, %c_idx;
    mul.lo.u32 %tmp32, %tmp32, %OH;
    add.u32 %tmp32, %tmp32, %out_y;
    mul.lo.u32 %tmp32, %tmp32, %OW;
    add.u32 %tmp32, %tmp32, %out_x;

    cvt.u64.u32 %addr_off, %tmp32;
    shl.b64 %addr_off, %addr_off, 1;   // fp16 element size

    .reg .f16 %out_half;
    cvt.rn.f16.f32 %out_half, %acc;
    st.global.f16 [%out_ptr + %addr_off], %out_half;

