import torch
from ptx_harness import ptx_load, ptx_launch  # provided by the evaluation harness

class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.bias = bias

        # depthwise weight tensor: (C, K, K) in fp16
        self.weight = torch.nn.Parameter(
            torch.randn(in_channels, kernel_size, kernel_size,
                        dtype=torch.float16, device='cuda')
        )
        if bias:
            self.bias_param = torch.nn.Parameter(
                torch.randn(in_channels, dtype=torch.float16, device='cuda')
            )
        else:
            self.bias_param = None

        # load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch, C, H, W = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding

        out_h = (H + 2 * P - K) // S + 1
        out_w = (W + 2 * P - K) // S + 1

        out = torch.empty(batch, C, out_h, out_w,
                          dtype=torch.float16, device='cuda')

        # launch configuration: one thread per output element
        grid = (batch, C, out_h * out_w)
        block = (1, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            out.data_ptr(),
            batch,
            C,
            H,
            W,
            K,
            S,
            P,
            out_h,
            out_w
        ]

        ptx_launch(self.module, "depthwise_conv", grid, block, args)

        if self.bias:
            out = out + self.bias_param.view(1, -1, 1, 1)

        return out

