PTX_SOURCE = r'''
.version 7.4
.target sm_80
.address_size 64

.visible .entry sdpa_kernel(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 Out_ptr,
    .param .u32 B,
    .param .u32 H,
    .param .u32 S,
    .param .u32 D
)
{
    // -------------------------------------------------------------
    // Load parameters
    // -------------------------------------------------------------
    .reg .u64 %ptrQ, %ptrK, %ptrV, %ptrO;
    .reg .u32 %B, %H, %S, %D;
    ld.param.u64 %ptrQ, [Q_ptr];
    ld.param.u64 %ptrK, [K_ptr];
    ld.param.u64 %ptrV, [V_ptr];
    ld.param.u64 %ptrO, [Out_ptr];
    ld.param.u32 %B, [B];
    ld.param.u32 %H, [H];
    ld.param.u32 %S, [S];
    ld.param.u32 %D, [D];

    // -------------------------------------------------------------
    // Thread / block indices
    // -------------------------------------------------------------
    .reg .u32 %ctaid_x, %ctaid_y, %ctaid_z;
    .reg .u32 %tid_x, %ntid_x;
    mov.u32 %ctaid_x, %ctaid.x;
    mov.u32 %ctaid_y, %ctaid.y;
    mov.u32 %ctaid_z, %ctaid.z;
    mov.u32 %tid_x,   %tid.x;
    mov.u32 %ntid_x, %ntid.x;

    // -------------------------------------------------------------
    // Scaling factor 1/sqrt(D)   (fp32)
    // -------------------------------------------------------------
    .reg .f32 %scale, %D_f32;
    cvt.f32.u32 %D_f32, %D;
    rsqrt.approx.f32 %scale, %D_f32;

    // -------------------------------------------------------------
    // Compute row index = ((b*H + h)*S + i)
    // -------------------------------------------------------------
    .reg .u32 %b, %h, %i;
    mov.u32 %b, %ctaid_x;
    mov.u32 %h, %ctaid_y;
    mov.u32 %i, %ctaid_z;

    .reg .u32 %tmp1, %tmp2, %row_idx;
    mad.lo.u32 %tmp1, %b, %H, %h;          // b*H + h
    mul.lo.u32 %tmp2, %tmp1, %S;          // (b*H+h)*S
    add.u32 %row_idx, %tmp2, %i;          // ((b*H+h)*S + i)

    // byte offset of a row (row_idx * D * 2)
    .reg .u64 %row_offset_bytes;
    mul.wide.u32 %row_offset_bytes, %row_idx, %D; // elements
    shl.b64 %row_offset_bytes, %row_offset_bytes, 1; // bytes (fp16)

    // -------------------------------------------------------------
    // Loop over output columns d (each thread handles strided d)
    // -------------------------------------------------------------
    .reg .u32 %d;
    mov.u32 %d, %tid_x;   // start column

    .reg .pred %p_done_d, %p_done_j, %p_done_k, %p_gt;

LOOP_D:
    setp.ge.u32 %p_done_d, %d, %D;
    @%p_done_d bra DONE;

    // ---------------------------------------------------------
    // Find max score over j
    // ---------------------------------------------------------
    .reg .f32 %max_score, %dot, %q_f, %k_f;
    mov.f32 %max_score, -3.402823466e38;   // -FLT_MAX

    .reg .u32 %j;
    mov.u32 %j, 0;

LOOP_J_MAX:
    setp.ge.u32 %p_done_j, %j, %S;
    @%p_done_j bra END_J_MAX;

    // dot product Q[i,:] * K[j,:]
    mov.f32 %dot, 0.0;
    .reg .u32 %col;
    mov.u32 %col, 0;

LOOP_K_MAX:
    setp.ge.u32 %p_done_k, %col, %D;
    @%p_done_k bra END_K_MAX;

    // address for Q[i,col]
    .reg .u64 %addrQ, %addrK;
    .reg .u64 %col_offset_bytes;
    mul.wide.u32 %col_offset_bytes, %col, 2;   // bytes
    add.u64 %addrQ, %ptrQ, %row_offset_bytes;
    add.u64 %addrQ, %addrQ, %col_offset_bytes;

    // load Q[i,col] (fp16) -> fp32
    .reg .f16 %q_f16;
    ld.global.f16 %q_f16, [%addrQ];
    cvt.f32.f16 %q_f, %q_f16;

