    // Compute sum of exp(dot - max)
    // ---------------------------------------------------------
    .reg .f32 %sum_exp, %exp_val, %diff;
    mov.f32 %sum_exp, 0.0;
    mov.u32 %j, 0;

    // constant log2(e)
    .reg .f32 %log2e;
    mov.f32 %log2e, 1.4426950408889634;

LOOP_J_EXP:
    setp.ge.u32 %p_done_j, %j, %S;
    @%p_done_j bra END_J_EXP;

    // recompute dot for this j
    mov.f32 %dot, 0.0;
    mov.u32 %col, 0;

LOOP_K_EXP:
    setp.ge.u32 %p_done_k, %col, %D;
    @%p_done_k bra END_K_EXP;

    // Q[i,col]
    mul.wide.u32 %col_offset_bytes, %col, 2;
    add.u64 %addrQ, %ptrQ, %row_offset_bytes;
    add.u64 %addrQ, %addrQ, %col_offset_bytes;
    ld.global.f16 %q_f16, [%addrQ];
    cvt.f32.f16 %q_f, %q_f16;

    // K[j,col]
    mad.lo.u32 %rowK_idx, %tmp1, %S, %j;
    mul.wide.u32 %rowK_offset_bytes, %rowK_idx, %D;
    shl.b64 %rowK_offset_bytes, %rowK_offset_bytes, 1;
    add.u64 %addrK, %ptrK, %rowK_offset_bytes;
    add.u64 %addrK, %addrK, %col_offset_bytes;
    ld.global.f16 %k_f16, [%addrK];
    cvt.f32.f16 %k_f, %k_f16;

    fma.rn.f32 %dot, %q_f, %k_f, %dot;

    add.u32 %col, %col, 1;
    bra LOOP_K_EXP;
END_K_EXP:

    mul.f32 %dot, %dot, %scale;
    sub.f32 %diff, %dot, %max_score;
    mul.f32 %diff, %diff, %log2e;
    ex2.approx.f32 %exp_val, %diff;    // exp(diff)
    add.f32 %sum_exp, %sum_exp, %exp_val;

    add.u32 %j, %j, 1;
    bra LOOP_J_EXP;
END_J_EXP:

    // ---------------------------------------------------------
    // Compute final output element out[b,h,i,d]
    // ---------------------------------------------------------
    .reg .f32 %out_val;
    mov.f32 %out_val, 0.0;
    mov.u32 %j, 0;

LOOP_J_OUT:
    setp.ge.u32 %p_done_j, %j, %S;
    @%p_done_j bra END_J_OUT;

    // recompute dot for this j
    mov.f32 %dot, 0.0;
    mov.u32 %col, 0;

LOOP_K_OUT:
    setp.ge.u32 %p_done_k, %col, %D;
    @%p_done_k bra END_K_OUT;

    // Q[i,col]
    mul.wide.u32 %col_offset_bytes, %col, 2;
    add.u64 %addrQ, %ptrQ, %row_offset_bytes;
    add.u64 %addrQ, %addrQ, %col_offset_bytes;
    ld.global.f16 %q_f16, [%addrQ];
    cvt.f32.f16 %q_f, %q_f16;

    // K[j,col]
    mad.lo.u32 %rowK_idx, %tmp1, %S, %j;
    mul.wide.u32 %rowK_offset_bytes, %rowK_idx, %D;
    shl.b64 %rowK_offset_bytes, %rowK_offset_bytes, 1;
    add.u64 %addrK, %ptrK, %rowK_offset_bytes;
    add.u64 %addrK, %addrK, %col_offset_bytes;
    ld.global.f16 %k_f16, [%addrK];
    cvt.f32.f16 %k_f, %k_f16;

    fma.rn.f32 %dot, %q_f, %k_f, %dot;

    add.u32 %col, %col, 1;
    bra LOOP_K_OUT;
END_K_OUT:

    mul.f32 %dot, %dot, %scale;
    sub.f32 %diff, %dot, %max_score;
    mul.f32 %diff, %diff, %log2e;
    ex2.approx.f32 %exp_val, %diff;          // numerator
    div.rn.f32 %exp_val, %exp_val, %sum_exp; // weight

    // load V[j,d]
    .reg .u64 %addrV;
    .reg .f16 %v_f16;
    mad.lo.u32 %rowK_idx, %tmp1, %S, %j;      // same row index as K
    mul.wide.u32 %rowK_offset_bytes, %rowK_idx, %D;
    shl.b64 %rowK_offset_bytes, %rowK_offset_bytes, 1;
    mul.wide.u32 %col_offset_bytes, %d, 2;
    add.u64 %addrV, %ptrV, %rowK_offset_bytes;
    add.u64 %addrV, %addrV, %col_offset_bytes;
    ld.global.f16 %v_f16, [%addrV];
    .reg .f32 %v_f;
    cvt.f32.f16 %v_f, %v_f16;

    // accumulate weighted value
    fma.rn.f32 %out_val, %exp_val, %v_f, %out_val;

    add.u32 %j, %j, 1;
    bra LOOP_J_OUT;
END_J_OUT:

    // ---------------------------------------------------------
    // Store result (fp32 -> fp16)
    // ---------------------------------------------------------
    .reg .f16 %out_f16;
    .reg .u64 %addrOut;
    cvt.f16.f32 %out_f16, %out_val;

    mul.wide.u32 %col_offset_bytes, %d, 2;
    add.u64 %addrOut, %ptrO, %row_offset_bytes;
    add.u64 %addrOut, %addrOut, %col_offset_bytes;
    st.global.f16 [%addrOut], %out_f16;

    // Next column for this thread
    add.u32 %d, %d, %ntid_x;
    bra LOOP_D;

DONE:
    ret;
}
