        K = K.to(torch.float16).cuda()
        V = V.to(torch.float16).cuda()

        out = torch.empty_like(V)

        B, H, S, D = Q.shape

        threads_per_block = 256
        grid = (B, H, S)
        block = (threads_per_block, 1, 1)

        args = [
            Q.data_ptr(),
            K.data_ptr(),
            V.data_ptr(),
            out.data_ptr(),
            int(B),
            int(H),
            int(S),
            int(D)
        ]

        ptx_launch(self.module, "sdpa_kernel", grid, block, args)

        return out

