import torch
import triton
import triton.language as tl

@triton.jit
def scan_kernel(
    input_ptr, output_ptr,
    N,
    BLOCK_SIZE: tl.constexpr
):
    # Block index
    block_idx = tl.program_id(0)
    # Starting position for this block
    start_pos = block_idx * BLOCK_SIZE

    # Load data into registers
    x = tl.load(input_ptr + start_pos + tl.arange(0, BLOCK_SIZE))
    x = x.to(tl.float32)

    # Forward scan in shared memory
    # First, compute inclusive prefix sum
    shared_data = tl.zeros((BLOCK_SIZE,), dtype=tl.float32)
    for i in range(BLOCK_SIZE):
        if i == 0:
            shared_data[i] = x[i]
        else:
            shared_data[i] = shared_data[i-1] + x[i]
        tl.store(output_ptr + start_pos + i, shared_data[i].to(tl.float16))

def scan_triton(x):
    output = torch.empty_like(x)
    N = x.numel()
    BLOCK_SIZE = 1024

    grid = (triton.cdiv(N, BLOCK_SIZE),)

    scan_kernel[grid](
        x.data_ptr(), output.data_ptr(),
        N,
        BLOCK_SIZE=BLOCK_SIZE
    )

    return output

class ModelNew(torch.nn.Module):
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x):
        # Handle multi-dimensional case by flattening along the scan dimension
        original_shape = x.shape
        if self.dim < 0:
            dim = len(original_shape) + self.dim
        else:
            dim = self.dim

        # For a 2D case like (batch_size, seq_len) with dim=1
        # We can do the scan along the last dimension directly
        if len(original_shape) == 2 and dim == 1:
            return scan_triton(x)
        else:
            # For other cases, use PyTorch's cumsum to maintain correctness
            return torch.cumsum(x, dim=self.dim)

